window.POETRY_REGISTER("v4-poems-685.js",{"records":[["江南好，西去是嘉禾。\n千尺画楼寒树外，断烟依旧锁南河。\n双桨一渔蓑。",""],["小阁廉纤微雨。\n金鸭水沉一炷。\n临别苦丁宁，携手画栏深处。\n人去。\n人去。\n长日满庭飞絮。",""],["帘外鸦啼风细，落月春芜满地。\n香尽画楼闲，知道玉人沉醉。\n君记。\n君记。\n正是消魂天气。",""],["山鸟啼。\n水鸟啼。\n水阔山青路欲迷。\n愁他双桨迟。\n酒醒时。\n梦醒时。\n花又无聊月又低。\n莫教羌管吹。",""],["梅花天。\n杏花天。\n春在前溪梅杏边。\n花开两岸烟。\n风满船。\n雨满船。\n风雨寒灯夕不眠。\n愁来更可怜。",""],["高楼酒一卮，肠断分离处。\n前夜秣陵花，今夜潇湘雨。\n独倚木兰桡，酒醒山无数。\n试问此时心，心似秋莲苦。",""],["愁绝萧郎音信稀。\n梦中归。\n画帘风动六铢衣。\n篆烟微。\n小园闲却秋千索。\n桐花落。\n最怜白昼燕双飞。\n怨春晖。",""],["绿蕉深处，又见一钩蟾影。\n绣帘垂。\n袅袅莲三寸，亭亭玉一枝。\n相思情似絮，相见泪如丝。\n私语屏山曲，立多时。",""],["泉冷云深，仙翁静爱青山宿。\n晓松如沐。\n夕涧幽禽浴。\n舴艋归来，独对群峰簇。\n炉烟馥。\n满庭黄菊。\n帘卷秋塘绿。","泉冷云深，仙翁静爱青山宿。\n晓松如沐。\n夕涧幽禽浴。\n舴艋归来，独对群峰簇。\n炉烟馥。\n满庭黄菊。\n帘捲秋塘绿。"],["落日凉飔曲槛南。\n红蕉初展燕呢喃。\n碧树冰簟酒微酣。\n茉莉暗藏镂玉枕，葡萄轻染薄罗衫。\n笑偎莲脸不知惭。",""],["绛蜡春醒晕粉腮。\n画栏斜凭溜金钗。\n手拈梅豆要郎猜。\n鸭绿双垂鸳尾带，猩红一捏凤头鞋。\n澹蟾偷影觑阳台。",""],["脉脉闲情似水流。\n暮江人上木兰舟。\n画桥西去笛声幽。\n客醉夕阳芳草路，鸟啼寒食杏花楼。\n澹烟微雨一春愁。",""],["侧侧东风涨绿池。\n燕娇莺嫩夕阳迟。\n踏青天气斗茶时。\n绮席兴酣银凿落，琐窗肠断玉参差。\n画船归去雨丝丝。",""],["孤馆寒更怅独眠。\n那人疑在绣衾边。\n欢情别恨两缠绵。\n记得夜深娇未睡，背灯无语立床前。\n鬓松腰嫩最堪怜。",""],["细雨屏山掩绿苔。\n侍儿私语傍妆台。\n瞢腾春醉眼慵开。\n鸳枕暖偎红粉颊，麝煤香浸绣弓鞋。\n翠帏风动梦初来。",""],["斗草归来雨湿衣，画帘春静蝶双飞。\n黛螺高绾绣裙低。\n好梦每嫌娇鸟唤，幽情只许侍儿知。\n小窗灯烬忆人时。",""],["羁思春情两不堪。\n嫩寒微雨透征衫。\n翠堤迢递路曾谙。\n村寺日斜山泼黛，野塘风静水挼蓝。\n断肠芳草遍江南。",""],["竹坞烟深禽影偏。\n溪桥花落浪痕圆。\n澹云芳草夹衣天。\n旧院碧桃人似梦，小窗红烛夜如年。\n坐残银漏阿谁怜。",""],["簏簌晴窗花影垂。\n新茶泼雨泻缥瓷。\n偶拈银管蘸琉璃。\n青簇晚山轻似髻，绿浮春水细于丝。\n江南小景胜徐熙。",""],["百宝栏前暑气清。\n砑罗衫薄茜裙轻。\n枕痕一线梦初醒。\n闲看绿窗消蕙炷，自描红玉作棋枰。\n重围谁为解刘生。",""],["细楷吴绫点漆螺。\n微吟钗溜绿云窝。\n年来诗句断肠多。\n对镜漫裁金缕曲，背人偷和竹枝歌。\n春心一寸奈愁何。",""],["静院幽思半不禁。\n冰泉满匣泻瑶琴。\n阿谁知得此时心。\n碧沼雨馀啼鸟寂，绣帘风细落花深。\n小窗弹罢独沉吟。",""],["芳塘弱柳波纹碧。\n画楼香雨花光湿。\n梦断晓钟残。\n床堆绣被闲。\n漫将沉水爇。\n心似丁香结。\n啮指暗寻思。\n相逢定几时。",""],["画帘簌簌梧桐雨，晚妆初罢娇无语。\n灯下强偎人，罗衫涴酒痕。\n肌香温绣被。\n蹙损眉山翠。\n未惯是双眠。\n须郎着意牵。",""],["草堂人去烟光夕。\n藕花残雨银塘碧。\n蝶梦此时幽。\n蝉吟一院秋。\n庭梧飘玉砌。\n曲磴茶烟细。\n独坐数归禽。\n疏钟逗远林。",""],["断桥雪霁溪声冷。\n溪边数点寒鸦影。\n山店暝钟来。\n垂垂花正开。\n羁愁凝望处。\n玉笛吹香雨。\n瘦萼不禁春。\n折来愁杀人。",""],["去年元夕和君别。\n今年又见梅如雪。\n寒雁一声声。\n君从何处听。\n愁来浑似醉。\n彼此同憔悴。\n烟艇暮江寒。\n谁怜行路难。",""],["凤钗欲溜欹香枕。\n枣花飞堕鸳鸯锦。\n漫爇玉炉香。\n那愁今夜长。\n癫狂真个醉。\n不放檀郎睡。\n些事最消魂。\n啼痕和齿痕。",""],["南屏已作三年别。\n倦游相对花如雪。\n行到画桥边。\n斜阳正可怜。\n绿蓑香雨小。\n横笛孤山晓。\n同泛鄂君舟。\n湖烟淡不收。",""],["黄鹂语不休，飞入红香暖。\n醉倚江边百尺亭，一抹柔蓝远。\n沙雨舞䰐鬖，渡口霞光乱。\n拨刺纤鳞水面游，点点菱花晚。",""],["年年肠断青溪路，燕子矶头。\n暂系扁舟。\n飞尽寒云水自流。\n六朝旧恨斜阳里，无数沙鸥。\n莫上高楼。\n叶叶丹枫赚客愁。",""],["去年寒食。\n滕王阁上吹横笛。\n今岁清明。\n邓尉峰头听早莺。\n几回欲去。\n却被春山留我住。\n羁思茫茫。\n且对繁华醉一场。",""],["山欲暝。\n山半一声孤磬。\n两两野猿攀绝磴。\n寒潭落日净。\n帘内老僧入定。\n帘外松花满径。\n古殿石灯金粟影。\n心珠常自莹。",""],["荒亭古驿。\n雨送疏钟湿。\n饥鼠衔花灯下立。\n驴背一声觱篥。\n缁麈白帢堪悲。\n澹云芳草萋迷。\n谁把玉箫轻按，离人正是愁时。",""],["酒醒何处。\n月落溪光曙。\n窗外子规啼不住。\n真个不如归去。\n莫言身后虚名。\n难忘菰饭莼羹。\n契阔山中茅舍，恐他鹤怨猿惊。",""],["绿蕉残梦雨丝丝。\n黄莺飞去迟。\n玉郎偷影入罗帏。\n巫山路不迷。\n湘簟滑，翠钿欹。\n灯花双穗垂。\n凭肩密约两心知。\n香唇暗啮时。",""],["凤头低落画裙边。\n绣帮三寸花鲜。\n凌波何幸遇婵娟。\n瓣瓣生莲。\n怪杀夜来狂甚，温香一捻堪怜。\n玉趺褪尽软行缠。\n被底灯前。",""],["销魂全在眼波秋。\n盈盈怕见春愁。\n暮江人去正凝眸。\n粉泪难收。\n密意灯前频送，幽情扇底微钩。\n绣帏斜睨半含羞。\n别样风流。",""],["脉脉柔情怯晓风。\n茜裙双带绾芙蓉。\n僻径遇人羞背立，柳阴中。\n几度暗颦眉黛绿，一回微笑粉痕红。\n愿作翠堤芳草软，衬鞋弓。",""],["乱蝉衰柳泣邗沟。\n舴艋是重游。\n青山不改，红蕖将吐，白了人头。\n数声画角残阳里，羁客易悲秋。\n多应惹起，十年旧梦，一片闲愁。",""],["玉骢肯住人难住。\n漠漠征尘何处。\n只有芳魂似絮。\n飞向阳关路。\n绿蕉影里双鬟语。\n梦断风流无据。\n屈指凤城人去。\n几度纱窗雨。",""],["燕市客，怅重游。\n又深秋。\n凉月小，暮山愁。\n玉蟾蜍，金腰袅，醉红楼。\n人如玉，倚香篝。\n拨箜篌。\n红蜡下，锦缠头。\n眼波横，眉黛浅，最风流。",""],["几点遥山，夕阳西下，黯黯残云。\n柳絮将飞，杏花初谢，江上孤村。\n天涯又值残春。\n更不禁、青衫泪痕。\n细雨扁舟，寒灯古寺，一个愁人。",""],["记得年时。\n罗敷未嫁，碧玉初笄。\n纨扇深遮，双螺高绾，刚解相思。\n花前珍重幽期。\n更恰好、灯昏篆微。\n半饷偎人，十分浓醉，一味娇痴。",""],["莫向江头，问他渔父，谁醉谁醒。\n一叶轻船，数声横玉，云树冥冥。\n狂奴故态堪惊。\n垂钓处、寒鸦乱鸣。\n花落鸥滩，苹香蟹簖，潮白山青。","莫向江头，问他渔父，谁醉谁醒。\n一叶轻船，数声横玉，云树冥冥。\n狂奴故态堪惊。\n垂钓处、寒鸦乱鸣。\n花落鸥滩，蘋香蟹簖，潮白山青。"],["白苹古渡，丹枫远寺，好景正深秋。\n暮岭重重，寒霞片片，江路去悠悠。\n羁游汗漫，寸心千里，回首不胜愁。\n渔沚歌残，柳桥人散，凉月伴孤舟。","白蘋古渡，丹枫远寺，好景正深秋。\n暮岭重重，寒霞片片，江路去悠悠。\n羁游汗漫，寸心千里，回首不胜愁。\n渔沚歌残，柳桥人散，凉月伴孤舟。"],["嫩绿含烟舞，妖红映水明。\n珠宫宝幕胜层城。\n蓦地绛云深处，遇娉婷。\n绣带鸳鸯暖，罗裙蛱蝶轻。\n红儿为字雪儿名。\n偷看桃花扇底，最关情。",""],["枫桥路，烟水正迢迢。\n欲向东君寻旧约，渚花岩月两无聊。\n孤负是春宵。\n人何在，独倚赤栏桥。\n遥忆去年樱笋候，画船红烛听吹箫。\n往事更魂消。",""],["江南好，烟景媚晴川。\n柳絮淡云寒食节，杏花香雨夹衣天。\n肠断画桥边。\n初相见，碧玉破瓜年。\n半饷幽欢疑梦里，几番私语避人前。\n娇小最堪怜。",""],["江南好，花信正芳菲。\n金屋莫愁偏早嫁，画船桃叶恰同归。\n风动六铢衣。\n闲伫立，不羡蝶双飞。\n银甲按筝歌调促，玉枰赌酒笑声微。\n往事囗依稀。",""],["江南好，良夜月华新。\n舞罢争看垂素手，歌残未许啮丹唇。\n妒杀是横陈。\n恹恹病，憔悴度芳春。\n何事窈娘偏薄命，多应小玉是前身。\n缥缈梦中人。",""],["江南好，人在画船中。\n桃扇半欹眉黛妩，杏衫初卸粉香融。\n洛浦降行踪。\n寻芳去，欸乃夕阳红。\n属玉双飞春恨浅，丁香百结暮愁浓。\n相忆忽相逢。",""],["江南好，六曲画屏开。\n真个有情怜宋玉，未应轻折在章台。\n幽径少人来。\n灯儿下，媚绝粉香腮。\n无语但垂双舞袖，背人偷换合欢鞋。\n长夜费安排。",""],["江南好，渌水蘸明妆。\n卓女漫夸眉际黛，婕妤别具体中香。\n窣地舞裙长。\n风流甚，半醉泥檀郎。\n蝶坞迷藏无处觅，鸳帏秘戏不禁狂。\n些事费思量。",""],["江南好，蓦遇曲栏边。\n弱柳作腰长自颤，夭桃靧面益生妍。\n一笑更嫣然。\n留欢住，双跪佛龛前。\n锲臂不忘同死约，痴情还想再生缘。\n私誓两心坚。",""],["江南好，乌桕夜乌啼。\n楚峡乍逢真似梦，隋楼欲到忽生迷。\n何异武陵溪。\n灯如昼，檀板翠眉低。\n金谷好花曾共赏，翠屏纤手忆同携。\n醉墨曩时题。",""],["江南好，佳丽数红儿。\n只为独眠偏起早，翻因密约故来迟。\n心事阿侬知。\n疏桐影，和月乱罘罳。\n子夜曲残人已醉，甲煎烧罢帐还垂。\n端的是情痴。",""],["江南好，愁坐厌芳樽。\n青鸟漫传千里信，彩鸾应化异时魂。\n孤负月黄昏。\n疏钟静，屈戍掩重门。\n绣阁不闻莲屧响，罗衫曾印口脂痕。\n无计再温存。",""],["江南好，孤馆又新秋。\n明月正圆偏作晕，彩云欲散迥难留。\n暮雨更添愁。\n闲思遍，曲巷少年游。\n灯下卸头簪茉莉，帐中含笑拨箜篌。\n往事最风流。",""],["江南好，肠断为知音。\n南陌碧桃寻旧约，西陵绣带结同心。\n良夜漏沉沉。\n人何在，门闭落花深。\n腻粉尚黏双钿合，残香犹暖旧瑶琴。\n幽恨至如今。",""],["斗帐异香熏。\n无限温存。\n凤箫吹罢更偎人。\n枕上双蛾衾上泪，事事消魂。\n潦倒厌芳樽。\n身在孤村。\n梧桐残露隔窗闻。\n别是一番滋味也，月澹灯昏。",""],["云雨巫山已渺茫。\n尚余粉靥费端相。\n细腰犹想藏衾内，高髻还疑坠枕傍。\n桃叶艇，杏花墙。\n一般微露断人肠。\n而今青草斜阳里，漫学徐妃半面妆。",""],["蝴蝶芳魂那可招。\n无端半面尚含娇。\n香埋秋藓藏罗袜，影断春波失翠翘。\n金凤慧，玉环妖。\n剩留双妩待人描。\n劝君莫作繁华想，细雨飞花一夜消。",""],["人面桃花一样残。\n东风孤冢不胜寒。\n移时莲步空余窄，啮处樱桃已损丹。\n寒食路，北邙山。\n荒榛长夜雨漫漫。\n当时无限相怜惜，觅取情人试一看。",""],["杜宇啼残一夜风，棠梨犹剪嫁衣红。\n曾于帘内匆匆见，却向溪边草草逢。\n山静悄，月朦胧，青燐数点蜡灯同。\n从今落尽铅华色，天女鸠荼总是空。",""],["海棠憔悴春光去。\n白昼廉纤雨。\n琐窗愁坐正思侬。\n恰好画堂深处蓦相逢。\n绣裙窣地双鸳小。\n妒杀腰支袅。\n博山香细酒微温。\n无奈娇波灯下最撩人。",""],["碧蟾偷弄梧桐影。\n屈戍霜华冷。\n玉人何处夜烧香。\n记取画栏西转曲池傍。\n别来瘦损腰如削。\n还忆花前约。\n此生无刻不关情。\n最是兰膏欲灺酒初醒。",""],["晚峰斜带秋云碧。\n闷坐羁怀积。\n楚江迢递梦难通。\n愁看别时红豆绣囊中。\n小楼隙月风争细。\n落叶吟香砌。\n酒醒灯暗画帘垂。\n试问此时心事阿谁知。",""],["齐山几点青螺小。\n千尺寒波绕。\n无端舟楫往来忙。\n试问千秋谁似谪仙狂。\n孤城画角烟初暝。\n望断江南信。\n劝君此处莫凭楼。\n只恐白云飞去不胜愁。",""],["夜阑怕向蓬窗睡。\n谙尽孤眠味。\n长江笑我往来频。\n况是早春时候倍愁人。\n从前好景都辜负。\n总为儒冠误。\n此身底事不能闲。\n赢得半江风雪浪如山。",""],["莺声似曲，花光如醉，玉溆波纹微皱。\n乱烟苦雨近黄昏，又酝酿、清明时候。\n迢迢欢梦，厌厌酒病，小院坐残银漏。\n情知薄幸不归来，犹自把、绣衾薰透。","莺声似曲，花光如醉，玉溆波纹微皱。\n乱烟苦雨近黄昏，又酝酿、清明时候。\n迢迢欢梦，厌厌酒病，小院坐残银漏。\n情知薄倖不归来，犹自把、绣衾薰透。"],["江上笛声残。\n双桨悠悠去不还。\n蓬背雨声潮又急，潺潺。\n两岸吴山湿影寒。\n憔悴损朱颜。\n屈指韶华鬓忽斑。\n回首故乡千里外，漫漫。\n独对梅花泪暗弹。",""],["罗袜锦茵重。\n叶叶铢衣不耐风。\n去似彩云来似梦，匆匆。\n肠断回廊细语中。\n愁倚画楼东。\n六曲屏山灯影红。\n月自徘徊花自笑，朦胧。\n孤负炉香彻夜浓。",""],["烂漫趁新晴。\n绛萼秾葩蘸水明。\n慵倚宝栏香又软，娉婷。\n惹定春光最有情。\n晓幕正啼莺。\n浥露垂垂力不胜。\n浑似玉人初睡起，轻盈。\n眉脸红潮醉未醒。",""],["绣袜留香，罗裙拂翠。\n盈盈绝称韶光媚。\n漫将团扇掩娇羞，风流偏解怜夫婿。\n燕妒双栖，莲惭并蒂。\n酒酣百种春情昵。\n小屏低槛月朦胧，云鬟压枕花香细。",""],["陌柳飘绵，园梨糁雪。\n红亭绿酒人离别。\n春光不是别离时，别离偏向春时节。\n旧梦无痕，新愁似结。\n乱鸦啼处山千叠。\n渔灯点点隔江明，苹似带雨波声咽。","陌柳飘绵，园梨糁雪。\n红亭绿酒人离别。\n春光不是别离时，别离偏向春时节。\n旧梦无痕，新愁似结。\n乱鸦啼处山千叠。\n渔灯点点隔江明，蘋似带雨波声咽。"],["狼藉金铺，飘零玉溆。\n蔫红皱白随风舞。\n残枝袅袅怨斜阳，玉环飞燕俱尘土。\n蝶泥馀香，莺辞荒圃。\n画桥客散蒙蒙雨。\n美人睡起正凭栏，娇波凝瞩愁无语。","狼藉金铺，飘零玉溆。\n蔫红皱白随风舞。\n残枝袅袅怨斜阳，玉环飞燕俱尘土。\n蝶泥馀香，莺辞荒圃。\n画桥客散濛濛雨。\n美人睡起正凭栏，娇波凝瞩愁无语。"],["桃片萦烟，梨花堕雪。\n画楼惆怅闻啼鴂。\n红妆掩泪诉东君，低回欲向枝头别。\n可是娇姿，风姨妒绝。\n顿教一夜芳菲歇。\n而今算做未开时，何须檀板悲歌咽。",""],["百宝栏前丹棘开。\n画屏深几曲、掩蓬莱。\n玉人无语立瑶阶。\n腰支小，须筑避风台。\n酒晕入莲腮。\n风流鸳帐里、费安排。\n桃笙滑溜凤凰钗。\n灯儿下，倩系合欢鞋。",""],["客里莺花三月半，春光不似愁浓。\n柳丝随处绿葱葱。\n酒帘斜日外，渔市乱烟中。\n多病文园兼作客，天涯信断难通。\n可怜长夜正思侬。\n寸心萧寺雨，残梦隔江钟。",""],["检点韶光春又去。\n羁思无聊，暂借吴山住。\n寂寂招提花几树。\n荒岩只有幽禽语。\n惆怅故人分手处。\n目断双鱼，良会浑无据。\n欹枕小楼听夜雨。\n相思一点灯光聚。",""],["茜裙窣地腰支颤。\n梅豆抛人，低露黄金钏。\n绿醑殷勤郎自劝。\n兴酣渐觉娇波缓。\n笑剔银灯回粉面。\n旋脱罗衫，瑞雪胸前见。\n鸳帐横陈红玉软。\n怜他臂上双弯暖。",""],["匆匆无计留君住。\n分手江亭，芳草廉纤雨。\n风雅而今谁共语。\n画桥怅望帆飞处。\n约道重来三月暮。\n开遍酴醾，荏苒春光去。\n若到金阊君记取。\n愁多莫赋销魂句。",""],["无语晓妆慵。\n胭脂数点红。\n爱亭亭、夕照楼空。\n浑似绿鬟刚十五，偏容易，嫁东风。\n春色不须浓。\n春情在此中。\n漫愁他、蜂蝶匆匆。\n料道消魂今岁始，常许我，一樽同。",""],["碧梧轻，红叶软。\n莺语无聊，顿觉芳菲浅。\n鸳帐梦回金钏匾。\n约得邻姬，双陆闲消遣。\n别愁浓，清泪泫。\n郎似杨花，妾似红蕉卷。\n漫把绣衫双扣撚。\n柔肠不禁车轮转。",""],["细雨苹丝叶叶秋。\n山自悠悠。\n水自悠悠。\n寒灯几点笛声幽。\n不是渔舟。\n便是菱舟。\n病客天涯悔浪游。\n花也增愁。\n月也增愁。\n双鱼寂寞泪长流。\n身在江楼。\n梦在妆楼。","细雨蘋丝叶叶秋。\n山自悠悠。\n水自悠悠。\n寒灯几点笛声幽。\n不是渔舟。\n便是菱舟。\n病客天涯悔浪游。\n花也增愁。\n月也增愁。\n双鱼寂寞泪长流。\n身在江楼。\n梦在妆楼。"],["检点闲身犹未老。\n莫教名利萦怀抱。\n淀水莼乡归隐早。\n尘事少。\n鴐鹅飞处青山晓。\n此际待将愁闷扫。\n悠然浊酒东篱倒。\n拍手浩歌岩月皎。\n秋色好。\n苹花数点潮声小。","检点闲身犹未老。\n莫教名利萦怀抱。\n淀水莼乡归隐早。\n尘事少。\n鴐鹅飞处青山晓。\n此际待将愁闷扫。\n悠然浊酒东篱倒。\n拍手浩歌岩月皎。\n秋色好。\n蘋花数点潮声小。"],["云影层层千嶂裹。\n奇峰削出芙蓉朵。\n仄磴苍藤穿磊砢。\n幽涧坐。\n饮溪麋鹿闲如我。\n突兀珠宫留佛火。\n夕岚自把香坛锁。\n拍拍水禽冲面过。\n和衣卧。\n凉蟾一点松梢堕。",""],["一树繁花摆。\n少个人儿在。\n阑干暗拍费沉吟，悔。\n悔。\n悔。\n错剪云鬟，虚传锦札，相思空害。\n拼得分开罢。\n双泪罗襟洒。\n枕馀衾剩为何人，待。\n待。\n待。\n屈指幽期，几番误了，韶华难买。","一树繁花摆。\n少个人儿在。\n阑干暗拍费沉吟，悔。\n悔。\n悔。\n错剪云鬟，虚传锦札，相思空害。\n拚得分开罢。\n双泪罗襟洒。\n枕馀衾剩为何人，待。\n待。\n待。\n屈指幽期，几番误了，韶华难买。"],["秋浦溶溶。\n秋岭重重。\n怅登临、水杳山穷。\n愁人心上，何处相逢。\n在雁声边，叶声外，雨声中。\n三秋作客，十年心事，恨迢遥、芳讯难通。\n炉烟初碧，灯芯徒红。\n任羁怀冷，吟怀淡，酒怀慵。",""],["萍踪又踏章门路。\n正高阁、斜阳暮。\n寂寞一尊空吊古。\n秋水长天，落霞孤鹜，端的才人句。\n云帆极目纷来去。\n槛外江流自吞吐。\n试问昔人高会处。\n渔歌四起，藕花萧瑟，依旧西山雨。",""],["东风吹绽丁香树。\n又陌上、飘残絮。\n肠断画桥门掩处。\n莺啼蝶舞。\n小楼曲榭，记是秋娘住。\n而今楚峡行云去。\n目断鸿笺春又暮。\n寂寞西陵松柏路。\n桃花旧院，春风如笑，悔把佳期误。",""],["叶叶铢衣高阁冷。\n小凤泥金飞不走。\n远山微蹙学修眉，人语静。\n疏林暝。\n月落青骢不见影。\n梦里分明花下径。\n携手不殊鸳翅并。\n问侬别后苦相思，方欲应。\n风吹醒。\n愁对银缸双穗烬。",""],["谁将羌管奏离筵。\n画桥边。\n酒旗前。\n细剪春风，莺语自年年。\n最是青青愁不了，常泣露，更啼烟。\n隋堤残月影翩跹。\n吐香绵。\n暮春天。\n飞入玉楼，常伴玉人眠。\n不信柔腰刚一捻，能禁得，许多怜。",""],["永夜沉吟，梦近人儿偏远。\n小窗斜日，山似愁鬟乱。\n欲将心事，诉与暝枫寒雁。\n风波平地，无端分散。\n还忆春时，背立花前如怨。\n兰膏香渍，试解罗囊看。\n迢递仙槎，隔着茫茫银汉。\n可怜拖逗，青春强半。",""],["深秋绿野桂将残。\n烟染檀栾。\n画帘欹枕无馀事，红牙度、香袅屏山。\n回想年时塞上，雪花驼帐初寒。\n从来勇退急流难。\n赢得身闲。\n初衣婵媛真堪羡，又何须、跨鲤乘鸾。\n容我鹿门负耒，同君鹤浦投竿。",""],["小亭无数秋云压。\n雨筱凉侵榻。\n帘前千顷即澄湖，点点青螺插。\n有个高僧，赤髭白足，说尽生公法。\n十年惯把溪山踏。\n野鹤孤飞匝。\n此中撇下万千般，消受茶枪菜甲。\n松阴夜静，长歌岸帻。\n皎月纤痕捻。",""],["重阳近也，枫残菊嫩不胜秋。\n远峰相对如愁。\n且喜闲斋无事，脱帽暂淹留。\n看张郎新句，潇洒风流。\n吟仙醉侯。\n问此乐、人在否。\n花下双螯在手，一笑奚求。\n红灯影里，听清谈、靡靡胜王刘。\n更何用、赵瑟齐讴。",""],["云影轻苹袅，雨丝残桂香。\n鸥烟浮远屿，渔火乱横塘。\n江上青山如画，最喜尽入蓬窗。\n邗沟衰柳啼妆。\n何处弄丝簧。\n万里滇南客，筑室老莼乡。\n淋漓翰墨，凤流不数齐梁。\n想芜城夕照，紫萸翠袖，登高倾尽菊花觞。","云影轻蘋袅，雨丝残桂香。\n鸥烟浮远屿，渔火乱横塘。\n江上青山如画，最喜尽入蓬窗。\n邗沟衰柳啼妆。\n何处弄丝簧。\n万里滇南客，筑室老莼乡。\n淋漓翰墨，凤流不数齐梁。\n想芜城夕照，紫萸翠袖，登高倾尽菊花觞。"],["霁烟轻，凉月澹，肠断西陵浦。\n松露廉纤，洒遍蓬窗雨。\n可怜旧日青山，无人吟眺，算谁肯、移家暂住。\n凭阑觑。\n几株垂柳阴边，属玉遥堪数。\n万壑千岩，犹记虎头语。\n任他客帽频欹，村醪半醉，聊目送、乱云归去。",""],["桂香蟾影雕栏折。\n喜已近、中秋节。\n凤箫轻按，鹿车双挽，偕隐风流高绝。\n绿野林泉迥别。\n羡樊刘、并传仙诀。\n掌内珠光如月。\n遍庭阶、芝芬兰茁。\n花间孟案，帘前莱彩，盛事一时夸说。\n遥望玉楼琼阙。\n待携将、玄霜绛雪。","桂香蟾影雕栏折。\n喜已近、中秋节。\n凤箫轻按，鹿车双挽，偕隐风流高绝。\n绿野林泉迥别。\n羡樊刘、并传仙诀。\n掌内珠光如月。\n遍庭阶、芝芬兰茁。\n花间孟案，帘前莱綵，盛事一时誇说。\n遥望玉楼琼阙。\n待携将、玄霜绛雪。"],["湖光如镜，双桨凌波去。\n莺语正钩辀，遍长堤、落红飞絮。\n归来半醉，肠断玉楼人，莲叶带，藕丝衫，斜倚阑干暮。\n柔蓝几叠，湿影联残雾。\n暝树带钟声，浑忘却、画桥归路。\n花时月夕，赢得此身闲，鹦鹉盏，凤凰槽，莫把韶光误。",""],["看白榆历历近秋河，玉露洒空庭。\n问羁人独夜，故园归梦，几度魂惊。\n屈指旧时文社，良友半凋零。\n遥想孤吟处，瘴黑岚青。\n当日江楼送别，记琼筵酒罢，慷慨扬舲。\n知天涯近来，诗句比南金。\n囗囗囗、囗囗囗囗，囗囗囗、翠羽价非轻。\n衡门下、迟君偃仰，菰饭莼羹。",""],["五柳高斋，恰对着、一泓秋水。\n绕溪畔、檀栾婉娈，轻鸥飞起。\n菜甲风前薿薿绿，豆花雨后垂垂紫。\n问何人、负耒学庞公，贤如此。\n白藤杖，青棕履。\n红螺盏，乌皮儿。\n看豪吟痛饮，诚哉名士。\n蒋径久忘宾与主，蘧年莫问非和是。\n但相逢、箕踞对斜晖，浮春蚁。",""],["绣甸春浓，酒帘外、青山无数。\n还记得、桃花满院，刘郎前度。\n红烛画桡临别酒，碧箫残雨相思路。\n看韶光、零落断桥边，斜阳暮。\n无限景，烟中树。\n无限意，风前絮。\n对澄湖如镜，玉人何处。\n艳影尚疑花欲笑，丽情只有莺能诉。\n叹西泠、松柏自年年，风流误。",""],["寄语陈郎，还记得、吴趋行乐。\n明月夜、鹍弦凤管，共倾凿落。\n迟日玉枰花下艇，翠微蜡屐烟中阁。\n想那年、光景总消魂，浑如昨。\n且学织，桃椎屩。\n且学卖，韩康药。\n又何妨远蹈，芜城跨鹤。\n况是竹西歌吹地，一时琴酒堪栖托。\n问董生、踪迹近如何，仍漂泊。",""],["三泖凄凉，忽变作、珠池璀璨。\n岂果有、孟尝廉吏，夜光复焕。\n何处忽收鲛客泪，谁人敢把骊龙探。\n看荧荧、火齐掌中圆。\n非常玩。\n赤水曲，昆仑岸。\n象罔索，离朱瞰。\n怪江干夜夜，蟾辉同烂。\n金错剖来胎似玉，晶盘擎出光微绀。\n似匹夫、怀宝罪何辞，还堪叹。",""],["自别同心友，倏忽五春秋。\n不知别后消息，千里思悠悠。\n地占南州之胜，人在东京以上，谈笑尽风流。\n回想龙沙景，烂漫梦中游。\n云如醉，烟如怨，月如愁。\n荒城觱篥，不堪还倚最高楼。\n闻道燕山归去，复向潇湘作客，奇句锦囊收。\n恨乏晨风翼，与汝访丹邱。",""],["螺盏浮琼液，鸠杖映华颠。\n秋来恰遇佳景，岩桂凝晴烟。\n本是竹溪六逸，堪入香山九老，丰韵自翛然。\n不作黄梁梦，惟检白云篇。\n柴门静，松径僻，日高眠。\n丹青妙理，真将笔墨当谈禅。\n吾欲借君彩笔，便拟写君入画，俨似画中仙。\n蟾影和秋色，潇洒自年年。",""],["岩腹欹红，湖唇罨绿，春光此处偏饶。\n丹襟双燕，飞过赤栏桥。\n人似东风无力，梨花梦、魂断难招。\n高楼上，玉笙吹罢，烟月总无聊。\n迢迢。\n云水阔，越王城下，独倚兰桡。\n叹十年行役，素发飘萧。\n记取三生石畔，寻旧约、几度魂消。\n山深处，烹苓斸术，容我伴渔樵。",""],["岸暝侵云，江深妒雪，萧萧声遍秋风。\n伤心客路，摇落正相同。\n十月江南暮景，空凝望、烟雨冥蒙。\n谁为伴，鸥汀紫蓼，渔舍更丹枫。\n孤蓬。\n还夜泊，一声残笛，数点离鸿。\n更怜他寂寞，露蕊霜丛。\n偶尔斜阳影里，还误认、柳絮漫空。\n青山外，平波渺渺，几欲泣途穷。","岸暝侵云，江深妒雪，萧萧声遍秋风。\n伤心客路，摇落正相同。\n十月江南暮景，空凝望、烟雨冥濛。\n谁为伴，鸥汀紫蓼，渔舍更丹枫。\n孤蓬。\n还夜泊，一声残笛，数点离鸿。\n更怜他寂寞，露蕊霜丛。\n偶尔斜阳影里，还误认、柳絮漫空。\n青山外，平波渺渺，几欲泣途穷。"],["鹤驭重逢，鹊桥仍架，银河依旧迢迢。\n喜双星尊酒，又得相邀，翻觉幽期容易，笑人间、别恨空劳。\n针楼畔，荷香欲断，桂露初飘。\n魂销。\n欢娱再整，念此夜姮娥，碧海青霄。\n羡风流佳话，较胜初遭。\n每岁相逢两度，又何须、暮暮朝朝。\n低声祝，年年但愿，常闰今宵。",""],["羡兰台词客，久擅雕龙，年华未老。\n肮脏风尘，喜宦情偏好。\n醉墨霏烟，吟船弄月，梦断吴山晓。\n桃叶江边，莫愁湖畔，春风来早。\n欣睹琼阶，桂枝初长，佳气充闾，金线绣褓。\n玉骨非凡，似神驹騕袅。\n此际香闺，红妆群拥，看轩渠含笑。\n子夜笙歌，沉沉凤蜡，玉山醉倒。",""],["本是青田仙客，暂辞碧落，谪向尘寰。\n极望蓬瀛万里，天路漫漫。\n林飔急、缟衣凋素，岩日澹、砂顶摧丹。\n夜方寒。\n声微力弱，难彻云端。\n媻跚。\n不翔吴市，未归华表，孰驾缑山。\n独立寒溪，自憎形影遽衰残。\n篱落边、漫随鸡鹜，女床侧、空羡鹓鸾。\n近雕栏。\n有人相对，同病堪叹。",""],["试入翠屏深处，花潭竹坞，恰恰啼莺。\n此日流觞曲水，更忆兰亭。\n曲尘波、娇云冉冉，蘅皋路、香雨冥冥。\n画楼凭。\n柔蓝一抹，日澹烟轻。\n分明。\n柳桥西转，香车宝扇，曾见娉婷。\n翠袖朱阑，隔花微笑眼波横。\n合欢鞋、绣帮三寸，同心结、彩缕千层。\n暮蟾生。\n画艭归去，几点纱灯。","试入翠屏深处，花潭竹坞，恰恰啼莺。\n此日流觞曲水，更忆兰亭。\n曲尘波、娇云冉冉，蘅皋路、香雨冥冥。\n画楼凭。\n柔蓝一抹，日澹烟轻。\n分明。\n柳桥西转，香车宝扇，曾见娉婷。\n翠袖朱阑，隔花微笑眼波横。\n合欢鞋、绣帮三寸，同心结、綵缕千层。\n暮蟾生。\n画艭归去，几点纱灯。"],["英雄已矣，把吴钩抛却、唾壶敲碎。\n痛哭穷途同阮籍，难乞步兵佳尉。\n白日黄鸡，催人老去，几度中山醉。\n龟毛兔角，叹浮名何年遂。\n梦魂不到春明，读书卖卜，潇洒君平肆。\n落日江亭闲岸帻，赢得持螯斫鲙。\n故国青山，美人黄土，往事征于鬼。\n桃笙豹枕，算人生惟有睡。","英雄已矣，把吴钩抛却、唾壶敲碎。\n痛哭穷途同阮籍，难乞步兵佳尉。\n白日黄鸡，催人老去，几度中山醉。\n龟毛兔角，叹浮名何年遂。\n梦魂不到春明，读书卖卜，潇洒君平肆。\n落日江亭闲岸帻，赢得持螯斫鲙。\n故国青山，美人黄土，往事徵于鬼。\n桃笙豹枕，算人生惟有睡。"],["几许奇才，与龙泉并瘗、夜光同碎。\n谁是黄梁初梦醒，甘作挂冠仙尉。\n挟瑟灯前，遗簪席上，且学淳于醉。\n荷衣桂桨，素怀欣此时遂。\n不妨轰饮悲歌，吹箫击筑，烂漫屠沽肆。\n淀水笭箵秋雨后，消受素莼丹鲙。\n词社凄凉，酒徒零落，一半嗷嗷鬼。\n黑甜软饱，问醉乡何如睡。",""],["韶光难再，任绯桃开罢、黄鹂啼碎。\n人世繁华谁占得，漫说吹箫都尉。\n羯鼓三挝，螺卮百罚，依旧腾腾醉。\n投竿抱瓮，妒君此愿先遂。\n还想八斗才华，金锵玉戛，如听歌钟肆。\n记得画堂红蜡暖，共瞰鱼羹鸠鲙。\n鳄浦书遥，羊城梦断，但见盈车鬼。\n屋梁明月，照人此际难睡。",""],["咄咄奚为，把毛锥拗折、陶泓摔碎。\n不艳石渠年少客，翻羡羽林诸尉。\n一叶何来，江边渔父，苦劝三闾醉。\n拂衣归去，农桑生计偏遂。\n看他傀儡排场，科头跣足，容我狂而肆。\n白苎丹枫时忆女，尝取郎官鲜鲙。\n杯底罗浮，胸中云梦，奇句堪惊鬼。\n浮生老矣，且图快饮浓睡。",""],["吾虽未见，想其人孤峭、其诗幽绝。\n踏遍江南江北路，雷洛壮心如铁。\n高卧芜城，桃花春雨，啼破黄鹂舌。\n请君试看，道傍多少危辙。\n回望三十二峰，峰峰奇削，已作多年别。\n石上浮邱丹灶在，不禁烟霞肠热。\n驱犊晴畦，捞虾暝渚，莫叹生涯拙。\n他时相访，共餐芝草岩雪。",""],["算浮生碌碌，止少得，一囊钱。\n且频唤索郎，亟邀欢伯，笑傲花前。\n富贵此生休问，尽徜徉、山水度残年。\n孰惯红尘短卫，饱图白社高眠。\n数弓隙地结茅椽。\n疏竹嬲溪烟。\n有峰际闲云，松间野鹤，相对翛然。\n数声渔笛何处，看斜阳、暧暧下平川。\n试问郁单天子，何如酒肆神仙。",""],["苕溪不遇，却相逢、在白苎城边。\n一见飞扬跋扈，挥洒乱云烟。\n暂学韩康卖药，知通人、游戏本相兼。\n看白狼选胜，赤乌吊古，落叶句尤妍。\n不浅莼鲈逸兴，趁秋光、独泛淀湖船。\n与尔樽前慷慨，心事两相怜。\n寄语吾家双伯氏，溪山何处数流年。\n此时只合，高歌痛饮落花前。",""],["羡归来昼锦。\n许安石东山，暂时高枕。\n深秋露华冷。\n正丹枫半醉，黄花弄影。\n楼空人静。\n倚胡床、蟾光万顷。\n试遥看、数点青螺，一片蓬瀛佳景。\n还省。\n銮坡视草，芸署裁诗，玉堂仙境。\n雕戈画戟，把江山来重整。\n荷君恩，且著莱衣戏舞，绿鬓韶华正永。\n尽教他、徐按笙歌，流霞细饮。",""],["个个如钱，丝丝似发，雨馀益增幽景。\n小园春去，双扉昼掩，落红初凝。\n槛外银塘如镜。\n有无数、翠钿相映。\n遍闲阶、那更松根月澹，草际露冷。\n春永。\n雨绣金铺，霜黏玉础，画帘人静。\n长信宫闲，华清院废，数点萤影。\n最喜萧然三径。\n装点个紫稠绿净。\n止许那、白鹤幽踪，飞来相称。",""],["白发花卿。\n向梨花皓月，绿醑同倾。\n宫商自谱，乐府新声。\n骊珠一串分明。\n看轻拢慢撚，掩抑无限深情。\n正魂消，渐曲终人散，斗转参横。\n当年禁廷宠召，喜子夜瀛台，天语峥嵘。\n汉代延年，唐时幡绰，风流今古齐古。\n旋南驰叱拨，春江路、蟾白螺青。\n掩柴荆。\n蒲团茗碗，蝶梦初醒。",""],["绯衣阿醋。\n忽改做、道家装束。\n看满额鹅黄，天然雅淡，绝胜猩红鸭绿。\n堪与姚家称娣姒，真一样、娇姿绝俗。\n有林外黄鹂，飞来一色，繁枝如簇。\n空谷。\n尽堪长日，伴人幽独。\n似憔悴恹恹，霍娘病起，瘦比篱边丛菊。\n插向云鬟，金钗掩映，不是丹葩秾郁。\n想飞霜，一夜秋苞，拆尽珀珠盈掬。",""],["看漠漠纷纷，𬘡缊缭绕，白昼非烟非雾。\n紫塞酸风，黄沙苦月，散漫陇云关树。\n十丈马头，缁衣化尽，东华旧路。\n记江南、春景佳时，细逐落花飞絮。\n谁把红牙暗度。\n见画梁簇簇，飘来无数。\n何处印香痕，爱杀玉弓微步。\n日长静对，虚窗弄影，傍着炉香几缕。\n算人世、弱草轻栖，只合清歌缓舞。","看漠漠纷纷，絪缊缭绕，白昼非烟非雾。\n紫塞酸风，黄沙苦月，散漫陇云关树。\n十丈马头，缁衣化尽，东华旧路。\n记江南、春景佳时，细逐落花飞絮。\n谁把红牙暗度。\n见画梁簇簇，飘来无数。\n何处印香痕，爱杀玉弓微步。\n日长静对，虚窗弄影，傍着炉香几缕。\n算人世、弱草轻栖，只合清歌缓舞。"],["故人游未返，目断南云。\n双鱼消息空闻。\n越山迢递几千里，岭梅落尽馀香。\n丈夫天涯寄迹，喜主人同调，杯酒情亲。\n葛巾棕屩，看飘然、七尺闲身。\n试上凤凰山望，海气拍长空，蜃雾氤氲。\n更有丹梯石室，桄榔万树，翠羽成群。\n眼前奇景，是天教、付与诗人。\n待少文游遍，故园归隐，同采秋莼。",""],["所谓伊人，羊城之左，鳄蒲之傍。\n看五马春行，层峰矗矗，双幡夕指，涨海茫茫。\n鹦鹉群飞，荔枝初熟，绝胜江南樱笋乡。\n更堪羡，有岩花绕几，桂酒盈觞。\n兴来摇笔琳琅。\n则词赋兰台独擅场。\n记应阮同时，骚坛狎主，机云并驾，皇路高骧。\n白发词臣，青山傲吏，政治文章两不妨。\n相期切，惟月卿天老，清禁徊翔。",""],["何处逢君，西子湖边，招提画楼。\n叹羁客重来，不堪凝眺，才人久别，依旧风流。\n凤腊花轻，螺卮酒腻，痛饮豪吟夜未休。\n挥毫罢，看烟霞乱洒，珠玉难收。\n而今便往南州。\n听鹎鵊啼残章水秋。\n况玉骢芳草，王孙未返，珠帘细雨，帝子空愁。\n客里相逢，客中送别，此际输君汗漫游。\n须珍重、记相思两地，楚尾吾头。",""],["见小园、黄花开遍，觱篥斜阳依旧。\n唾壶击碎正无聊，况值悲秋时候。\n檐雨骤。\n兼数声落叶、映壁灯光瘦。\n浮生大谬。\n算龟背刮毛，马头生角，何时成就。\n黄梁梦，早被卢生看透。\n宁待疏钟残漏。\n建牙吹角寻常事，只爱白云翠岫。\n君知否。\n叹多少、英雄末路空回首。\n花前邂逅。\n同作醉乡游，长吟短咏，莫使双眉皱。",""],["试数词坛彦。\n惟陈生、奇葩逸藻，波腾云卷。\n手展麦光倾八斗，竞道扬班再见。\n听清论、靡靡忘倦。\n海内真才能有几，叹从来、风雅时人贱。\n休浪诩，雕虫擅。\n石城花月同留恋。\n正良宵、银筝翠袖，鸾笺题遍。\n别后酒徒零落尽，尔我飘飖蓬转。\n止馀得、愁丝恨片。\n不信董公称健者，已十年、瘦损风尘面。\n空搔首，泪如霰。",""],["贫也原非病。\n怅萧然、桑枢蓬溜，褐衣尘甑。\n底事屋梁恒仰面，赢得穷愁愈甚。\n请从此、停披辍咏。\n谢绝墨卿毛颖辈，任江花、零落边笥罄。\n北窗下，惟高枕。\n莫夸繁露才名盛。\n到如今、下帷何用，窥园不禁。\n蛮触功名安足贵，早己邯郸睡醒。\n况穷达、从来有命。\n暇日支筇携斗酒，正花时、不负登临兴。\n谁似我，麋鹿性。","贫也原非病。\n怅萧然、桑枢蓬溜，褐衣尘甑。\n底事屋梁恒仰面，赢得穷愁愈甚。\n请从此、停披辍咏。\n谢绝墨卿毛颖辈，任江花、零落边笥罄。\n北窗下，惟高枕。\n莫誇繁露才名盛。\n到如今、下帷何用，窥园不禁。\n蛮触功名安足贵，早己邯郸睡醒。\n况穷达、从来有命。\n暇日支筇携斗酒，正花时、不负登临兴。\n谁似我，麋鹿性。"],["孰为归生老。\n看翛然乌巾鹤氅，风姿犹好。\n偏喜镜台容易觅，扇底嫣然一笑。\n况才比、温郎还妙。\n架上彩毫应秃尽，须另寻、银管青螺扫。\n知长夜，被花恼。\n莫嗤秋燕同潦倒。\n问平生、容成秘术，些些可晓。\n种玉仙缘天付与，消受翠鬟娇小。\n真妒杀、鹊桥天表。\n但得茂陵人似玉，任白头、大妇贻诗诮。\n诧掌上，明珠耀。",""],["久拟结茅岩穴。\n便可长抛一切。\n底事为饥驱，消受江花岭月。\n愁绝。\n愁绝。\n那得称心时节。",""],["江南忆，犹忆旧繁华。\n绛蜡三更偎芍药，红螺百盏听琵琶。\n肠断赋梅花。\n人何处，远宦隔天涯。\n鹦鹉薄岚愁度岭，荔枝残月醉思家。\n山城衙鼓挝。",""],["江南忆，银管擅风骚。\n鲁国灵光推第一，高唐丽句总魂消。\n烟月妒妖娆。\n知何日，绿醑共良宵。\n粤岭人归桃叶渡，淀湖花满木兰桡。\n丘壑尽逍遥。",""],["交颈落花前。\n结得雕笼伉俪缘。\n心似彩鸾形翡翠，缠绵。\n说到相思便可怜。\n何忍暂相捐。\n别鹤孤鸾各一天。\n人世钟情谁似此，鹣鹣。\n韩贾风流萧史仙。",""],["九衢车马纷如蚁。\n暍死红尘里。\n夕阳城阙乱啼乌。\n遥望蓟丘烟树总模糊。\n客窗梦又归家去。\n竹冷泉深处。\n此时谁凭曲阑干。\n料想池荷开罢没人看。",""],["切切凄凄，叨叨絮絮。\n西风驿路伤心处。\n明知枕畔不堪听，何劳故傍疏灯语。\n古迹丹枫，寒城白苎。\n便须谱入悲秋句。\n玉人起坐泪阑干，声声断续纱窗曙。",""],["百尺楼头任骋望，参差远树稠。\n断云螺髻，斜阳鸦背，更豁双眸。\n芳筵黄菊，满酌频斟，宾主风流。\n珠帘卷，把银筝徐炙，玉斝频浮。\n优游。\n秋高爽阁，人生行乐复何求。\n餐英骚思，题糕逸兴，彩笔赓酬。\n画檐凉月涌，爱清光、欲去还留。\n荡归舟，渐縠纹溪暝，亚字城秋。","百尺楼头任骋望，参差远树稠。\n断云螺髻，斜阳鸦背，更豁双眸。\n芳筵黄菊，满酌频斟，宾主风流。\n珠帘捲，把银筝徐炙，玉斝频浮。\n优游。\n秋高爽阁，人生行乐复何求。\n餐英骚思，题糕逸兴，彩笔赓酬。\n画檐凉月涌，爱清光、欲去还留。\n荡归舟，渐縠纹溪暝，亚字城秋。"],["当年公瑾，早三五文社，誉蜚龙腹。\n滚滚毫端夸丽藻，不数江潘海陆。\n探得灵珠，夺来花簟，久侧时贤目。\n沉冥埋照，一杯常满醽醁。\n回想玉勒京华，侯鲭分饷，华馆燃红烛。\n赋罢凌云词客老，空赏谈天炙毂。\n笔傲千秋，丹成九转，长啸须眉绿。\n官衙昼静，春风吹动苜蓿。","当年公瑾，早三五文社，誉蜚龙腹。\n滚滚毫端誇丽藻，不数江潘海陆。\n探得灵珠，夺来花簟，久侧时贤目。\n沉冥埋照，一杯常满醽醁。\n回想玉勒京华，侯鲭分饷，华馆燃红烛。\n赋罢凌云词客老，空赏谈天炙毂。\n笔傲千秋，丹成九转，长啸须眉绿。\n官衙昼静，春风吹动苜蓿。"],["绕秋池、名姝偃仰，晨妆镜中彻。\n蛾眉匀净，渐暖日微酣，分外娇绝。\n雪儿小字，凭改唤、红儿丰韵别。\n记偷觑、粉腮羞晕，画帘风乍揭。\n昨夜梨花梦醒，海棠魂映，一片晚霞秋月。\n吟赏处，疑仙手、芳痕重捏。\n知还想、锦城艳丽，且试看、繁葩当槛列。\n预愁那、玉容憔悴，金樽寒夜歇。",""],["辟疆园里秋光，蓼花小艇斜阳晚。\n逶迤竹径，画栏转角，碧池清浅。\n帘控虾须，茶烹蟹眼，鹊炉香暖。\n喜高人艳质，良时邂逅，俱绝妙，湖仙伴。\n更听阳春白雪，遏行云、鹍弦凤管。\n兰灯未灺，宝钗欲坠，柔情缱绻。\n银漏无声，玉蟾弄影，琼筵初散。\n算人生，惟有高歌痛饮，葡萄百盏。",""],["燕掠莲香，蝉吟槐碧，渐觉凉生残夏。\n小院虾帘，骤雨银河倒泻。\n怪悲歌、燕市淋漓，喜顾曲、周郎蕴籍。\n漫愁他、花月销魂，十千频醉新丰舍。\n看君金马玉勒，有闲情丽藻，才凌鲍谢。\n锦色瑶笺，多在雪廊风榭。\n凭彩笔、细为平章，算红友、何如仆射。\n尽君王、赏罢凌云，西园难问价。",""],["千载词坛，寥寥可数，谁似先生。\n看奇葩四吐，扬班烂漫，灵珠盈掬，潘陆峥嵘。\n十捻三都，千金一字，当代风骚属老成。\n龙门在，任诸家百氏，孰敢争衡。\n廿年鹿侣欧盟，有碧水丹山世外情。\n记鹓班奏罢，炉烟春润，凤池散后，莲烛宵擎。\n文苑凋残，英雄老去，荏苒霜髭忽数茎。\n欣无恙，如天孙高峙，斗极常明。",""],["秦邮城外湖千顷，烟蒲夜宿䴔䴖冷。\n水面月痕生，东风舴猛轻。\n望中青欲雨。\n贞女祠边树。\n酒酽烛花垂。\n一编淮海词。","秦邮城外湖千顷，烟蒲夜宿鵁鶄冷。\n水面月痕生，东风舴猛轻。\n望中青欲雨。\n贞女祠边树。\n酒酽烛花垂。\n一编淮海词。"],["隋堤何在，见晴云雪草，苍茫无际。\n皂帽蹇驴凭吊罢，闲忆汴京遗事。\n花竹梁园，烟霞艮岳，何处寻荒址。\n繁华销歇，断肠戍鼓声里。\n堪叹蛾贼纷纷，洪涛昏垫，一夕漂朱邸。\n只有金梁桥上月，曾照歌楼灯市。\n楚汉荥阳，袁曹官渡，懒去评青史。\n黄沙古堞，暮鸦落日飞起。",""],["番君庙后鹧鸪飞。\n素馨花落蛮娘归。",""],["夹衣初换。\n花信春逾半。\n桃片织，禽声变。\n山亭蜂蝶闹，津市鱼虾贱。\n繄谁氏，柳阴坐挟书盈卷。\n不道年华晏，夕照烟峰乱。\n天可问，堪长叹。\n未酬云路志，已遂名山愿。\n今方信，白衣苍狗人情幻。",""],["莺娇蝶媚。\n人与春同醉。\n虾帘敞，螺卮腻。\n清歌调玉管，红蜡垂金穗。\n书床畔，半生消受清闲味。\n忆昔游湖墅，欢宴犹能记。\n叹荏苒，韶光逝。\n君才真八斗，富贵偏能致。\n还堪笑，董生与尔同憔悴。",""],["银蒜。\n银蒜。\n遮了东风一半。\n门前日影初残。\n犹见微峰远山。\n山远。\n山远。\n风送残红片片。",""],["露重叶无声。\n微雨秋灯。\n情深不见更分明。\n想得焚香垂手立，绣被寒轻。\n雁柱不飞筝。\n锦字谁凭。\n梦中犹记彩云名。\n桂影半窗人寂寂，依约三更。",""],["苏样青衫淡紫，宫妆小袖微红。\n郎住温柔乡里，妾住娉婷市中。",""],["思昔日，何事到而今。\n照尽青铜犹有面，烧残绛蜡已无心。\n起看月西沉。",""],["青女祠。\n青女祠。\n苔碧寒帘聚野狸。\n蛤鼓芦笙归去后，小姑白月夜题诗。",""],["衣绣凤，枕盘龙。\n妾身能自造春风。\n湿梦离披香雨闹。\n灯前照。\n绛缕添丝和影笑。",""],["郎把莲花为面。\n妾把芙蓉为面。\n启香奁，开金鉴。\n仔细凝眸数遍。\n今须辨。\n纵莲花。\n不如他。",""],["心似铁。\n撇得银环拈玉玦。\n风情两字应偏拙。\n不如归去禽声噎。\n休饶舌。\n年年啼过清明节。",""],["红楼紫箫。\n红潮画桥。\n钿筝十二娇娆。\n趁东风并骄。\n鸟中六曹。\n花间一樵。\n教他百舌休嘲。\n任春心卷蕉。","红楼紫箫。\n红潮画桥。\n钿筝十二娇娆。\n趁东风并骄。\n鸟中六曹。\n花间一樵。\n教他百舌休嘲。\n任春心捲蕉。"],["风中欲笑雨中啼。\n惯分离。\n桥边携手傍香堤。\n暮春时。\n十四红楼留不住。\n雕鞍去。\n柳枝摇曳胜杨枝。\n绾青丝。",""],["忆相见。\n羞相见。\n相见重相怨。\n潮晕透轻红，窈袅遮纨扇。\n细雨蹙蛾弯，佯羞安翠钿。\n唤住卓金车，再认春风面。",""],["醉唱新词付小红。\n去年此夜月明中。\n吹箫脉脉傍帘栊。\n肠断不堪成九曲，心灰难与叠千重。\n笑啼花事听东风。",""],["花片飞残逐水流。\n却烦燕嘴作来邮。\n雕梁犹忆旧巢不。\n珍重两心单有梦，依稀数语但言愁。\n鸳鸯小结在心头。",""],["东风无力娇慵起。\n梨花开谢桃花里。\n绣得六铢衣。\n新黄蛱蝶飞。\n花前初瞥见。\n斜掩回琼扇。\n何日嫁文鸯。\n言欢节节双。",""],["疏帘密簟红蕉吐。\n秦娥十六调鹦鹉。\n长昼对挑棋。\n犹嗔布算迟。\n香闺侬国手。\n胜负凭檀口。\n绣领撚花儿。\n抛残玉子时。",""],["黄金合里开红雪。\n青丝扇底回珠月。\n楚楚更娟娟。\n鬟多半亸肩。\n碧窗都未倦。\n压损湘裙茜。\n底事怕传闻。\n花繁好避人。",""],["朱楼十二阑干近。\n蜻蜓翼薄撩蝉鬓。\n石畔好潜藏。\n苔阴绣雀凉。\n谁人花底逻。\n却向蔷薇躲。\n簌簌动南枝。\n红潮露一丝。",""],["香烧心字安银叶。\n灰温火慢烟微爇。\n焦尾对花弹。\n秋声应指寒。\n同心金凤串。\n莫作离鸾怨。\n梦峡与啼湘。\n愔愔一夜长。",""],["纱窗风飏萧萧竹。\n金鹅屏里抽书读。\n绿简最牵人。\n佯呼错应频。\n菱花刚对面。\n影瞥双纨扇。\n绣案尚低头。\n沉吟卒未休。",""],["梅花隔院传香雪。\n兰芽吐砌流芬月。\n扑朔逐雄雌。\n萧娘映柱窥。\n犀帘长下惯。\n那解郎偷看。\n微动眼波潮。\n回身罥翠翘。",""],["兰缸照出梭儿玉。\n流苏闲挂笙囊绿。\n斗帐卸钩垂。\n浅怜深惜时。\n螺铺交屈戍。\n尽著郎详觑。\n扇扇镜屏中。\n莺啼花雨红。",""],["画桥分手。\n鹊脑双倾婪尾酒。\n泪洒鲛珠。\n斟酌来朝欲寄书。\n雪炉焚怨。\n粉魂不觉当风倦。\n凤懒龙娇。\n闲却床头紫玉箫。",""],["桃笙如水。\n莲叶飘香浮细蕊。\n红玉如脂。\n汗点轻罗带泪丝。\n轻纨微扇。\n素手慵拈纤影颤。\n闲数流萤。\n却下空阶到小庭。",""],["枇杷花里樱桃树，待扫双眉。\n罢扫双眉。\n那许春风仔细知。\n花朝才过教人懒，欲度腰肢。\n莫度腰肢。\n最怕新欢倚镜时。",""],["长堤外，水生烟。\n染就淡黄细雨，风流张绪正当年。\n画楼间。\n高低衬得春山碧。\n一道红衫明减。\n蒙蒙中酒草黏天。\n好题笺。","长堤外，水生烟。\n染就淡黄细雨，风流张绪正当年。\n画楼间。\n高低衬得春山碧。\n一道红衫明减。\n濛濛中酒草黏天。\n好题笺。"],["重重珠幕护窗纱。\n春思方佳。\n一种娇慵如梦，微闻莺语哗。\n丁香轻掩扣微差。\n绿云半侧堆鸦。\n枕痕红晕重，不敢见菱花。",""],["琮琤寒玉。\n清调随秋竹。\n旧时惯弄求凤曲。\n莫把朝飞轻续。\n一弹明月轻纱。\n再弹夜雨梨花。\n莫使高山流水，三分搀入琵琶。",""],["可怪灯花不省。\n却把兰膏光凝。\n重新剔去旧灯花，照出双单影。\n绛蜡已心灰，独向银缸等。\n待翻针帖认红丝，泪落鸳鸯冷。",""],["博山寒，沉水歇。\n香在梅冰树隙。\n薰豆蔻，解罗襦。\n亲承芗泽馀。\n绿纱深，银叶剪。\n莫漏檀心一点。\n藏犀合，贮红箱。\n须留待粉郎。",""],["娇重偏憎小婢。\n发亸故梳时髻。\n倒晕镜流红，重上桃花粉腻。\n蟹眼珠泉响细。\n鸾帐玉山人起。\n一啜便骄郎，可解樱桃至味。",""],["兰凤惝恍飘清响。\n绿池畔、茱萸金网。\n翠滑宝簪松，影落湘波漾。\n灵蛇髻绾随新样。\n恼娇慵、不寻情赏。\n绡帐起来寒，又怕云屏敞。",""],["闲阶踏遍怜华足。\n偏懊恼、春愁成曲。\n簇簌敛桃笙，展向?毫褥。\n隔墙唱彻丝和肉。\n残梦断、琮琤寒玉。\n漫卷绣帘听，孤闷吹豪竹。","闲阶踏遍怜华足。\n偏懊恼、春愁成曲。\n簇簌敛桃笙，展向?毫褥。\n隔墙唱彻丝和肉。\n残梦断、琮琤寒玉。\n漫捲绣帘听，孤闷吹豪竹。"],["银床月起回孤影。\n撇团扇、宿酲初醒。\n珠露浴蔷薇，光烛流萤冷。\n晚妆怯向菱花镜。\n欹鬌、金钗慵整。\n残粉较何郎，香汗消汤饼。",""],["药栏镇日抛红雨。\n清耿耿、翠梭鸳杵。\n蓦忆两凭肩，夜夜传私语。\n待寻好梦郎边去。\n转玉绳、星低河鼓。\n爇罢水沉香，冷落松枝麈。",""],["澹日春烟花信宜。\n红云到处罥游丝。\n自是凄凉浑不管，总难支。\n小雨三更归梦湿，轻烟十里乱愁迷。\n幸有秭归能解事，未曾啼。",""],["小楼独对云屏。\n凤胫自青青。\n待伊来也，温存锦瑟，排待银笙。\n暗笑薄情真个懵，全不听、城上三更。\n偏教看尽，绣窗月上，花影分明。",""],["灯宵才过又花朝。\n风景恶相撩。\n绿窗何事送无聊。\n闲看金步摇。\n红鸭桥头人寂寂，皇姑庙后水遥遥。\n荏苒佳期不定，恼杀木兰桡。",""],["人去珠帘花影动。\n依旧南楼月涌。\n人日春寒重。\n氍毹曾向猊炉拥。\n翻被鲍娘春信哄。\n望蜀何如得陇。\n没分香篝宠。\n两边锄断鸳鸯冢。",""],["紫玉化烟千万缕。\n变作寒窗旧雨。\n铃阁经相聚。\n数年叨做居停主。\n却怪净持原老妪。\n生得霍王小女。\n一点心相许。\n子姑乩畔偷眉语。",""],["云母屏前红泪洒。\n绣帕银环自解。\n缔约经三载。\n紫鹅桥畔曾相待。\n花草他乡应有在。\n权嘱何郎莫采。\n一晌春风罢。\n落红满地深如海。",""],["忆昔卿来于我馆。\n议作吹箫佳伴。\n重订香帏款。\n数行约法拈银管。\n传语谓郎姑且缓。\n十五盈盈未满。\n谁料朱绳短。\n相如卤莽原无算。",""],["竹叶同倾飞鹊盏。\n低觑玉儿青眼。\n细辫为侬绾。\n剩将寸发调伊懒。\n荡子天涯归未晚。\n轻把同心解散。\n长恨疑荒诞。\n自编小传邹郎撰。",""],["再浴女蚕难作茧。\n旧日鸳鸯结卷。\n春风莺暗啭。\n画楼此夜晶帘卷。\n半面相逢重腼腆。\n辜负芳心缱绻。\n恨被黄蜂践。\n情丝应付并州剪。","再浴女蚕难作茧。\n旧日鸳鸯结卷。\n春风莺暗啭。\n画楼此夜晶帘捲。\n半面相逢重腼腆。\n辜负芳心缱绻。\n恨被黄蜂践。\n情丝应付并州剪。"],["翠幰流苏声细悄。\n义甲冰弦袅袅。\n门外萧郎扰。\n鹤簪惊向犀奁掉。\n金鸭炉中香篆袅。\n翠盎文鱼长绕。\n听说相思鸟。\n红潮两点檀痕小。",""],["画梅写字都闲雅。\n更善弹棋打马。\n忆去年初夏。\n妮他细语荼蘼下。\n浪卜瓣香双凤瓦。\n谁信金钱尽假。\n风云偏潇洒。\n林逋不遇梅花寡。",""],["河满数声催阿沈。\n拼向蝉窗痛饮。\n分别思香寝。\n并头闲看红蕤枕。\n低诉几番声尚噤。\n郎欲归时寒甚。\n门外珠霜凛。\n衣郎半臂葡萄锦。","河满数声催阿沈。\n拚向蝉窗痛饮。\n分别思香寝。\n并头闲看红蕤枕。\n低诉几番声尚噤。\n郎欲归时寒甚。\n门外珠霜凛。\n衣郎半臂葡萄锦。"],["执手榴屏权雪涕。\n此后更休相弃。\n鸿便须频寄。\n延平再合君牢记。\n短后征衫驱北蓟。\n指望珀盂春第。\n不道庐江吏。\n伯劳飞燕卿夫婿。",""],["蝴蝶帐边曾作伴。\n不料朱绳折断。\n斜靠屏风畔。\n唏嘘执手重相看。\n荆钗自执樵青爨。\n时向伯鸾相唤。\n留下风情半。\n剩与做后来公案。",""],["叠得蓉笺书几瓣。\n唤住人人去雁。\n聊慰伊家盼。\n花髫乱挽闻长叹。\n细语蝉帘今不办。\n笼里雪衣分散。\n莫慰加餐饭。\n半生愁里逍遥惯。",""],["分手柴扉陈数愿。\n一愿郎心不变。\n二愿娘身健。\n今生为妾图方便。\n三愿双环常裹绢。\n四愿重投凤钏。\n五愿频相见。\n香车再到回心院。",""],["芍药仍开花步障。\n小阁春愁一晌。\n潜入葡萄帐。\n床头私致声无恙。\n岁岁青陵台畔望。\n人在蘼芜曲巷。\n再到添惆怅。\n夕阳芳草闲相向。",""],["毕竟书生真薄命。\n还是佳人薄幸。\n待把山盟订。\n海棠单受梅花聘。\n辛苦相携酬玉镜。\n漫把双环投赠。\n芳讯亲教证。\n近来小玉闻多病。","毕竟书生真薄命。\n还是佳人薄倖。\n待把山盟订。\n海棠单受梅花聘。\n辛苦相携酬玉镜。\n漫把双环投赠。\n芳讯亲教证。\n近来小玉闻多病。"],["紫雪脂香光滟滟。\n名绣红丝作验。\n银箸垂垂酽。\n不堪回首将伊念。\n杨柳章台愁作堑。\n心比兰膏更焰。\n应是前生欠。\n不平莫按神于剑。",""],["纵使百年胶漆。\n三万六千时日。\n红箫翠帐几多欢，又被闲愁搀越。\n休把春秋记，着无数、等闲风月。\n今年寒食又来过，应恨莺花恍惚。",""],["水味中泠第一。\n唤双鬟、点来新叶。\n正蟹眼鱼针初歇。\n搀入兰花清色。\n小鬟怯、擎杯涩。\n银瓶作汲。\n阿郎到底相如渴。\n应罚做、王朗水厄。",""],["花丝清艳。\n榆钱贱。\n燕燕近来双羽差健。\n玉人见。\n旧年红线。\n犀帘掩。\n写蓉笺、提起重念。\n无多件。\n烦伊作个鸿便。\n郎如面。\n回音若欠。\n郎心变。",""],["雁字鱼函浑未寄，肠断辽西客。\n金鞭微响，玉骝空闹，听马蹄得得。\n雨声偏向芭蕉滴。\n把泪珠和墨。\n学寄画崔徽，添些红晕，怕黛朱无色。",""],["一杯酹汝。\n春色何痴，药栏深处。\n海棠沉睡，紫烟红雨。\n和梦将伊去。\n鸟啼偏搅香衾侣。\n无情绪。\n魂共春丝语。\n柳馆莺来作寓。\n唤双鬟莫与。",""],["西风侧侧催衣袖。\n凉日犹长昼。\n把酒剩茱萸，休说重阳，瞒过愁时候。\n年年愁到还依旧。\n人落登高后。\n情愿一年中，分半清明，一样平消瘦。",""],["待把愁推愁未舍。\n惯听阳关浑不解。\n摇摇薇帐梦春风。\n一晌画屏东。\n绮魂飞度梁州里。\n何处凄凉忽提起。\n鸳尖怕记陇西腔。\n珠袖界残妆。",""],["二月春光未老。\n枝上红颜犹好。\n薄命桃花，断肠棠蕊，欲寄疑卿恼。\n窗外落红闲不扫。\n留伴胆瓶人悄。\n好向绿云边，簪残置案，香气犹缭绕。",""],["轻暖轻寒春仲。\n熨香风、红楼惹梦。\n泥人绣被多情，遮翠幕、不教留空。\n金衣向午争花哄。\n晕斜红、腻云绿重。\n风过日影那移，问双鬟、晓寒何重。","轻暖轻寒春仲。\n熨香风、红楼惹梦。\n泥人绣被多情，遮翠幕、不教留空。\n金衣向午争花鬨。\n晕斜红、腻云绿重。\n风过日影那移，问双鬟、晓寒何重。"],["绣帏。\n深处。\n夜深私语。\n衬月银云。\n洗花玉雨，雨馀遥指青虹。\n美人虹。\n沉沉春梦和烟绕。\n相思草。\n留饲相思鸟。\n重帘垂下，博山自爇香鱼。\n美人鱼。",""],["新衔花史。\n药栏烟重，花枝娇倚。\n戏抛红豆打莺儿。\n笑指。\n犀奁占喜子。\n影入青铜红窈窕。\n炉烟绕。\n望断羊车悄。\n玉鱼凉绣鸳藏。\n宫装。\n尘生金缕箱。",""],["检点红缸，缭绕香凫，翡翠里、不教花睡。\n非云非月非霞处，花与灯俱醉。\n莫教东风容易崇。\n只数点、金枝绛萼，夜光相配。\n银泥双袖，障兰膏一会。",""],["闲中恼。\n花事恨寥寥。\n狎客群登青雀舫，妖姬家住紫鹅桥。\n萧寺独无聊。\n闲中好。\n蓬跣任逍遥。\n识字屡呼君子鹤，佐觞犹伴美人蕉。\n一醉任天高。",""],["朱靺鞨，翠箜篌。\n轻艳处，十三楼。\n徘徊雁柱自微搊。\n香阁内，绣帐里，不曾愁。\n春如线。\n人似燕。\n恨煞东君作践。\n薰宝鸭，倚秦篝。\n绿鬟腻，红潮浅，越风流。",""],["彩云随处任风飘。\n蓬山不与海南遥。\n红蕤授枕皆双粲，紫电投壶每百娇。\n弹月磬，奏云韶。\n天孙帝子尽来朝。\n袖中碧玉新封事，愿筑银河乌鹊桥。",""],["玉奴立向风前倦。\n自把新团扇。\n上图蛱蝶下鸳鸯。\n但愿从今怀袖镇双双。\n宵来莫把流萤扑。\n长罗纨轻薄。\n权教收拾避秦篝。\n不道许多冷暖到红楼。",""],["轻暖轻寒，不晴不雨，辜负韶光九十。\n落花飞絮两无情，仗千尺、游丝作合。\n涂抹东西，飘零南北。\n从此扁舟一叶。\n梦回始觉未归人，恨一点、窥人明月。",""],["初霁。\n梅雨。\n紫苔绿荇，小山曲渚。\n丹鱼饥矣。\n搓得粉香半黍。\n向清波付与。\n防他翠鸟轻沾羽。\n双鬟语。\n种个芭蕉树。\n细数红鳞小燕，争泥坠处。\n惹双双遁去。",""],["溶溶白月。\n环环紫蜺，纷纷翠雪。\n万斛胭脂，泻拼一色银河，捣清砧，声续绝。\n金鱼锁断，一似繁筝急。\n又似愁螀噎。\n戍管梅花，痴龙渴凤孤飞。\n怨凉蟾，星欲滴。","溶溶白月。\n环环紫蜺，纷纷翠雪。\n万斛胭脂，泻拚一色银河，捣清砧，声续绝。\n金鱼锁断，一似繁筝急。\n又似愁螀噎。\n戍管梅花，痴龙渴凤孤飞。\n怨凉蟾，星欲滴。"],["海棠娇影垂杨线。\n杜鹃啼怨流莺啭。\n情语题笺，芳容题扇。\n春风吹损芙蓉面。\n唇珠懒上红笙宴。\n眉烟淡扫青琴钿。\n楚楚堪怜，仙仙堪怨。\n迎风手执花枝颤。",""],["相如不过书生耳。\n争似文君，赢透奇男子。\n却自琴心通绿绮。\n飘飘赋就凌云气。\n不是题桥雄蜀水。\n财守王孙，埋没文人矣。\n薄幸茂陵生两意。\n白头吟罢相如死。","相如不过书生耳。\n争似文君，赢透奇男子。\n却自琴心通绿绮。\n飘飘赋就凌云气。\n不是题桥雄蜀水。\n财守王孙，埋没文人矣。\n薄倖茂陵生两意。\n白头吟罢相如死。"],["幽欢久待兰缸敛，懒绣鸳鸯。\n懒说鸳鸯。\n舌唾酣红淡海棠。\n知么，微怒也、问檀郎。\n含娇半晌才私语，轻度丁香。\n轻啮丁香。\n秘密风情在画厢。\n知么，微笑也、问檀郎。",""],["沈真真，苏小小。\n旧日知名，今日馀多少。\n花史新编谁氏了。\n为问青衣，可有迦陵鸟。\n闭门羹，护门草。\n碧锁红桥，未许何郎到。\n流水无声长自绕。\n几朵芙蓉，独耐秋霜老。",""],["鹊炉温，龙饼热。\n小盒缄来，中有双银叶。\n慢火应将心字炙。\n化作鸳鸯，烟里随风结。\n向花阴，灯影灭。\n再解罗巾，犹剩沉檀屑。\n荀令薰香香未彻。\n寄语红楼，莫放馀烟歇。",""],["小阁飏微飔。\n绣床畔、涤爪来迟。\n砑绫光照蔷薇架，才翻旧谱，重临新样，又劈鲜丝。\n无语正凝思。\n双菡萏、何事连枝。\n关情曲曲盘金缕，偷窥半面，慵抬纤手，斜露双綦。",""],["紫珍随月清波满。\n应与嫦娥为伴。\n乐昌何事常分半。\n红潮一派，黛山两点，人在潇湘畔。\n翻看底下鸳鸯款。\n双鹊铸戗将金满。\n珍重绣囊丝纽短。\n萧郎照后，韦娘藏起，长贮香奁暖。",""],["忆玉兰花下，初见芳踪。\n眉欲语，意才通。\n衣香清更馥，肤彩瘦偏丰。\n人悄悄，雨蒙蒙，正相逢。\n莹莹面的，窈窈趺弓。\n蛾黛蹙，脸朱融。\n柔乡多懊恼，佳会易怔忪。\n长记取，裙上泪，石榴红。","忆玉兰花下，初见芳踪。\n眉欲语，意才通。\n衣香清更馥，肤彩瘦偏丰。\n人悄悄，雨濛濛，正相逢。\n莹莹面的，窈窈趺弓。\n蛾黛蹙，脸朱融。\n柔乡多懊恼，佳会易怔忪。\n长记取，裙上泪，石榴红。"],["花檀方拍。\n花泪频频滴。\n紫钗卖，乌丝裂。\n玉环悲蜀道，铜雀欺孙策。\n东风逆，二乔应作漳台客。\n三秋如一日，九曲回肠结。\n空自把，韶华掷。\n本非司马窃，难对虞侯说。\n凄凉夜，举杯自忏当头月。",""],["唏嘘无计。\n权且相回避。\n只一念，应牢记。\n柳眉休更蹙，荑手应还腻。\n堪悲是，金樽难下平原醴。\n忆昔多惊悸。\n欢会非容易。\n难忘却，当初意。\n原惭金谷主，空学庐江吏。\n伊去后，泪痕又把红绡寄。",""],["灵芸十五鬓如鸦。\n针绝写西家。\n捧心眉矉处，粉面映溪花。\n试问苎萝畔，无忧艳，何事浣春纱。\n梧宫叶落珠帘下，犹闻神女堪夸。\n谁信道五湖，烟水泛轻槎。\n待想玉床醉倚，娇无力，阁绣晕明霞。",""],["何事欺花赚柳，恨煞春难住。\n几层烟雾空蒙处。\n恰盼到黄昏，潇潇神雨。\n才做暖，又轻寒，梦中九十还重数。\n黄蜂紫蝶，浪向荼蘼舞。\n春归百计寻春补。\n织尽冰丝，断肠千缕。\n浑无语。\n道春这回真去。","何事欺花赚柳，恨煞春难住。\n几层烟雾空濛处。\n恰盼到黄昏，潇潇神雨。\n才做暖，又轻寒，梦中九十还重数。\n黄蜂紫蝶，浪向荼蘼舞。\n春归百计寻春补。\n织尽冰丝，断肠千缕。\n浑无语。\n道春这回真去。"],["树森森，波淼淼，回首京华路。\n无限离情，趱数声鸣橹。\n遥看一片黄云，两行绿树。\n遮断却、故乡来处。\n无情绪。\n谁念寥落天涯，杯酒和风雨。\n梦去愁来，消息浑无据。\n便教两字平安，三千里外，怎博得、夜深私语。",""],["纹瀫微流。\n正万缕初柔。\n垂绮苑，映妆楼。\n此日藏乌多少，他时系马迟留。\n渐渐绿深黄浅，一带烟浮。\n花花絮絮雷塘路，风风雨雨到邗沟。\n初学舞，惯含愁。\n远恨能传玉笛，轻寒乍到红篝。\n最是长条牵愁，人在兰舟。",""],["散发伊谁氏，琴心秋水间。\n雁柱飒然动，锦瑟暗相怜。\n鼓罢湘灵妙曲，一弦一柱华年。\n博山香袅微烟。\n义甲动春纤。\n抚操众山响，箕踞对婵娟。\n白头绿绮，明珰长袖翩跹。\n便风前相倚，花前对整，无语能将心事传。",""],["约伴寻春，何处玉钩斜畔，暗数道、画桥廿四。\n向芳郊，酒帘畔，听流水。\n歌声美。\n才过桥头十五，小苏家，钿筝斜倚。\n花雨霏微，纷纷海棠园里。\n唤流莺、欲留无计。\n待满泛银船，肠断鸳鸯被。\n鲛绡拭残泪，长记酒头茶尾。",""],["离愁处，碧树正苍茫。\n伊人又一方。\n君谱茶经携瓦罀，我修花史坐琴床。\n玳楼中，金弹处，可能忘。\n他生撇、不下鸳池被。\n今生趱、不上鲛盘泪。\n杨柳下，泛归航。\n借得世情消酒瓮，拾将奇字衬诗囊。\n唤风姨，招月姊，伴云窗。",""],["巫云驻影红，湘水留痕绿。\n好腰偏绰约、轻纨束。\n横波一点，占断千行玉。\n绣帘才半揭，那许消魂，烟朝月夕偷宿。\n相逢瞥眼，便是相看熟。\n避人归僻径、青蛾蹙。\n金蝉小整，风动惊银竹。\n重到回廊曲。\n细晕红潮，恰如初醉醽醁。",""],["团扇流连，镂满月影娥池小。\n费尺素裁来，襟袖好风偏杳。\n皴石枯松，研罨画、上林承诏。\n想胭脂脱尽，宜对昭阳人悄。\n吴带当风，曹衣出水，写生空表。\n只禁本生绡。\n淡墨寒烟围绕。\n莫教持比，黄荃花鸟。\n想袖来、频向荷凉轻舀。",""],["从此闺中，便应添个司更婢。\n海棠低亚，争忍看、寸阴儿戏。\n昨夜蓉笺传语，刻在心头记。\n应并着、侍儿经意。\n月上矣。\n又听得、城头画角，莫并入、三更未。\n花神证据，乞致与、姮娥意。\n鉴我小窗欢约，莫便糊涂里。\n郎来也、应放姮娥避。",""],["春欲去。\n看窗外樱桃，离离满树。\n湿烟生碧，澹荡飘红雨。\n闹花百舌花无语。\n待唤春阴住。\n最难拼、千丈游丝，一帘飞絮。\n暗把韶光数。\n恨阵阵东风，将春压暮。\n长下虾须，留取最深处。\n蝶争须叶蜂争蕊，总被多情误。\n趁榆钱、买断送春归路。","春欲去。\n看窗外樱桃，离离满树。\n湿烟生碧，澹荡飘红雨。\n闹花百舌花无语。\n待唤春阴住。\n最难拚、千丈游丝，一帘飞絮。\n暗把韶光数。\n恨阵阵东风，将春压暮。\n长下虾须，留取最深处。\n蝶争须叶蜂争蕊，总被多情误。\n趁榆钱、买断送春归路。"],["十五盈盈小。\n投钿盒心烟缭绕。\n流连辛苦，不道佳期竟杳。\n蘼芜巷里人何在，豆蔻花中春已老。\n泪落天涯，断肠多少。\n极目年年芳草。\n闻绣阁玉蛾不扫。\n何事尺素传来，征鸿悄悄。\n侧侧轻寒白日过，蒙蒙细雨黄昏早。\n酒醒更阑，数声啼鸟。","十五盈盈小。\n投钿盒心烟缭绕。\n流连辛苦，不道佳期竟杳。\n蘼芜巷里人何在，豆蔻花中春已老。\n泪落天涯，断肠多少。\n极目年年芳草。\n闻绣阁玉蛾不扫。\n何事尺素传来，征鸿悄悄。\n侧侧轻寒白日过，濛濛细雨黄昏早。\n酒醒更阑，数声啼鸟。"],["冉冉今何日，剩东风柳外、吹来帘缝。\n忆清明、倚尽箫声，恨黄昏、选残香梦。\n迷却来时，断伊归路，不教轻送。\n情旖旎，影朦胧。\n点点落红心动。\n燕子衔将，鸠儿唤却，渐博浓阴重。\n看架外蔷薇，恁偏娇横，玉人暗中低诵。\n留得红颜，便春归、惜他何用。",""],["离离莹缀。\n见粉淡欲匀，红轻疑坠。\n绿叶重阴，引蔓分枝，恰璇帐绡宫、鲛女垂珠泪。\n正是药栏烟霁，才提丝笼，频搴素手，半揎罗袂。\n双穗。\n绀霜琼露，向白玉盘中，红罗袖里。\n文园消渴，冷甘乍解，金茎味。\n醒来何似凉州醉。\n留供绣佛幢前，素珠百琲。",""],["滚滚红尘，苦秋风、斜阳宫刹。\n方悟得、夜半深池，人盲马瞎。\n山鬼狐威帝以虎，小人猿化妻于獭。\n待陈情、细诉与天公，凄凉煞。\n三里雾，何时刮。\n三月雨，何时撤。\n用不着慈悲，告伊菩萨。\n老猾钱刀方作横，少年姜桂何能辣。\n醉狂时、击柱亦徒然，冲冠发。",""],["巫山梦，浦兰含彩照，朝云神女。\n谁把纤秾长短，写出迁延徐步。\n宋玉当时，玮态瑰姿，彩毫曾赋。\n梦来去。\n又瑶佩褰帷，杳不知处。\n但见吴绫一幅，绣无双、鸿惊凤举。\n彩缥吹烟，香透缯云丝雨。\n只描到使君，银钩小字，断肠千缕。\n大夫枕上依依，梦魂谁主。","巫山梦，浦兰含彩照，朝云神女。\n谁把纤秾长短，写出迁延徐步。\n宋玉当时，玮态瑰姿，彩毫曾赋。\n梦来去。\n又瑶佩褰帷，杳不知处。\n但见吴绫一幅，绣无双、鸿惊凤举。\n綵缥吹烟，香透缯云丝雨。\n只描到使君，银钩小字，断肠千缕。\n大夫枕上依依，梦魂谁主。"],["何处吹芦管，双剑倚长天。\n银河万斛湔洗，风景似当年。\n料得玳楼帘卷，又怕玉人衣薄，香裹夜珠寒。\n破镜衔团扇，寂寞小楼间。\n飘蝶梦，惊鸟睡，搅花眠。\n刚道人间月半，天上月团圆。\n我是前身金粟，伊是今生玉女，何事不周全。\n待驾青虬去，仔细问婵娟。","何处吹芦管，双剑倚长天。\n银河万斛湔洗，风景似当年。\n料得玳楼帘捲，又怕玉人衣薄，香裹夜珠寒。\n破镜衔团扇，寂寞小楼间。\n飘蝶梦，惊鸟睡，搅花眠。\n刚道人间月半，天上月团圆。\n我是前身金粟，伊是今生玉女，何事不周全。\n待驾青虬去，仔细问婵娟。"],["爽气生兰野。\n飘细雨、孤帆卸。\n蝉声曳树，燕飞掠水，远村如画。\n便桃笙、葵扇如遥也。\n独把乌丝挥洒。\n怪金风、初欲动，不禁悲秋重写。\n蓦忆镜中人，自来好、绣阁幽雅。\n多病为闲愁，怯初长此夜。\n记来朝、巧时良日，初临好、排待针楼下。\n寄语归期近，向罗衣再把。",""],["芍药初开，菖蒲难见，曾向画帘趋倚。\n黛影依稀，粉痕零落，别是一番情味。\n香消酒冷，算只有、好梦来睡。\n分手红鹅村畔，销魂碧鸡坊里。\n回思别愁似缕。\n刚肠早被秋眸系。\n料他红绡满把，暗垂鲛泪。\n一夜西风古道，吹不透、相思万千里。\n卧看双星，银河如水。",""],["未雨梅天，微风麦候，薄寒乍散犹侵。\n花信吹残，莺雏却哢新音。\n尊前病起难任。\n爱疏帘、密簟清阴。\n橙花香透，榴花火照，庭院深深。\n玉人此际。\n闲对云屏。\n才拈斑管，徐埋瑶琴。\n吴绫嫌重，轻罗初试神针。\n钗炼浮金。\n绾鸦翎、又插屏簪。\n慢沉吟。\n莫题秋怨，难解春心。",""],["渐过尽、郁仪飞驭。\n千顷琼池，一轮光素。\n银汉遥遥，七襄灵匹，河边住。\n从来此夕，再不见、佳期误。\n天若少情时，应苦禁、天孙年年暗渡。\n看蟾闲兔寂，算只羿妻相妒。\n纤阿去也，更不许、凤晨鸾暮。\n恨昨宵、青女初来，便明夜、皇姑无主。\n最肠断人间，留得欹针残缕。",""],["白岳移文，黄山招隐，问君何不归哉。\n便石床丹灶，尽冷落苍苔。\n忆昔日、轩辕铸鼎，容成采药，剩有高台。\n况山中、猿鹤思君，何必徘徊。\n扬州城郭，叹年年、紫陌黄埃。\n纵文选楼高，竹西路好，日踏千回。\n三十六峰犹在，白云下、洞壑须开。\n向山灵寄语，十年清梦归来。",""],["官阁昼凉初歇雨。\n正逢令节重五。\n栀子榴花齐放，香消清暑。\n为吊灵均作赋，恰随处、岁时荆楚。\n年年绣鹢朱旗，最难逢、酒龙诗虎。\n僧弥年少多才，况佐节、扬州风流霞举。\n拾艾采兰，多少鹄俦鸿侣。\n看尽鱼龙曼衍，舞回鹘、歌残白苎。\n留髡送客，便日落、莫催津鼓。",""],["青女初裁，素谷长门，冷落金茎囗注。\n只有丽娟，琥珀缨裾，艳绝披香蕊女。\n瑶圃葩芬，更掩映、锦云珠雨。\n辛苦。\n见婉约朱栏，不禁幽暮。\n便是泪染灵芸，著红玉壶中，向人如语。\n千丝铁网，百宝流苏，傍他海棠何处。\n留待深秋，恐化作、晚霞归去。\n难据。\n把金剪、甚待重做。",""],["南浦依依，西墙漠漠，好梦初透兰旌。\n香珍窃去，药重偷来，易喜易恨多惊。\n午睡初醒。\n早空房帘影，飞动初萤。\n罗袜痕轻。\n蹈香阶、猧吠疑听。\n从别后良宵，长自低巾掩袖，懊恼多情。\n秋河不动，暮雨难期，孤负双成。\n金猊火尽，剩篆烟、一缕孤萦。\n便浅嫌密妒，囗囗囗囗，难忘嘉盟。",""],["窈渺珠帘，微茫宝镜，仿佛绡宫锦地。\n便湘水无波，压残兰蕊。\n恰见素面凝妆，只粉痕、一线垂红泪。\n梅花魂冷，梨花梦断，云屏深闭。\n何事。\n临琼砌。\n但消受东君，幽情寒思。\n还领却艳阳，平些春意。\n素手喜拈绛蜡，畏珠箔、风侵回绣被。\n应渐博、艳雪枝头，留作晓霞凝睇。",""],["文采风流，试问今日，谢雪卫书谁敌。\n想姊视道升，兄承公择。\n挥洒淇园千亩，把湘妃、远翠归珠墨。\n看瘦影、便觉苍风淡月，细香吹碧。\n清极。\n写鹅溪，挥百尺。\n洗尽绣帏脂粉，黄楼屏幛，翠筠高节。\n想有坡公能识。\n识钗股、丁香旧标格。\n须留供、绣佛幢前，维摩天女能惜。",""],["昔年情绪，忆绿窗调笑，细语爱吴侬。\n流苏微响处，自忖风流，人在画屏中。\n闲听戍角，声声响、泪滴铜龙。\n恨当初、并肩花底，衫映石榴红。\n匆匆。\n一时分手，别意如烟，剩酒痕花血，尽思量、罗襦半解，宝髻微松。\n鱼函新叠回文字，应还仗、一点轻鸿。\n销魂地、难忘云树葱胧。",""],["素秋飙冷，正影娥池畔，红衣初谢。\n思妇芳魂，怨女幽情鸳鸯社。\n断肠不向西风嫁。\n最喜近、瑶台清夜。\n蛾眉淡扫，不施脂粉，虢姨妖冶。\n难借。\n涂黄晕碧，似素馨品格，暗香飘麝。\n斜倚银墙，独抚冰弦圆蟾挂。\n诉离恨望夫石下。\n鲛珠洒玉盘倾泻。\n最怜独自亭亭，雨檐霜榭。",""],["人为愁娇。\n见风回紫曲，月落红桥。\n有心催雀舫，无意听鸾箫。\n千行杨柳舞蛮腰。\n销魂堤畔，魂断重销。\n浑无语，算只有双星私照。\n悄悄。\n波浩渺。\n一点檀心，化作如烟抱。\n书密偷看，扇低重掩，留下乌丝行草。\n天许吴侬得重来，匆匆那怕徐娘老。\n山长水远，离情无限谁晓。",""],["紫曲黏云，绿窗引月，又闻香满中庭。\n檀心乍点，鲛绡试着犹轻。\n烟初散，露方零。\n傍雕栏、吹彻瑶笙。\n销魂此际，何郎剩粉，荀令馀响。\n夜阑斗转珠绳。\n渐觉烛花影里，微醉初醒。\n风流解语，宁教有恨无情。\n拈芳蕊，爱佳名。\n忍折来、供向瑶屏。\n须教夜夜，如花作伴，不负双星。",""],["柳腴花瘦日，正绿烟如水，红雨成径。\n栩栩飞来，见寻香觅艳，轻狂不定。\n乍遇微风起，又依却、苔须欲凝。\n前身香国翩跹，应知好梦难醒。\n怅好多情成性。\n向绣幕晶帘，时弄双影。\n占尽芳辰，只燕昏莺晓，江南佳景。\n长博双蛾喜，簇绣处、百花恰称。\n不道粉褪香残，误人薄幸。","柳腴花瘦日，正绿烟如水，红雨成径。\n栩栩飞来，见寻香觅艳，轻狂不定。\n乍遇微风起，又依却、苔须欲凝。\n前身香国翩跹，应知好梦难醒。\n怅好多情成性。\n向绣幕晶帘，时弄双影。\n占尽芳辰，只燕昏莺晓，江南佳景。\n长博双蛾喜，簇绣处、百花恰称。\n不道粉褪香残，误人薄倖。"],["寒香散雾初暖，轻尘灵洁。\n又见蜂忙莺懒，将恨绮愁罗，游丝千结。\n绿窗人惜。\n小步和苔金缕滑。\n吹散处，丝障重重，一春如梦风流绝。\n何事与、勾云倚月。\n随清赏、莫孤佳节。\n旧日徐娘姿态，只半面残妆，轻蝉如发。\n赊晴买夜，一点春光休损折。\n五更风，三月雨，惯作伤心别。",""],["小窗烟雨冥冥响，飕飕吹坠，落叶空庭。\n急杵浮砧，凄凄石竹墙阴。\n偏与愁人作楚，细思量、甚事恰关卿。\n无端似，空床泣恨，断轸传情。\n年年惯做西风伴，隐荒苔、啼残青穗馀灯。\n哀笳远笛，飞来何处秋声。\n二十五番寒照静，听清钲历历严更。\n偏怨汝，叫回孤梦，短发星星。",""],["九秋挽带，三春判袂，才信别离容易。\n玉簪恩重，金鸭香浓，靓妆依约在臂。\n去年此日，梁鸿溪畔，绛纱初系。\n便广陵、听吹箫明月，忍看佳丽。\n月中情，花下泪。\n几回难说，向人前寄。\n绣床停剪，锦字裁绡，空懊黔娄夫婿。\n眉间眼底，蹙新愁、还教暗避。\n归来亲揾啼痕，道伊备细。",""],["画扇歌楼，玉鞭酒市，氤氲金屋初赐。\n觅取销魂处，听柳外、旗亭清吹。\n银墙遥峙。\n见汗粉黏红，眉痕叠翠。\n真神丽。\n筵前私语，流莺声细。\n谢客花径归来，任吹箫飞盏，尽伊调戏。\n更深怜密唤，怕回首、吴侬千里。\n杜郎风味。\n爱宝萼知名，御香闻气。\n潇潇雨，愁霖泪眼，甚时同霁。",""],["风澹艳，霜蟾乍圆，森森银竹。\n何来灵族。\n翩跹处、清喉箫续。\n王孙珠夹，少妇鲛绡，辉云屋。\n露冷水晶屏，烟暖蓝田玉。\n近雕帘，舞丹足。\n慧性神姿，那数雕笼，雪衣名擅独。\n断舌叨叨语，回素玩，随佳瞩。\n初教与、相思曲。\n更蝉窗、不受金环辱。\n料不夜珠边，长傍冰壶浴。\n照寒波影绿。","风澹艳，霜蟾乍圆，森森银竹。\n何来灵族。\n翩跹处、清喉箫续。\n王孙珠袷，少妇鲛绡，辉云屋。\n露冷水晶屏，烟暖蓝田玉。\n近雕帘，舞丹足。\n慧性神姿，那数雕笼，雪衣名擅独。\n断舌叨叨语，回素玩，随佳瞩。\n初教与、相思曲。\n更蝉窗、不受金环辱。\n料不夜珠边，长傍冰壶浴。\n照寒波影绿。"],["猛忆晶帘，携手数番，鲛珠频洒。\n东风吹断，一宵归梦，葡萄慵把。\n断酒除诗，忍教孤负相思，游丝千尺偏沾惹。\n觅起旧花笺，把离愁重写。\n艳冶。\n当年分手，香鸭炉头，紫凫屏下。\n曾记绿签，暗数金钱私打。\n几回目断，此日花发长安，料应遥策春堤马。\n懊恼看征衫，又萧萧归也。",""],["巫雨朝飞，湘烟暮压，落花着地犹新。\n闺中陌上，到处欲断还匀。\n摇荡春风形影，连绣户、翠接无痕。\n寒食近、绣盖金鞍，偏汝暗赚游人。\n相思溪上，断红约月，合欢冢上，怨绿黏云。\n楚楚娟娟，多少蝶梦蜂魂。\n又见犀奁赌胜，佳名谁不爱王孙。\n斜阳处、宝屧初回，馀香犹染湘裙。",""],["瑰姿艳逸，着雾绡、云縠是何人。\n但见凌波微步，罗袜自生尘。\n手托明珠翠羽，向芝田、蘅馆启朱唇。\n却含辞未吐，明眸转盼，暗识洛灵甄。\n当日枕遗玉缕，令陈王、耿耿暗销魂。\n绣出神光离合，浮动素绫纹。\n想挑鸾彩鸾期近，便绣凤绣虎才分。\n纵宓妃重遇，魏宫今日重针神。","瑰姿艳逸，着雾绡、云縠是何人。\n但见凌波微步，罗袜自生尘。\n手托明珠翠羽，向芝田、蘅馆启朱唇。\n却含辞未吐，明眸转盼，暗识洛灵甄。\n当日枕遗玉缕，令陈王、耿耿暗销魂。\n绣出神光离合，浮动素绫纹。\n想挑鸾綵鸾期近，便绣凤绣虎才分。\n纵宓妃重遇，魏宫今日重针神。"],["碧琐空屏，云母凉，鱼镮烟绕深院。\n红叶乍惊秋，人归杳，朱栏花信香浅。\n便教卜尽五铢，剩青蚨未转。\n窗前看、疑是沈郎遗来，丹纹翠掩。\n犹记雕栊倦。\n绛蜡下、纤手掷红幺，金绯绚赌胜处，将花选、玉人那爱鸾钿。\n只教彩贯同心，佩宜男珠串。\n金风冷、留买一线斜阳，怎看秋贱。","碧琐空屏，云母凉，鱼镮烟绕深院。\n红叶乍惊秋，人归杳，朱栏花信香浅。\n便教卜尽五铢，剩青蚨未转。\n窗前看、疑是沈郎遗来，丹纹翠掩。\n犹记雕栊倦。\n绛蜡下、纤手掷红幺，金绯绚赌胜处，将花选、玉人那爱鸾钿。\n只教綵贯同心，佩宜男珠串。\n金风冷、留买一线斜阳，怎看秋贱。"],["莱子传声，洪都佐节，争羡玉珂珠勒。\n高阁重临，秋水长天一色。\n看莺花、绣斧初横，忆鲈鲙、绿帆悬直。\n怪柴桑、早赋归来，春尽听杜鹃鸣北。\n乌台三月追随，记同车参乘，齐名交逼。\n把酒高歌，莫叹片时戢翼。\n任猿臂、醉尉相呵，总虎头、封侯不易。\n最难是、知己重逢，把平原丝刻。",""],["甲帐云开，辛盘早荐，天门曙色曈昽。\n火城队散，仙琯音回，浮浮奕奕连空。\n舞絮飘花，看琼枝四照，碧海遥通。\n飞素满天中。\n御香缭绕烟融。\n便黄竹歌传，绿醽酒赐，遥闻五老呼嵩。\n佳气连清禁，紫皇新降蕊珠宫。\n万户千门，玉京畔、群玉玲珑。\n赋幽兰、谢庄衣上，侍臣初试春风。",""],["问谁家月里，是处云边，初见遥山姣。\n帘翼空青里，依稀是、楚峰十二初晓。\n玉钗声悄。\n才画时、一半慵扫。\n纵消受、螺黛蛾黄，也着些的烦恼。\n飘渺。\n轻烟微袅。\n似张郎留样，卓女遗稿。\n柳叶双尖锁，浑无语、还将鸾镜偷照。\n相思缭绕。\n凭暗传、密意多少。\n试描得鸳鸯，成十样知谁好。",""],["兰堂遥裔。\n见水佩风裳，烟鬟雾髻，尺幅传幽意。\n看泾水愁人，洞庭怨女。\n断翠斜红，揾不尽，鲛绡珠泪。\n只手把湘沅双鱼，蹙恨敛容偷寄。\n剪痕轻，绫影薄，羡蕊乱云盘，神工密致。\n想低回斜睇。\n到贵主还宫，书生仗义。\n肠断当筵，料此际、更难回避。\n落绣后、闲整鸾钗，不觉金针暗坠。",""],["听箫声、初下瑶京。\n烛影里、望双成。\n黛隐犹疑山远近，画眉郎、已到红亭。\n迢迢银漏，香尘暗度，绣槅微明。\n待来朝、细觑绿鬒雨腻，绛靥霞清。\n鬟垂玉导，肩亸珠缨，须知最小盈盈。\n按得绮魂摇飏处，梦云透、薇帐吹轻。\n今朝恰是，初开百岁，满合三生。\n看鸳鸯、小阁灯花，何如书幌藜青。",""],["今年才过清明节，又见春风催暮。\n酒旗篱落，画舫笙歌，都傍销魂堤树。\n金刹斜阳，透得红霞一抹，望中绿莎如许。\n送韶华岁岁，江山烟雨。\n相语。\n屈指兴亡多少，只柳影莺声无数。\n殿前三千，桥头十五，断却隋皇归处。\n惟有醉翁几阕，髯公三过，妆点平山词赋。\n看骑鹤人来，吹箫人去。",""],["寻梅官阁，问柳隋堤，试问使君何所有。\n种花栽竹，皓月清风对虚牖。\n谁相耦。\n悠然濠濮，宛尔潇湘，云梦胸中常八九。\n荇藻交横，鱼鸟流连，长啸清昼。\n还知否。\n鼓鬣扬鳍鱼乐，唾影唾香花覆。\n谁识非我非鱼，海罟江罶。\n消长昼。\n影动春雨绿添，纹生晚霞红皱。\n那数西江尺鲋，呴濡升斗。",""],["青女惊蝉，素娥辞燕，又是华年荏苒。\n绣阁前、依约见分明，翠袖轻匀霞脸。\n夜深几度翩跹，乍见红玉，临风欲掩。\n十二朱楼，肠断秋风，斗帐垂垂摇艳。\n宝靥慵妆，佳人对镜，还把芳姿细念。\n谁问种，自知名忍，揉碎瑶翻香滟。\n绛树清歌欲罢，红儿百首才新赋，又恰是、两三黄蝶，映丹珠一点。",""],["月佩烟裳。\n伴窗纱犹识，半面徐娘。\n翠华嘉节，来迟洛浦，紫云新苑，宠殿昭阳。\n芳妍不逐秋风嫁，涂娇晕、自整慵妆。\n老是乡。\n兰膏照彻，倒尽瑶觞。\n亭亭傲雨欺霜。\n更艳凌枫赤，秀夺松黄。\n避风台上，欲随风舞，辟寒帐畔，偏透寒香。\n消魂帘卷人争瘦，阿娇去、金屋悲凉。\n莫断肠。\n花神独许清狂。","月佩烟裳。\n伴窗纱犹识，半面徐娘。\n翠华嘉节，来迟洛浦，紫云新苑，宠殿昭阳。\n芳妍不逐秋风嫁，涂娇晕、自整慵妆。\n老是乡。\n兰膏照彻，倒尽瑶觞。\n亭亭傲雨欺霜。\n更艳凌枫赤，秀夺松黄。\n避风台上，欲随风舞，辟寒帐畔，偏透寒香。\n消魂帘捲人争瘦，阿娇去、金屋悲凉。\n莫断肠。\n花神独许清狂。"],["十五年前，事怨绪，离纷殢雨寻云。\n银屏执手时，恨他生未卜，别样殷勤。\n空教惆怅珠帘，难向南楼种合昏。\n最消魂、一语叮咛，银环钿盒泪痕新。\n断肠菱镜双分。\n嫩绿成阴，牧之枉煞寻春。\n手持双豆蔻，想佩声鬟影，香染罗巾。\n上窗重展乌丝，惟有春寒瘦著人。\n便重来、梦里分明，何处觅湘君。",""],["村居三亩地，东风暖、无数暗阴遮。\n见绿草方塘，些些睡鸭，白杨废圃，点点归鸦。\n况墙外、老藤方挂树，苦笋正抽芽。\n宜夏宜冬，几间茅屋，半村半郭，一带人家。\n主人无个事，正瓷瓯酌酒，瓦罀煎茶。\n更课樵青数辈，自捕鱼虾。\n看拍手群儿，争驱黄犊，垂鬟小女，笑插红花。\n只此闲中日月，暗度年华。",""],["烟生芳草。\n斜阳外，尺书可来天表。\n空庭懒妇正心惊，齐女吟声悄。\n渐叶叶、梧桐报晓。\n银床金井苔痕小。\n见月浪横天，又鹦鹉、侵霜欲语，檐花相照。\n此际肠断伊人，西风卷透，一点梦魂难到。\n晴窗如雨滴愁声，动孤眠怀抱。\n似别院、哀筝响急，四弦槭槭离鸾调。\n争奈铜龙漏彻，听过三更，雁飞多少。","烟生芳草。\n斜阳外，尺书可来天表。\n空庭懒妇正心惊，齐女吟声悄。\n渐叶叶、梧桐报晓。\n银床金井苔痕小。\n见月浪横天，又鹦鹉、侵霜欲语，檐花相照。\n此际肠断伊人，西风捲透，一点梦魂难到。\n晴窗如雨滴愁声，动孤眠怀抱。\n似别院、哀筝响急，四弦槭槭离鸾调。\n争奈铜龙漏彻，听过三更，雁飞多少。"],["越水吴山，待扁舟、久矣栖迟。\n只丈夫、南北东西。\n着征衫、何必赠将离。\n应只有、奇字盈囊，虎跳龙卧，落纸争飞。\n过严滩，为访富春旧迹，重上钓鱼矶。\n云冉冉，草萋萋。\n忆临歧，秋士休悲。\n听武夷幔亭仙乐，便骖鸾梅福也相期。\n何况是、到处逢迎，天涯知己，斫鲙衔杯。\n怀故苑，畅好荔枝未熟，劝汝莫忘归。",""],["饮金舟。\n人生何处可言愁。\n气清天朗，兰亭梓泽，好向迟留。\n碧波数顷，绿阴千树，风景如秋。\n对双双、㶉鶒沉浮。\n又桥回路转，药栏映石，渔艇随流。\n况使君文采，角巾短屐，鹤盖任飙悠。\n且一饮千杯，隔林蝉唱晚风柔。\n管弦丝竹，左徒芳圃，中散良游。\n念西陵、何似吴州。\n把六桥花柳，三竺云烟，长忆秦楼。","饮金舟。\n人生何处可言愁。\n气清天朗，兰亭梓泽，好向迟留。\n碧波数顷，绿阴千树，风景如秋。\n对双双、鸂鶒沉浮。\n又桥回路转，药栏映石，渔艇随流。\n况使君文采，角巾短屐，鹤盖任飙悠。\n且一饮千杯，隔林蝉唱晚风柔。\n管弦丝竹，左徒芳圃，中散良游。\n念西陵、何似吴州。\n把六桥花柳，三竺云烟，长忆秦楼。"],["花影兰砌。\n碧天净，薰风起。\n乍看皓质，又闻娇语，云母屏前，绡帏堪倚。\n玉容冰骨自瑶池，暂谪向、人间游戏。\n想沉香、亭畔当年，舞霓裳、只雪衣相对。\n素馨香冷鲛人佩。\n犀帘外，歌喉细。\n红牙声静，绿鬟影动，诗句清新，好教长记。\n黄冠乍吐晕檀心，更不数、翩翩丹翠。\n便花田、珠网携来，傍雕栏、向梨花闲睡。",""],["九点齐州，两丸明镜，南北东西万里。\n吹箫吴市，卖药咸阳，有个英雄在里。\n三千粉黛，百万摴蒱，笑杀庸庸馀子。\n问书生、肯向商山，谩学餐芝黄绮。\n便教他、跃马中原，挥毫内殿，争羡风流名士。\n奴衣火浣，婢捧香囊，上客横拖珠履。\n肘后黄金，腰间白玉，消得十年悲喜。\n到归来、细数繁华，不过梦中而已。",""],["几日新寒乍到，看满砌、海棠幽冶。\n待教选胜寻芳，是处画檐雕榭。\n小山琼树初开，晕檀心、渐觉飘珠麝。\n轻烟歇雨，更冷露无声氤氲射。\n飘飘金粟前身，又谁倩、虎头妙写。\n揽仙芬、待踏遍银蟾，好酬良夜。\n怕娇额涂黄，智琼妆卸。\n便金屋携来，不许狂蜂惹。\n爱芳姿、风流蕴籍。\n问何时、重染天香，向广寒宫借。",""],["曾忆当年，纵横意气，调笑风流。\n向紫宫曾咏，金丸翠被，锦鞋曾赋，碧𫄷缃绚。\n赌折搔头，敲残如意，邹衍高谈大九州。\n都休问，愿拜南柯守，封酒泉侯。\n年来自爱清酬。\n待啸月吟风烟际浮。\n便五湖遍泛，策非范蠡，一邱自足，客有羊求。\n诗酒逃名，渔樵混迹，何异衣鱼与食鸥。\n人争羡，说延陵道上，又见披裘。","曾忆当年，纵横意气，调笑风流。\n向紫宫曾咏，金丸翠被，锦鞋曾赋，碧繶缃绚。\n赌折搔头，敲残如意，邹衍高谈大九州。\n都休问，愿拜南柯守，封酒泉侯。\n年来自爱清酬。\n待啸月吟风烟际浮。\n便五湖遍泛，策非范蠡，一邱自足，客有羊求。\n诗酒逃名，渔樵混迹，何异衣鱼与食鸥。\n人争羡，说延陵道上，又见披裘。"],["我欲从之，置酒西园，较射南冈。\n只撚须摇膝，人称慧业，蓬头散发，自许清狂。\n跂脚北窗，行吟东郭，男子何须志四方。\n逍遥处，问眼前悲喜，何必张皇。\n怕教鬓发苍浪。\n且随分新词赋几章。\n便支硎山内，谈庄放鹤，金华道上，叱石成羊。\n灵运生天，淮南好道，天地梨园一戏场。\n他年志，待布黄金地，求白云乡。",""],["翠霭朝轻，红云昼暖，石乳玉苕乍茁。\n斑筠初织青丝笼，恰是吴姬相约，春纤其撷。\n香刺蒙蒙沾缀露，应摘尽、金蕾珠蘖，携轻篓、带笑归来，衣染暗香绝。\n却早柴扉半掩，红泉初汲，中妇拍茶才歇。\n蒸凝青琼，焙来绿髓，制就些些雀舌。\n看云鬟影动，幽意引奇芬初泄。\n倦文园、自来消渴，仙掌分尝，瓮瓯斟涧雪。",""],["重帘小阁关心事，绿遍萱丛。\n旧时相逢未嫁，冷落金虫。\n去后千回梦忆，重逢瞥见姿容。\n人间辛苦都尝遍，灯前拥髻愁浓。\n算只玉钗恩重，留结表心同。\n年来敢道宋家东。\n何计决芳悰。\n悔教端阳一别，直恁匆匆。\n玉冷环留脆碧，香消枕腻残红。\n纵眼前有人欢笑，才回首便自忡忡。\n肠断萧娘一纸，何必怨君终。",""],["短发愁千缕。\n谁认得、平生萧瑟，沉鳞羁羽。\n忽发狂言惊满座，浪说目成眉语。\n但记取、柘枝白苎。\n送客留髡倾一石，纵三更、且听吴歈去。\n吾明日，焚书舞。\n新声回鹘传三部。\n铁如意、唾壶敲缺，低昂击鼓。\n何事干卿春水皱，漫道齐名韦扈。\n最难得、忘形鬓主。\n二十四桥寻小杜，抱平安、书记今何许。\n新月上，桐初乳。",""],["吾老矣、去日光阴，那堪屈指，任侠疏狂，蹴鞠樗蒲，不痴不慧，无才无技。\n况生来、本磨蝎为宫，穷鼯学计。\n问人生、何处堪出世。\n应有淡月微风，剩山残水。\n还自去、守我良方，钻他故纸。\n不过是、一卷离骚，几叶楞严，破除万事，颓然坐废。\n曾消受得、蛮触功名，邯郸滋味。\n而今后，拼得无萦系。\n永教毁砚焚书，渔樵同醉。","吾老矣、去日光阴，那堪屈指，任侠疏狂，蹴鞠樗蒲，不痴不慧，无才无技。\n况生来、本磨蝎为宫，穷鼯学计。\n问人生、何处堪出世。\n应有淡月微风，剩山残水。\n还自去、守我良方，钻他故纸。\n不过是、一卷离骚，几叶楞严，破除万事，颓然坐废。\n曾消受得、蛮触功名，邯郸滋味。\n而今后，拚得无萦系。\n永教毁砚焚书，渔樵同醉。"],["从别后，千回梦忆，何处琴挑香惹。\n记小语怜惜，芳姿俊雅。\n红潮微醉金蝉亚。\n褰绣幔、认得雨娇云姹。\n便一刻、算作百年声价。\n清暇。\n长回首、绿屏深曲，轻啼浅笑，顿觉鸳被生寒，总负鲛珠频洒。\n白头吟就偏惊讶。\n更细数盟言、织就回文重写。\n那便得眼前、玉人如画。\n素娥幽冶。\n忍使梦游抛舍。\n梧桐下。\n寸心斗酒争芳夜。",""],["书幌长清，帘衣渐裛，火罢炉灰生晕。\n小山畔、桂花迟放，曲栏外、海棠偏嫩。\n爱青瓮、栽满菖蒲，恰称得幽人，碎愁零恨。\n怪满耳蛩声，凄凄切切，叫得雄心都尽。\n病人悲秋浑未损。\n况剑寂琴虚，二毛偏近。\n答宾戏、支离自笑，送穷鬼、揶揄谁问。\n十年事、偏上心头，便青鸟飞来，总虚佳信。\n只赋号愁霖，诗名苦雨，权寄眼前孤闷。",""],["问今年为底，才识春愁。\n梅额浅，柳腰柔。\n傍妆台、试看团圆玉照，一丝新喜，才上眉头。\n金雀屏风，红珠斗帐，试听东风黄栗留。\n午梦瞢腾慵醒处，金虫宝瑟倩谁收。\n又是飞飞燕子，穿帘拂幕，坐雕梁、对话难收。\n红作片，锦成毬。\n空楼闲昼，暗数绸缪。\n千点飘来，柳花烟起，五铢用尽，榆荚星稠。\n恨伊偏薄劣，镇教垂却，银蒜双钩。",""],["官阁深。\n浓树阴。\n修竹碧森森。\n金锁珠条，鸾回凤跱吐清音。\n满砌月生渌水，一片云写青林。\n正使君、拥书高啸，翛然坐对鸣琴。\n奇姿妙质振微吟。\n丽蓉采采、善解幽心。\n惯是得人怜惜，充君戏玩，风前舞翠衿。\n相思秦陇停声，不语莲漏沉沉。\n长傍湘帘，好厌雕笼，又忆飞岑。\n梦醒清怨难禁。\n恐檐霜晓侵。\n座中有客，莫倚能题，漫写珍禽。",""],["宫河杨柳，隋苑莺花竹西路，是前人、断肠处，年年长忆烟途。\n吾徒。\n烧兰作烛，裁诗擘锦东阁畔，翠盘妙舞白苎，红牙倒尽琼苏。\n歌呼。\n更清谈挥麈，回头残月落金铺。\n恰又是、离人欲别，分唱骊驹。\n踟蹰。\n西园北里，况教曾醉当垆。\n想芙蓉丛菊，二分明月，蕊女花奴。\n徐徐。\n便十年一梦，赢得虚名薄幸无。\n向平山、重到还怕，见衰草寒蒲。","宫河杨柳，隋苑莺花竹西路，是前人、断肠处，年年长忆烟途。\n吾徒。\n烧兰作烛，裁诗擘锦东阁畔，翠盘妙舞白苎，红牙倒尽琼苏。\n歌呼。\n更清谈挥麈，回头残月落金铺。\n恰又是、离人欲别，分唱骊驹。\n踟蹰。\n西园北里，况教曾醉当垆。\n想芙蓉丛菊，二分明月，蕊女花奴。\n徐徐。\n便十年一梦，赢得虚名薄倖无。\n向平山、重到还怕，见衰草寒蒲。"],["乱雨分秋，浓烟护晚，望远极目偏赊。\n万顷琉璃，广寒何处，浮云卷尽还遮。\n叹杨柳为侬憔悴，蟋蟀为侬凄戚，催寒几阵，西风空庭，湿尽寒沙。\n试问琼楼瑶阙，当此夕、何事使人嗟。\n啸呼风伯，招寻月姊，桂魄飞来，素影横斜。\n从今愿、分餐玉屑，长驾金枢，更自左持欢伯，右把婵娟，好待冰壶濯蕣华。\n回忆芳时，兰舟同舣，画阁双凭，舞罢霓裳，景色溶溶，教人好觅伊家。","乱雨分秋，浓烟护晚，望远极目偏赊。\n万顷琉璃，广寒何处，浮云捲尽还遮。\n叹杨柳为侬憔悴，蟋蟀为侬凄戚，催寒几阵，西风空庭，湿尽寒沙。\n试问琼楼瑶阙，当此夕、何事使人嗟。\n啸呼风伯，招寻月姊，桂魄飞来，素影横斜。\n从今愿、分餐玉屑，长驾金枢，更自左持欢伯，右把婵娟，好待冰壶濯蕣华。\n回忆芳时，兰舟同舣，画阁双凭，舞罢霓裳，景色溶溶，教人好觅伊家。"],["见春光又去，肠断处、年年轻掷。\n堤柳乱飘，双双飞燕翼。\n掠波无踪。\n只因狂做病，将颠赚醉，遍粉塘香国。\n风流何处寻钗泽。\n浮白红楼，踏青紫陌。\n准拟受他怜惜。\n待挑灯剪烛，细语窗槅。\n春心寂寂。\n只唾花袖碧。\n面叶钿黄，微闻消息。\n座中顾曲佳客。\n话旧游苏小，欢情何极。\n更匆匆、绝缨欹帻。\n誓今后、怜水怜山，不过远山垆侧。\n驾扁舟、趁伊潮汐。\n自思量、惟有凄凉梦，一生值得。",""],["当时江左风味，玉笙吹彻，天许轻狂暇。\n有北海韩郎，才名潇洒。\n玉鸾视草，铜螭署敕，更闻弟畜徐铉，客呼舒雅。\n行乐地、歌舞争兰夜。\n铜盘绛蜡耿耿，芳樽细浪，长鲸倾泻。\n香雾暖、满堂玉人如画。\n宛转搊弦，激昂挝鼓，沉沉月隐花明，鱼脂飘灺。\n交翠舄、花冠暗中卸。\n到此不觉，缨绝履遗，良宵无价。\n那羡南朝官仆射。\n动君王、恰赢得虎头偷写。\n看明月、梅岭冈前者。\n谢公墩畔风流话。",""],["僮来语汝，约法告而曹。\n吾所命，只数事，汝母嚣。\n记来朝。\n红药栏干畔，缚棕帚，摩苔石，除菊蠹，移兰盎，早须浇。\n庭际几头丹鲫，戏苹藻、粉饵时调。\n便闲将短竹，扶植美人蕉。\n弹雀驱枭，莫逍遥。\n宜勤应答，捷趋走，护书箧，整诗瓢。\n燕几侧，博山内，水沉烧，火毋焦。\n煮茶铛频熟，便蟹眼，听松涛。\n吾无事，痛饮酒，读离骚。\n若有客来时候，须涤盏、频进香醪。\n且抱琴吹笛，长醉侣渔樵。\n门掩无敲。","僮来语汝，约法告而曹。\n吾所命，只数事，汝母嚣。\n记来朝。\n红药栏干畔，缚棕帚，摩苔石，除菊蠹，移兰盎，早须浇。\n庭际几头丹鲫，戏蘋藻、粉饵时调。\n便闲将短竹，扶植美人蕉。\n弹雀驱枭，莫逍遥。\n宜勤应答，捷趋走，护书箧，整诗瓢。\n燕几侧，博山内，水沉烧，火毋焦。\n煮茶铛频熟，便蟹眼，听松涛。\n吾无事，痛饮酒，读离骚。\n若有客来时候，须涤盏、频进香醪。\n且抱琴吹笛，长醉侣渔樵。\n门掩无敲。"],["联翩游骑。\n玉勒踏遍，月楼烟市。\n漫追寻、雷塘绣瓦，望青帘杏花村底。\n春一笑、任群莺满树，却与春光俱醉。\n怎禁得、画桥暂止。\n猛听吹箫声起。\n遗簪堕珥筹花事。\n忆少年、情悰如水。\n却早见、当垆佳丽。\n抱银筝、初来北第。\n香缥缈、飏绣屏罗绮。\n风散落红十里。\n谁怜惜、旗亭游子。\n看日搅、一帘花碎。\n莫道天远蓬山，暂消受、檀牙按指。\n何问时、翠幰重来，对红蕤怯睡。\n赚得个、玉纤整髻。\n假报金钗坠。\n还记取、垂柳堤边，摇荡春风影里。",""],["放桃花画舫寻春。\n绿水回环，红雨缤纷。\n嫩柳丝垂，莺簧乍啭，陌头骤起香尘。\n雷塘何处，小桥流水，弥弥濏濏粼粼。\n只莺花不改，无数箫声，占断芳晨。\n伊道紫宫金弹，我道钿筝锦瑟，此恨平分。\n且试向东风寄语，细与评论。\n是谁家、桃叶桃根。\n鸦黄隐笑，蛾黛留颦。\n偷傍犀帘，微揎翠袖，的的东邻。\n明言未实，暗祝方真。\n又是夕阳斜度，早难道且住为佳，踏遍黄昏。\n回首千秋索下，猛忆三生石畔，记取腰身。\n更莫向西园北里，轻掷销魂。",""],["忆长安握手萧寺，倾倒风流如许。\n讲毗昙、年少重僧弥，把团扇、名齐法护。\n连宵过、喜听蝉联语。\n濯濯见、新桐晨露。\n两丸髻、对酒清歌，白玉手、谈庄挥麈。\n向西山、时看爽气，却种此君同住。\n洒白练、夭矫似惊龙，爱写洛神遗赋。\n高舆披鹤氅，广陵路。\n都争识、神仙风度。\n芙蓉第、纱帽隐囊，凤凰池、琼林珠树。\n羡吴苑小令题诗，兰亭右军作序。\n看车前、赫奕八驺来，更邓禹、笑人何处。\n便插簪、散帻成高步。\n封禅书、诵来无误。\n况庭际、蜡凤叠棋，数公才、又还如故。",""],["忆青春。\n年年花发碧阶新。\n寂寞谁过，倒来家酝自奇芬。\n尚难忘绮语，抛残口业负诗人。\n当时红牙翠羽，杨柳外黯自消魂。\n银管裁将，雪儿唱彻，风吹细语幽纷。\n便优伶周柳，叱咤辛刘，下笔如神。\n此日情绪难分。\n竹扉高掩，寂寞困琴樽。\n犹自有、华胥可到，玉友相亲。\n更衍波，挥洒十二龙宾。\n吾甘瓠落长贫。\n孔方交绝，管城相薄，半通难绾青纶。\n沈郎多病日，赋成雌霓，赖有王筠。\n况是弹丸脱手，向金壶、点汗走灵㕙。\n看来丽涌香氛。\n枕边鸿宾，应博佳人问。\n斟玉瀣、双鲤传兰讯。\n诵佳句、曳雪牵云。\n好破除、碎恨闲颦。\n怕十年、心事到黄昏。\n还须自忏，新参丹龠，长守金轮。",""],["垂绣幕，掩金铺。\n绿窗虚。\n黛残红敛索人扶，画难如。\n春梦非烟非水，春心乍卷乍舒。\n囗苦叫花花不应，嫩寒馀。",""],["何事连宵唱懊侬。\n双垂斗帐绣芙蓉。\n凄清晓起怨征鸿。\n水驿蓬窗山驿店，夜程霜月晓程风。\n叮咛有限意无穷。",""],["香叠红闺瑟瑟稠。\n鸳鸯瓦冻唤行舟。\n鸦啼衰柳月如钩。\n千里牵情双梦好，一年惜别四时愁。\n不须频上最高楼。",""],["九畹傍幽人，曾误灵均死。\n绿春泛泛笑东风，几朵吴花紫。\n缥缈影双飞，黯淡香层倚。\n移近红楼碧玉阑，着意长看此。",""],["临行耐把归期问。\n金钱卜信看看近。\n花事近荼蘼。\n当归寄一枝。\n红衿双燕子。\n不作传书使。\n春梦总无凭。\n还应梦未曾。",""],["清明寒食江南路。\n年年生把花时误。\n明月听吹箫。\n虚传廿四桥。\n潇潇连夜雨。\n泪滴那堪数。\n何事住扬州。\n偏增无限愁。",""],["芙蓉脸忆珠奁畔。\n绿螺细写双眉半。\n此处惯留侬。\n窗纱日影红。\n铜壶清泪水。\n闷却和衣拥。\n两地不成眠。\n春宵剧可怜。",""],["韶光九十轻抛掷。\n柔风腻雨无人惜。\n懊恼大刀头。\n何时是倦游。\n但留颜色好。\n珍重宜男草。\n莫更寄征衣。\n春归侬也归。",""],["好风吹送蒲帆影。\n却把前期省。\n怕伊细数恁归迟。\n却问牡丹花剩几多枝。\n小楼昨夜灯花好。\n今日归来了。\n知侬生性爱天涯。\n便到杜鹃啼罢又离家。",""],["君欲溯河北，我亦渡江东。\n纵是莺花三月，社燕等秋鸿。\n九曲池边高会，十五桥头长啸，蜡屐每相从。\n歌吹竹西路，批抹是春风。\n念平生，数知己，莫如公。\n嵚崎历落可笑，把臂许吴蒙。\n今日素车白马，当日螭头豹尾，人识紫薇翁。\n此后平山客，寂寞月明中。",""],["科头箕踞，是西京才子，淮南仙客。\n碧眼紫髯长啸处，手种龙鳞千尺。\n听尽隋箫，敲残秦缶，鼓罢邯郸瑟。\n无弦在膝，便教此意谁识。\n惟有明月清风，长林古涧，差可同朝夕。\n与我周旋宁作我，烂醉还须千日。\n且住为佳，不如归去，一梦扬州值。\n先生自笑，吾今四十头白。",""],["新秋不换，过皇姑渚畔，七襄停织。\n天上一年如一日，却爱千金时刻。\n珠露溶溶，银湾耿耿，不怕风涛急。\n转盼重逢，笑指人间何夕。\n便是薄幸灵乌，多情瑞鹊，恩怨天然别。\n绡阙莫嫌良会少，月寡星孤堪惜。\n世世生生，长生殿里，夫妇何曾得。\n痴儿騃女，又向果筵陈乞。","新秋不换，过皇姑渚畔，七襄停织。\n天上一年如一日，却爱千金时刻。\n珠露溶溶，银湾耿耿，不怕风涛急。\n转盼重逢，笑指人间何夕。\n便是薄倖灵乌，多情瑞鹊，恩怨天然别。\n绡阙莫嫌良会少，月寡星孤堪惜。\n世世生生，长生殿里，夫妇何曾得。\n痴儿騃女，又向果筵陈乞。"],["秦篝小炷销宫饼。\n绣衾一叠文鸳冷。\n侬已不成眠。\n知伊更可怜。\n晨光生牖里。\n晓幕长孤起。\n春梦太分明。\n关人半日情。",""],["绿杨城外平山路。\n五里香尘消暖雾。\n水碧迢迢。\n溪北溪南出画桥。\n酒旗闲向春阴卷。\n黄鸟一双篱外啭。\n堤畔人家。\n风细秋千影半斜。","绿杨城外平山路。\n五里香尘消暖雾。\n水碧迢迢。\n溪北溪南出画桥。\n酒旗闲向春阴捲。\n黄鸟一双篱外啭。\n堤畔人家。\n风细秋千影半斜。"],["绿柳正飞绵。\n半是阴天。\n孤灯和枕不成眠。\n青火未吹光似豆，故闪风前。\n花事正焉然。\n好景谁怜。\n客游还到大江边。\n细雨连宵看皓魄，谁缺谁圆。",""],["绣被携来爱鄂君。\n柳花衫子藕花裙。\n听将李尉歌中曲，认作陈王赋里人。\n偏宛转，独殷勤。\n锦裘双梦忆宵薰。\n扬州小杜能轻薄，曾向筵前乞紫云。",""],["断袖相思未惯经。\n皇姑河畔指双星。\n誓如鱼墨浓偏淡，酒到鸦啼醉复醒。\n须漫语，且徐听。\n一声弹做雨淋铃。\n铜官泼墨如螺翠，更向山头望九霄。",""],["岸草黏天明还绿，小桃袅袅红浮。\n一篙春涨上芳洲。\n橛头船护鸭，丸髻笛呼牛。\n好鸟唤晴云影破，随风似叶孤舟。\n深闺此际想含愁。\n花明残雨砌，人倚夕阳楼。",""],["荏苒芳时成惜别。\n待卷虾须，春梦愁轻切。\n绡帐微风吹半褶。\n绿杨枝上残星灭。\n晓唱玲珑声未绝。\n郎去迢迢，才过清明节。\n窗畔丁香愁百结。\n秭归过处啼难歇。","荏苒芳时成惜别。\n待捲虾须，春梦愁轻切。\n绡帐微风吹半褶。\n绿杨枝上残星灭。\n晓唱玲珑声未绝。\n郎去迢迢，才过清明节。\n窗畔丁香愁百结。\n秭归过处啼难歇。"],["多少游丝飘绣阁。\n画旗闲却秋千索。\n翡翠帘垂深院落。\n春梦恶。\n金炉篆袅无人觉。\n可奈风光今又昨。\n伤心独对葡萄幄。\n嫩柳三眠丝正弱。\n风如削。\n惜花几度探红药。",""],["碧槛芙蕖隔水遥。\n绿树阴阴，迎凉初到赤栏桥。\n鱼子兰浓侵绣带，鹅儿酒薄晕红潮。\n珠汗轻沾粉未消。\n宝袜重收，六铢衫子怯冰绡。\n阶下流萤飞一点，画眉楼上独吹箫。",""],["玉剪双双细语闻。\n花畔呢喃，微凉压梦思氤氲。\n琥珀枕寒纹尚涩，琉璃簟滑碧无尘。\n宝鸭烟飘银叶温。\n情绪冥冥，巫山洛浦杳难分。\n丹的乍施因入月，芫花煮水自湔裙。",""],["十日新年，才毕椒花家宴。\n画楼待理残针线。\n东风有信，吹到深深院。\n看摇动、鬓边飞燕。\n夹道湘帘，无数玉钗金钏。\n寻春都向铜街转。\n梅花消息，恰早枝头见。\n怕春愁、乍添娇面。",""],["江天漠漠飞鸿去。\n曾忆向、苕溪路。\n野涨挼蓝谁唤渡。\n红船乌榜，绿蓑青箬，莺脰湖边雨。\n斜川图上烟云暮。\n千顷波光凌尺素。\n莫道风波增几许。\n钓筒茶灶，幡竿鱼磬，便拟从他住。",""],["兰亭梓泽曾经处。\n消受画船箫鼓。\n水次接流觞，石畔看娇舞。\n走马杏花堤，烂醉辛夷坞。\n且莫道、酒龙诗虎。\n只一枕、春酲停午。\n浮白何时，踏青无伴，萧萧竹径销风雨。\n红萼为谁妍，翠禽相对语。",""],["红深绿浅。\n恰石栏开遍。\n拾将百草斗输赢，减春色、花飞一片。\n细雨社翁飘点点。\n任东风吹转。\n闺人此日停针线。\n在朱樱庭院。\n微寒料峭卷湘帘，怕误却、去年归燕。\n小瓮鹅黄倾几盏。\n做看花春宴。","红深绿浅。\n恰石栏开遍。\n拾将百草斗输赢，减春色、花飞一片。\n细雨社翁飘点点。\n任东风吹转。\n闺人此日停针线。\n在朱樱庭院。\n微寒料峭捲湘帘，怕误却、去年归燕。\n小瓮鹅黄倾几盏。\n做看花春宴。"],["轻寒侧侧下帘栊。\n细雨乍蒙蒙。\n盆池浅绉冰初解，便山茶、斜著殷红。\n四见丁年，几逢人日，万事酒杯中。\n银幡凤倚绣花丛。\n小阁影朦胧。\n辛盘七种羹方荐，问梅花、点额还空。\n剪彩为人，缕金作胜，都未见春风。","轻寒侧侧下帘栊。\n细雨乍濛濛。\n盆池浅绉冰初解，便山茶、斜著殷红。\n四见丁年，几逢人日，万事酒杯中。\n银幡凤倚绣花丛。\n小阁影朦胧。\n辛盘七种羹方荐，问梅花、点额还空。\n剪綵为人，缕金作胜，都未见春风。"],["二十四番花信满。\n曾几日、春过半。\n橘花才绽，榆烟又改，野鸟提壶相唤。\n何处秋千池馆。\n画旗边、饧箫声缓。\n兰叶小舟不见。\n怅春情、半篙流短。\n苍髯枝老，绿腰细草，飘散玉钱无算。\n多少翠襦金碗。\n奈伤心、莺捎蝶乱。",""],["北郭东皋，开三径、伊人静处。\n何来客、征帆初下，水餐烟语。\n瓮底老春拼尽倒，槎头缩项还重煮。\n况朔风，飒飒挟愁来，前山雨。\n提壶劝，宾还主。\n衔杯笑，吾爱女。\n爱红堆脍缕，绿浮茶乳。\n四壁惟馀犊鼻在，一樽且博鸱夷古。\n羡君家，斑管尚生化，闻鸡舞。",""],["孝然祠畔，看功名却是，眼前何物。\n两桨东西浮玉峙，撑得东南半壁。\n健鹘凌风，神鼍吼雨，浪卷江豚雪。\n空山屈指，由来处士人杰。\n待看瘗鹤残铭，纵横断碣，势涌春潮发。\n无数龙蛇留石上，都与苍苔磨灭。\n青玉坞中，碧桃湾里，望海门如发。\n松阴萝叶，举头又见新月。","孝然祠畔，看功名却是，眼前何物。\n两桨东西浮玉峙，撑得东南半壁。\n健鹘凌风，神鼍吼雨，浪捲江豚雪。\n空山屈指，由来处士人杰。\n待看瘗鹤残铭，纵横断碣，势涌春潮发。\n无数龙蛇留石上，都与苍苔磨灭。\n青玉坞中，碧桃湾里，望海门如发。\n松阴萝叶，举头又见新月。"],["九曲池边，无双亭畔，使君吟眺初回。\n正见抱琴长啸，卷帙重开。\n非仙非佛扬州吏，亦诗亦史济南才。\n堪相对，恰称何郎标格，惟有官梅。\n迟回。\n更何处，题斑管，定应校籍兰亭，此日隐囊小几，遥映水苔。\n羼提阁里容高坐，渔洋山外许谁陪。\n前身是，好认玉清仙子，金粟如来。",""],["问昭亭、故迹遗留多少。\n有良朋、青鞋布袜，穿云烂漫寻讨。\n爱苍霞、翩然放杖，仰层峰、高挂啼鸟。\n碧瓦朱栏，飞楼涌殿，夜游秉烛，催觞到晓。\n步荒祠、欲呼谢李，冥冥苍苔悄。\n凌风去、齐州九点，长空飘渺。\n但绝顶翠微未上，夹路苍髯犹小。\n好重来、追寻奇趣，丹梯那便龙鳞老。\n蹭蹬归期，安排诗律，破除万事深杯好。\n更回首、白龙黄鹤，仙迹天南绕。\n崚嶒处，石耸遗坛，麻姑仙爪。",""],["吴云不断，楚雨偏神，珍重相怜意。\n绣帏私倚。\n乌丝句、偷写樱桃小婢。\n学梳时髻。\n才做出、妮人情思。\n问何时，持楫相迎，笑看银灯蕊。\n寄语鱼笺仔细。\n但身如弱柳，三眠倦起。\n泪痕如水。\n几番验、都在越罗衫底。\n为伊屈指。\n也算得楼中萧史。\n更莫教、好梦轻圆，胜业坊前李。",""],["桃花庙口，鹦鹉洲边，谁写离人意。\n插天剑倚。\n肯回顾、多少橘奴鱼婢。\n黛峰如髻。\n空目断、骚人遗思。\n忆当年、汉浦投珠，莫负同心蕊。\n一片云浓烟细。\n想漠漠江天，悲秋顿起。\n吴山越水。\n好收拾、偏贮锦奚囊底。\n风流举止。\n应只有萧然图史。\n到他时，黄鹤搥翻，都识青莲李。",""],["红窈窕，绿参差。\n小鬟调笑绾青丝。\n花醉锦屏香雨湿，画桥归去紫箫迟。",""],["暝色摇人。\n惺惺小犬吠花阴。\n香气冷侵帘不卷。\n红云暖。\n宛转春风归路缓。","暝色摇人。\n惺惺小犬吠花阴。\n香气冷侵帘不捲。\n红云暖。\n宛转春风归路缓。"],["玉鹅桥上，遥映香堤柳。\n宝髻露红丝，向珠帘、一番携手。\n半钩罗袜，袅袅步花阴，香脂透。\n冰肌瘦。\n暗度银泥袖。\n投赠双环，一幅鲛绡绉。\n楼外月黄昏，试东风、情怀如酒。\n不堪重说，往事费思量，分离候。\n休回首。\n燕子飞清昼。",""],["软玉风情，弄环年纪，曾看柳叶新颦。\n恰半梳鸦髻，斜插犀簪。\n曲本偷藏花样，饼茶细啮纤痕。\n正才离鸳枕，桃花粉颊，细印红纹。\n曲阑低衬，锁帐氤氲。\n花神轻护芳魂。\n整云纨海棠满绣，豆蔻初薰。\n莲瓣凤头三寸，菱花螺黛双分。\n相看无语，徐笼小袖，自整长裙。",""],["一叶落。\n将谁托。\n春花秋叶同飘泊。\n花飘妮绣铃，叶飘绕红药。\n绕红药。\n留写秦楼约。",""],["笼月影，拂花痕。\n小凤氤氲。\n双袖梅花罩淡云。\n琼楼隐隐欲黄昏。\n殷勤锦瑟也，与微温。",""],["小髻糁糁绾夏云。\n轻眉淡淡拂秋烟。\n杏黄衫子藕丝裙。\n谁作伴，自成群。\n笼罩东风满袖曛。",""],["影傍青鸾怯，香趁金猊泄。\n着意为郎谋，先整龙纹席。\n温柔宿暖风，绮艳留香雪。\n莫待菊花开，吹冷红檐铁。",""],["肠断当年翠玉钩。\n新来不合强言愁。\n春风冷透鹔鹴裘。\n梦罢始知无梦好，情多暗被薄情留。\n谁教生长近红楼。",""],["花落声中听杜鹃。\n多情紫玉化成烟。\n珊珊小影是非间。\n无可思量裙簇蝶，不曾容易被裁鸳。\n今生已结再生缘。",""],["应是渡头桃叶。\n又拥过江双楫。\n青溪遗事问当垆。\n莫愁湖。\n应是堤边紫玉。\n曾照蓬山双烛。\n越溪遗胜忆朱楼。\n百花洲。",""],["花明月暗。\n灯微风缓。\n怕来朝绣幕深馆。\n失春风一半。\n流残绛蜡垂银蒜。\n须自把、铜虹换。\n荑手剔来金蕊焕。\n污兰煤须盥。",""],["临邛绿绮。\n何事琴心在里。\n听侬弹、双凤和鸣，愿萧郎洗耳。\n怕桐孙声死。\n素丝不比朱丝喜。\n玉纤纤、金凤花痕，向红窗轻理。",""],["莫教挈伴踏微行，剩与印泥量。\n玉弓月样，宝莲金齿，素足如霜。\n而今不重双红屐，画屧做高墙。\n凤头露湿，鸳踪声细，珍重相将。",""],["春色深深深护。\n隔著银墙微露。\n红杏闹，到邻家，寄语邻娃休妒。\n叠就双鱼纨素。\n中有惜花新赋。\n教收拾，小花篮，黄蜂伶俐随香渡。",""],["斑管蓉笺偏楚楚。\n堪羡香斋绣簿。\n独自翻花谱。\n罗衣私学男儿舞。\n曾记樗蒲花下赌。\n邀得卿家薄怒。\n怜子心头苦。\n檀郎罪案临风数。",""],["三百签文亲自写。\n恨被邻娃相惹。\n莫把红绫扯。\n簪花学得夫人者。\n年年待阙鸳鸯社。\n多半前生误也。\n事急相随且。\n昏黄绣佛持般若。",""],["春梦阑珊愁老大。\n惟有相思厮耐。\n一点青山黛。\n留待绛炬心休坏。\n斗酒长将他顶戴。\n博得些些盼睐。\n落下情仇派。\n五年还却三生债。",""],["一朵花铃红豆蔻。\n闻道玉人消瘦。\n铜舆重邂逅。\n约来岁放灯时候。\n望郎不见将郎咒。\n细折银泥小袖。\n轻向崔娘嗽。\n萧郎补过难依旧。","一朵花铃红豆蔻。\n闻道玉人消瘦。\n铜舆重邂逅。\n约来岁放灯时候。\n望郎不见将郎咒。\n细摺银泥小袖。\n轻向崔娘嗽。\n萧郎补过难依旧。"],["昨宵曾梦，慈悲天竺，买将丝绣。\n把笔先描出庄严，敢掩看、银泥袖。\n早挽香云应腻手。\n向珠泉频漱。\n一束杨枝在瑶瓶，且安放鹦哥右。",""],["两载飘零作浪游。\n到处金舟。\n蝶魂原不为花留。\n推梦去，又重收。\n红楼翠馆予无福。\n拼他莫莫休休。\n人愁不肯我言愁。\n天封我，醉乡侯。","两载飘零作浪游。\n到处金舟。\n蝶魂原不为花留。\n推梦去，又重收。\n红楼翠馆予无福。\n拚他莫莫休休。\n人愁不肯我言愁。\n天封我，醉乡侯。"],["蛾黄淡扫，轻添螺黛，雨湿海棠娇。\n知侬别后，香奁用尽，小晕露红潮。\n双眉斗尽青山小，和恨不成描。\n待侬归后，何郎馀粉，着意代卿消。",""],["小步方停，香车先去，邻舫比前增。\n欲问还疑，凝思细听，帘内理银筝。\n筝声似写离鸿怨，一样妾平生。\n遮莫风流，红鞭公子，故意赚侬情。",""],["应学簪花格。\n寄一本、茂猗小帖。\n这银钩、钗股休轻缺。\n卫夫人、今传说。\n便薄首孔肩，更莫把、管城轻亵。\n寄相思、付庭中桐叶。\n归来后、泪如漆。",""],["雪衣伶俐乌衣拙。\n嘱红襟、寄书莫缺。\n独向金笼，粉郎言语，和伊细述。\n八哥教煞声终鴂。\n费经年、一番剪舌。\n长锁银环，镇餐松子，叨叨再说。",""],["撚断冰蚕金鸭烬。\n频惆怅、鸾胶濡尽。\n针帖重翻寻绛缕，向绣窗搓紧。\n雁柱轻勾调凤轸。\n一般是、红筝锦瑟，落霞声近。\n冶郎何处，弹与思归引。",""],["小阁香风绉紫绡。\n女郎三五趁春娇。\n红幺下子争双陆，尺八低吹和六幺。\n知有恨，总无聊。\n句裁金剪近今宵。\n东邻姊妹都归去，独把朱唇暖玉箫。",""],["撇小鬟，花径里。\n怕翠泥潮透，照顾凤头小履。\n却被花姨调戏。\n放花梢相抵。\n鬟拨难安，飞蓬不理。\n蝉翼轻施，却向花姨微詈。\n道自来、整冠避李。\n怎援侬一例。",""],["木兰舟，杨柳树。\n两不关情，挽宿由天暮。\n更有上流春草渡。\n暗笑行人，何事频来去。\n往来人，南北路。\n水宿风餐，半被京华误。\n蓦忆江南烟月处。\n按拍传觞，不管城头曙。",""],["收将残照，衬作飞霞。\n征帆千尺向归鸦。\n思亲万里，望故苑，被云遮。\n听风外、城头鼓挝。\n身在异乡，为逐客，恨天涯。\n书行绿树罩黄沙。\n弹丸黑子，因战后，长荒葭。\n空留得、三两人家。",""],["半轮金镜，见横空千仞。\n飘泊韶华叹青鬓。\n看烧残绛蜡，简点袖痕，筹往事、惟有泪花相赆。\n人生无限恨，何事伤心，梦里愁魂暗相趁。\n便珠楼十二，费尽黄金，人去后，金雁钿蝉难认。\n只一点、相思仗东风，缄寄与伊行，更谁凭信。",""],["春游去。\n蝉衫似水。\n鸦鬓如云，十三年纪。\n犊车轻、偏向繁华处。\n栀子帘前，目炫铜街花雨。\n争奈绣鞭偷觑。\n回看阿姊，窃窃多私语。\n招侬住。\n微那小步。\n斜掩轻纨，莫把红潮露。\n深深祷向青溪庙，抽得签文，难与游郎诉。\n才信云母屏前，牢护花铃，不放春风度。",""],["记得丽娟当日，花梢年纪，鸦鬓初长。\n红玉阑干十二，门枕垂杨。\n只一搦、文犀领扣，刚三寸、绣雀鞋帮。\n傍窗纱。\n同尝苦笋，共试甜香。\n堪伤。\n博山炉畔，长斋绣佛，细祷昏黄。\n世世生生，文鸳锦水莫相忘。\n写方笺、琉璃砚匣，传密约、蛱蝶花囊。\n恨无端，千回万转，羞见萧郎。",""],["金台游倦初回，兰舟南望遥天表。\n千尺征帆，两堤断岸，归心萦绕。\n波漾轻鲦，岸驱野犊，断烟风袅。\n问故乡何处，杂花满树，此日莺飞多少。\n猛听城头芦管，见皓月、一钩犹小。\n工愁善恨，装酸捻冷，何时方了。\n欸乃数声，晚鸦几点，惊飞林杪。\n且叵罗笑把，樗蒲醉掷任他昏晓。",""],["鹿城绮席初开，气清天郎兰亭节。\n风飘紫燕，云迥青鸟，笙歌未歇。\n京陵娣姒，孝穆儿郎，千秋阀阅。\n羡三珠玉树，凌王铄谢，又早见宫袍曳。\n老子胡床高据，对南楼、正谈风月。\n宫体诗拈，内尊酒赐，语传天阙。\n绿简裁将，黄庭展罢，屏山香爇。\n到黑头将军归来，九转才成绛雪。",""],["礼佛金幢，焚香绮阁，冷落玉温香腻。\n半掩湘帘，红雨送来花气。\n教绣婢、花样初描，问厨娘、药方新忌。\n海棠园、辜负韶华，临风洒尽鲛珠泪。\n无言独傍雕栏，奈芙蕖两朵，偏教并蒂。\n锦水鸳鸯，更向绿苹游戏。\n结罗带、杏子单衫，簪宝珀、牡丹新髻。\n恨银蟾、一点窥人，斜向流黄倚。","礼佛金幢，焚香绮阁，冷落玉温香腻。\n半掩湘帘，红雨送来花气。\n教绣婢、花样初描，问厨娘、药方新忌。\n海棠园、辜负韶华，临风洒尽鲛珠泪。\n无言独傍雕栏，奈芙蕖两朵，偏教并蒂。\n锦水鸳鸯，更向绿蘋游戏。\n结罗带、杏子单衫，簪宝珀、牡丹新髻。\n恨银蟾、一点窥人，斜向流黄倚。"],["妒花风作。\n凭吹到、红心小阁。\n恨于今、珠零玉冷，便算笙歌院落。\n想伊时、前度刘郎，是绛树紫箫权托。\n恨轻写乌丝，重投翠羽，辜负花间半诺。\n难道行云巫女，刚学得、玉清情薄。\n只一梦春风，半宵秋雨，排演做寒窗消索。\n氤氲原错。\n料檀涡蓉帐，配不上、梅花寂寞。\n无名小鸟，红溜莺餐自啄。",""],["清商歌作。\n便欲附、临春绮阁。\n想当时、私称乡里，愿学夫妻村落。\n算从来、豪侠风流，单只是、书生难托。\n悔金雀楼中，紫鹅桥畔，多事当初便诺。\n独对亭亭小影，不料是、桃花命薄。\n奈半合双环，断香破镜，怎赋得离情十索。\n天公不错。\n道才子多情，这四字、而今且莫。\n无人深巷，谁向柴扉剥啄。",""],["风姨做作。\n误佳期、花姨耽阁。\n竟将伊、檀心一片，付与孟婆吹落。\n料如今、怨粉啼妆，应懊恨、庸奴难托。\n只三章有罪，两字无情，以此呼予曰诺。\n不料补过微之，竟做了、十郎轻薄。\n这别鸿新操，雕鸾旧调，可入得小窗弦索。\n伊家自错。\n问章台杨柳，道轻折、而今更莫。\n多愁杜宇，一任山花自啄。",""],["冰块霜纨，桐阴萧瑟，熊丸荻课。\n应不数、周礼师传，绛帐女宗，争颂雪满烟萝。\n有子孙郎斑管擅，看驷马、高车题柱过。\n他年志，便起居八座，彩舞巍峨。\n空庭鹤唳风咽，更绣阁时闻黄鹄歌。\n只青箱丹卷，琅函贝偈，互听高哦。\n偕隐无文，陈情有表，此乐家庭事孰多。\n持樽劝，见鸾腰虎齿，同进金鹅。","冰块霜纨，桐阴萧瑟，熊丸荻课。\n应不数、周礼师传，绛帐女宗，争颂雪满烟萝。\n有子孙郎斑管擅，看驷马、高车题柱过。\n他年志，便起居八座，綵舞巍峨。\n空庭鹤唳风咽，更绣阁时闻黄鹄歌。\n只青箱丹卷，琅函贝偈，互听高哦。\n偕隐无文，陈情有表，此乐家庭事孰多。\n持樽劝，见鸾腰虎齿，同进金鹅。"],["汝是何来，宣公后裔，太仆曾孙。\n见中山绝技，喷成墨雾，洪园异节扫向苍云。\n才大难施，调高寡和，历落嵚崎可笑人。\n因底事、着缁衣皂帽，便欲离群。\n莫教短笑长颦。\n且百饮深杯醉不分。\n任千峰极目，闲愁不断，一身出世，故态犹存。\n骂鬼文章，吓蛮书檄，一卷离骚酒一樽。\n还记取、是钓台狂客，栗里遗民。",""],["澹月轻烟，断桥深巷，可忆当年张绪。\n玉人来处风敲竹，小玉半开朱户。\n消魂处。\n舌绣红酣，琐帐摧私语。\n横波相许。\n最怜是、翠袖搊弦，独自歌金缕。\n伤情路。\n碧苑金鸡啼曙。\n泪落珠衫油污。\n简点行装看绣簿，惟有断肠诗句。\n归梦去。\n恨不得、离魂缩地和卿住。\n人生最苦。\n只几个黄昏，轻教断送，永夜潇潇雨。",""],["长伴犀梳光欲暝。\n片片碧池应冷。\n无语看金井。\n潇湘映出芙蓉景。\n一点秋波能作镜。\n莫向邻娃相并。\n寄与红楼省。\n等闲藏却孤鸾影。",""],["无数罥青凝绿，暮鼓急，晚钟轻。\n把杯横。\n一径山寒树静，归鸦噪声。\n仿佛斜阳影没，见归僧。",""],["我辈风流放荡。\n当指点、古人多妄。\n白塔红亭，幽龛别户，不藉重重纱帐。\n振衣千仞，欲倒就、南湖成酿。\n恰喜求羊赓唱。\n试问取、山川无恙。\n飞路盘空，长松直上，此际烟霞偏壮。\n不厌相看，才信得、青莲非诳。",""],["岛屿蟠沙，烟波抱月，潜虬吐沫如许。\n敛自绡宫，滴同薇露，万里浮槎谁取。\n博山小试，似快剪、云英一缕。\n袅袅萦帘拂座，怅望海天何处。\n最怜空闺独炷。\n对氤氲、燕梁莺户。\n漫倚银篝听尽，夜深梅雨。\n此际相思不浅。\n叹荀令风流顿非故。\n素被馀薰，缠绵未去。",""],["田田漫舞银塘，鱼床捧出黎云好。\n新妆淡伫，静窥湍濑，临风窈窕。\n翠羽低穿，水荭斜压，数枝偏皎。\n宛湘妃独立，轻绡掩映，明珰缀，波光照。\n三十六陂淼淼。\n渐黄昏、冰姿恁悄。\n开宜玉井，折应素手，闹红都扫。\n露冷才香，月明无影，苹花共老。\n对鹤洲千朵，堪成雪赋，向邹枚道。","田田漫舞银塘，鱼床捧出黎云好。\n新妆淡伫，静窥湍濑，临风窈窕。\n翠羽低穿，水荭斜压，数枝偏皎。\n宛湘妃独立，轻绡掩映，明珰缀，波光照。\n三十六陂淼淼。\n渐黄昏、冰姿恁悄。\n开宜玉井，折应素手，闹红都扫。\n露冷才香，月明无影，蘋花共老。\n对鹤洲千朵，堪成雪赋，向邹枚道。"],["甚江东、绿波无际，泖湖风物尤美。\n露葵生处春洲远。\n翠叶紫茎铺水。\n轻摘起，见说道、参差荇菜浑难比。\n烟村小市。\n算只有吴鲜，依稀钗股，好自伴菰米。\n秋风动、有客天涯徙倚。\n采芳曾作归计。\n当时但为鲈鱼脍，何事怅然如此。\n谁鼓枻。\n常是那、香羹调向芦花里。\n樽前漫记。\n与碧涧芹芽，帘泉玉版，潇洒共风味。",""],["西园渐届清商节。\n疏林一声凄切。\n叶底潜流，枝头乍送，常向空庭纷聒。\n齐姬恨结。\n正无限伤心，晓风残月。\n寥落高天，满身凉露响还歇。\n故园旧曾听处，柴门闲依杖，清韵飘忽。\n翻入云深，传来院静，不数哀蛩啼鴂。\n悲秋自说。\n任南陌东城，斜阳明灭。\n更忆闺中，鬓丝真髣髴。",""],["江湖岁晚。\n正水落空洲，枫下高岸。\n设簖平沙败苇，灯光零乱。\n轮囷乍向临流得，掩青筐、霎时皆满。\n谁怜携去，渔庄草舍，清霜一片。\n又早是、重阳款宴。\n叹秋色殊佳，篱金初遍。\n几处酒人对擘，新橙同荐。\n老饕只爱持螯嚼，想眉山、旷怀如见。\n还从醉后、茶烹石鼎，恍窥双眼。",""],["柳烟如织绵初落，好春尚留南郭。\n野色分桥，轻阴涨圃，仿佛江乡池阁。\n碧桃吐萼。\n更红药芽新，紫藤苞弱。\n斜日溪亭，半篙绿水燕低掠。\n旧游岁华已远，宾朋仍此地，共倾山酌。\n扇底眉弯，花间句丽，多少相思依约。\n东风轻薄。\n渐吹得羁人，鬓丝非昨。\n一曲高歌。\n醉中天作幕。",""],["横波剪得吴江影。\n发覆蝤蛴领。\n文茵走上脸微红。\n恰听雏莺羞涩哢东风。\n轻盈拟倩游丝惹。\n留住春光也。\n暖香艳雪绮筵边。\n好个朦胧烟月断肠天。",""],["望去非花，飘来疑雪，轻狂如许。\n未作浮萍，已离深树。\n此际谁为主。\n隋堤三月，几回翘首，一片漫天飞舞。\n最堪怜、无根无蒂，总被东风弄汝。\n踏歌魏女，离情多少，问道春光何处。\n乍扑空帘，旋黏芳径，好倩莺衔取。\n还思往日，鹅黄初染，变态顿分今古。\n枉垂著、长条踠地，绾伊不住。",""],["面壁。\n泪痕湿。\n相见含毫灯下立。\n风鬟雨鬓吴宫隔。\n芍药香消堪惜。\n明妃远嫁归何日。\n一曲琵琶凄恻。",""],["雕笼小鸟两眉弯。\n谁为描远山。\n好音缥缈落檐前。\n空堂成碧山。\n低格磔，碎闲关。\n新声李义山。\n听鹂携酒送春闲。\n何时少室山。",""],["杨柳正如丝。\n虫虫见客时。\n爱房栊、乍出迟迟。\n几度问年羞作答，微笑道，有娘知。\n回首便天涯。\n幽情减牧之。\n怅红桥、云树迷离。\n应是寻春人去晚，风雨过，绿阴滋。",""],["溽暑长安榴吐缬。\n客忆莼鲈，不待清秋节。\n座上高谈惊乍歇。\n箧中留得文如雪。\n折柳旗亭歌一阕。\n竟别东华，人道真痴绝。\n无限相思何日彻。\n春申浦上芦花月。",""],["借草生情，因风弄影，熠耀飘来何处。\n个个轻盈，点缀秋光无数。\n才乱穿、小幔疏棂，又暗照、空墙废圃。\n似从他、狡狯天孙，繁星洒作夜深雨。\n佳人轻把扇子，扑取青苔砌上，玉纤笼住。\n凄切寒蛩，妒杀流辉迟暮。\n怕烛至、暂敛微明，缀庭柯、顿成珠树。\n最堪怜、数斛征求，遍山岩放去。","借草生情，因风弄影，熠耀飘来何处。\n个个轻盈，点缀秋光无数。\n才乱穿、小幔疏棂，又暗照、空墙废圃。\n似从他、狡狯天孙，繁星洒作夜深雨。\n佳人轻把扇子，扑取青苔砌上，玉纤笼住。\n凄切寒蛩，妒杀流辉迟暮。\n怕烛至、暂敛微明，缀庭柯、顿成珠树。\n最堪怜、数斛徵求，遍山岩放去。"],["蕃马屏风小。\n围向洞房春正好。\n鸳鸯飞起，不道云深波杳。\n映日曾怜杏蕊新，笼烟还忆杨枝袅。\n片月当亏，双鱼恁少。\n远道萋萋芳草。\n天外山同眉黛扫。\n谁知孤客登临，总伤怀抱。\n轻寒轻暝春归久，闲闷闲愁秋早到。\n断续哀蛩，萧疏丛筱。",""],["枫香桥是黄州路。\n曾岸帻、扶筇去。\n一望霜天风景暮。\n空山流水，白云红树。\n动我悲秋赋。\n于今屡梦高歌处。\n聊取嘉名锡痴语。\n兰畹金荃休见妒。\n花间低按，尊前轻度。\n总愧江枫句。",""],["翠浪翻帷，红绫灿枕，灯花细落银缸。\n夜雨春风，寂寞掩兰房。\n吐丝妾似蚕眠箔，奈化枳君同橘过江。\n此恨倩谁说与，愿逐晨风飞去，遂到君傍。\n水远山高，云树但苍茫。\n鸳鸯几见池中睡，叹芍药空飘槛外香。",""],["花开亚枝。\n鹊飞绕枝。\n临风偏恼萱枝。\n道春归有期。\n窗悬网丝。\n琴闲凤丝。\n伤心聊写乌丝。\n问人归几时。",""],["何事淹留。\n朝来春色，又遍皇州。\n绮陌烧灯，凤城挑菜，吹面风柔。\n招寻漫逐鸣驺。\n回首处、伤心旧游。\n燕子穿帘，杏花倚槛，小小红楼。",""],["消忧何处，爱张融、舟屋轩窗偏阔。\n绿树阴深新雨后，一架藤花争发。\n文酒移情，云烟过眼，俯仰尘襟豁。\n枯桐挂壁，鞠通隐隐曾啮。\n客有江左风流，郢中高调，抱取金徽拂。\n四座无言灯影静，清响传来超忽。\n曲奏离骚，肠回冰炭，宿鸟惊林樾。\n嗒然相对，当檐飞出明月。",""],["禁烟时节好花开。\n客思暗中催。\n几树垂杨，一庭芳草，小雨燕初回。\n春光记得江南早，林际倒深杯。\n杏子衫轻，藕丝裙软，游女踏青来。",""],["春正好，雨丝丝。\n湿花枝。\n朱户掩，画屏围。\n耐轻寒，听细响，夜何其。\n三更后，梦迟迟。\n几多思。\n灯影涩，漏声稀。\n恨残红，愁嫩绿，晓来时。",""],["灼灼花开溪水上，天气艳阳中。\n断桥野岸芳菲满，把碧流、染就嫣红。\n沙鸟惊波，游鱼骇浪，春到绡宫。\n木兰艇趁东风。\n好景武陵同。\n最怜十里五里浅濑，明霞一片轻笼。\n渔父旧时应有，恨舍棹去匆匆。",""],["苏门曾说孙登啸。\n又何似、仲举清歌偏好。\n一曲和皆难，听余音缥缈。\n漫写江南肠断句，又变作、离奇夭矫。\n高调。\n是乌丝旧唱，迦陵新草。\n还忆往日风流，向旗亭画壁，双鬟争道。\n廿载飘零，剩髯霜多少。\n天子凌云思赋手，喜岁晚、遭逢非小。\n堪傲。\n有牛腰词卷，将人压倒。",""],["停帆旧是兵戈地，寂寞城𬮱。\n肠断行人。\n何处炊烟一缕新。\n屏风九叠干霄立，翠染波纹。\n多谢匡君。\n双剑峰高割晓云。","停帆旧是兵戈地，寂寞城闉。\n肠断行人。\n何处炊烟一缕新。\n屏风九叠干霄立，翠染波纹。\n多谢匡君。\n双剑峰高割晓云。"],["高阁尚岿然，背江城、俯瞰东流朝暮。\n双桨溯波来，登临好、襟带风烟无数。\n断霞缥缈，孤飞犹是当年鹜。\n潭影悠悠浑不定，送尽几番歌舞。\n最怜词客消沉，有残碑剥落，半欹古础。\n胜地走戈铤，帆樯集、乍息一天鼙鼓。\n倚栏呼酒，黄昏还听涛声怒。\n归去蓬窗明月上，照我醉眠南浦。",""],["远水拖蓝，晴峰送翠，徐牵三板轻船。\n野岸风筝，撩人恰是新年。\n垂杨不负东君约，袅鹅黄、一色堪怜。\n更悠然、几处渔歌，几点村烟。\n家山回首斜阳外，但萋萋芳草，淼淼长川。\n十八滩遥，舟人指向鸥边。\n红牙漫拍王孙句，倚蓬窗、聊破愁眠。\n莫垂帘尚有江梅，尚少啼鹃。",""],["过雨西湄，草堂里、闲看新涨。\n病初起、尘襟顿遣，诗怀无恙。\n波影如云当岸走，芦花似雪缘阶上。\n见携来、尺半鲤鱼肥，邻翁饷。\n衰柳下，扁舟漾。\n夕阳外，渔歌唱。\n更举杯邀月，同倾花酿。\n高兴漫裁金缕曲，狂游还觅青藤杖。\n但烟霞、深处作生涯，真无状。",""],["堤柳添烟，苑花飘翠，匆匆过了三春。\n雨霁风恬，清和撰就嘉辰。\n闲庭草色如茵。\n映方塘、碧水粼粼。\n单衣初试，疏帘乍垂，密簟先陈。\n几多恨叶，一片清波，沈腰带减，潘鬓霜新。\n山茫水渺，风流何日还亲。\n犹记同君。\n看双双、燕拂梁尘。\n到斜曛。\n蔷薇架边，坐对仙裙。",""],["密蕊临风香细。\n艳雪几枝分缀。\n不复结春愁，占断小园秋霁。\n庭际。\n庭际。\n妒杀一丛丹桂。",""],["杨柳春城驻幰车。\n罗衣掩映女墙斜。\n江南装束是谁家。\n城下有人闲伫立，芙蓉朝日望来赊。\n一春愁绪又添些。",""],["伏日炎蒸，长安道、喧传洗象。\n正翻盆急雨，御河新涨。\n隔岸乍闻吹画角，归途已见排仙仗。\n有乌蛮、赤脚跨将来，岿然状。\n飞楼启，乘舆上。\n天颜喜，宸游畅。\n奈冲泥后至，翠华徒望。\n暮返柴扉仍寂寞，吟成斗室添萧爽。\n笑吾生、万事总蹉跎，休痴想。",""],["澹荡西风，尽吹却、鳞鳞鱼涨。\n高会处、银蟾乍涌，清光无恙。\n桂影婆娑河汉外，露华沾洒梧桐上。\n正遥天、一片好秋容，来相饷。\n擎玉斗，香醪漾。\n按象板，吴儿唱。\n渐更深漏转，薄寒初酿。\n谁继谢庄今夜赋，空传公远当年杖。\n羡素娥、相对舞霓裳，纷千状。",""],["清和新霁，杖孤筇、野外追随上客。\n望去琳宫千树里，磐响乍传遥碧。\n山色当门，葵花盈砌，到此尘嚣隔。\n衔杯籍草，赏心更拥图册。\n谁道冠盖京华，偏容吾辈，泉石留行迹。\n醉后看松过别圃，细雨沾衣将夕。\n公瑾风流，伟长词赋，此会高今昔。\n岑参兄弟，愿言常奉游屐。",""],["雨做清愁，人添羁恨，几处花放春城。\n招寻初地，修竹倚茅楹。\n千叶桃花灼灼，苔墙上、薜荔抽萌。\n开樽好、邻园灌木，百啭听流莺。\n移情。\n当此日，山僧乍遇，人淡诗清。\n更书同颠米，笔阵纵横。\n向夕花前小住，狂歌发、共掩柴荆。\n天将霁、朦胧片月，深殿一钟鸣。",""],["席帽聊萧，尘襟冷落，恰喜骚人相见。\n永夜衔杯，珍重红牙低按。\n乍飘来、管脆丝恬，任听去、魂消肠断。\n看灯前、年少吴趋，风流并极一时选。\n谁怜吾辈倦客，潦倒长安市，岁华偷换。\n邂逅欢场，莫道漏沉星转。\n赋短句、宋玉增悲，纵高谈、方干忘倦。\n问篱畔、菊有花不，还期花下宴。",""],["作客经时。\n葡萄引蔓，绿透书帷。\n雨后追凉，风前听籁，月正如眉。\n中宵无限凄其。\n奈短笛、邻家又吹，踏遍苔钱，寻来萤火，排遣些儿。",""],["斜日照清嶂，落叶下金台。\n故人辞我南去塞雁一声来。\n莼菜苕溪堪摘，茅屋苹村无恙，遥指白云隈。\n相送潞河上，萧瑟荻花开。\n倚门望，归棹急，肯徘徊。\n江风渔火偏喜岁晚谢尘埃。\n到日浣裙调膳，暇日登山临水，野老对衔杯。\n史馆须椽笔，好与雁同回。","斜日照清嶂，落叶下金台。\n故人辞我南去塞雁一声来。\n莼菜苕溪堪摘，茅屋蘋村无恙，遥指白云隈。\n相送潞河上，萧瑟荻花开。\n倚门望，归棹急，肯徘徊。\n江风渔火偏喜岁晚谢尘埃。\n到日浣裙调膳，暇日登山临水，野老对衔杯。\n史馆须椽笔，好与雁同回。"],["帝城幽绝处，孤台起、突兀古墙边。\n叹车马此时，几人休歇，林丘我辈，随意盘桓。\n恰还有，彩毫堪共赋，清酒罄交欢。\n佳气郁葱，瞻来北阙，岚光重叠，送自西山。\n斜阳风吹落，冰轮皎又见，涌上天坛。\n各自迷离烟树，指点乡关。\n正西湖雨后，荷香十里，梁园月下，竹影千竿。\n何事莼鲈高兴，偏让张翰。",""],["老矣陈琳，悲哉宋玉，披襟共此清秋。\n恰重阳又到，载酒楼头。\n君言计日江南去，看霜林、橘柚如毬。\n未成分手，偏宜对菊，醉发狂讴。\n鼓枻漫逐河流。\n有萧娘窈窕，潜贮商丘。\n问故乡虽好，可否同游。\n天涯况未销烽燧，罨画溪、莫说寻幽。\n好将彩笔，登台赋雪，一笑淹留。",""],["列戟朱门，雕桥珂里，喜见悬弧。\n恰凤雏载诞，参差玉笋，麟儿同育，错落骊珠。\n如此奇逢，真称佳话，岂复寻常吉梦乎。\n须知道，是尼山鹫岭，送自云衢。\n匡时共说司徒，宜阶下、芝兰秀色敷。\n羡食牛之气，抱来竟爽，惊人之骨，望去皆殊。\n千里神驹，一双英物，异日追随殿陛趋。\n开筵处，任名流作画，歌客操觚。",""],["巷子条条看尽似。\n但尘影、连天起。\n笑弹指、光阴直个是。\n吃过了、樱桃矣。\n插过了、荷花矣。\n剩有瓶中三日米。\n且自翻书史。\n问何不、归欤偏恋此。\n还要看、萤光耳。\n还要听、蛩声耳。",""],["宝髻盘云，绛绡笼雪，内家妆束风流。\n向石边小憩，藏却钿钩。\n还有侍儿执扇，苔径里、映带温柔。\n伤心也，杏花在手，凝盼枝头。\n啾啾。\n绿衣娘子，爱惜杀春光，芳树能留。\n好教将言语，等待宸游。\n似欲殷勤重问，长门赋、汝会吟不。\n摩挲叹，一方素练，貌尽宫愁。",""],["映日齐开红萼。\n霞光交错。\n独从初地占侬春，似空谷、佳人托。\n忆昔看花张幕。\n天香薰酌。\n只今惆怅近雕栏，将胜事、思量着。",""],["纤腰恰傍垂杨树。\n瞥然惊遇。\n寻常梳里可怜人，一缕腻香风处。\n白板门边归去。\n盈盈微步。\n斜阳飞絮奈何天，直欲作、高堂赋。",""],["宝髻八盘倭堕，樱唇一点鲜圆。\n低回无语风前立，顾影自生怜。\n珠泪玉烟谁写，腻香真色俱传。\n明妃不减夭矫态，应费画工钱。",""],["写鸟能生动，描花吐艳姿。\n深闺纤指露清奇。\n不数黄荃崔白画家师。\n倦倚红红笔，愁凝小小眉。\n莫教风雨妒胭脂。\n留待双双富贵白头时。",""],["筠廊秋艳菊花丛。\n命秦宫。\n理焦桐。\n坐向花前，纤手动清风。\n白纻轻衫腰一把，流盼好，送归鸿。\n思量往事恨难穷。\n恁匆匆。\n水流东。\n寂寞高斋，桃萼又将红。\n独抱云和今夜里，谁忍弄，月明中。",""],["何可居无竹。\n共晨夕、惟君独。\n森森似束。\n雨枝烟叶，声飘哀玉。\n谩说千竿，如此一丛已足。\n依然淇澳。\n遍轩槛、皆新绿。\n恰宜阮籍高吟，月下轻阴满目。\n隙地无多，更种几本寒菊。",""],["记得早莺啼。\n红杏初飞。\n宋城西。\n旗亭别路草萋萋。\n回首处，暮烟迷。\n独有河梁投赠句，任远道相随。\n酌酴醾。\n醉后何为。\n行歌燕市，故人天末，几番恼杀分离。\n吹面曲尘，素衣今已化缁衣。\n中宵无寐，千种思惟。",""],["谁从比舍奏清商。\n小秋娘。\n小兜娘。\n一缕因风，袅袅度空墙。\n燕语乍停莺又啭，黄昏后，听来时，总断肠。\n断肠。\n断肠。\n起彷徨。\n月有光。\n漏正长。\n欲去欲去，不忍去、余韵悠扬。\n仿佛天边，遏住片云翔。\n好借君家苔径里，坐十日，听千巡，愿始偿。",""],["炎蒸才谢。\n正暮云敛尽，银河斜挂。\n莺燕风流，荷芰繁华，梦还惹。\n此时旅况何如也。\n举目见、新霜沾瓦。\n青荧灯火，纸窗竹屋，狂吟闲写。\n中夜。\n追思往日，向金门执戟、竞夸裘马。\n一阵西风，又送羁人，燕台下。\n急须觅破衣残帕。\n同学者、相逢如乍。\n且寻江表徐陵，月明词话。",""],["韦编三换。\n一石才过半。\n丘壑性，终难变。\n传文洛纸贵，顾曲吴绫贱。\n便便也，撑肠柱腹皆奇卷。\n日起花砖晏，短发梳还乱。\n追往事，休增叹。\n杯螯左右手，便是长生愿。\n君不见，丹楼百尺仙居幻。",""],["岁又将秋矣。\n向天涯、良朋高会，于今无几。\n馆阁雍容称好客，谁似青莲才子。\n词赋手、招来芜市。\n小院双榆新霁后，写伤心、绮语清宵里。\n争击钵，任浮醴。\n余惟翘首兴怀耳。\n正穷愁、柴门偃仰，未陪名士。\n妒杀晓风残月句，谱自娉婷女史。\n作佳话、流传不已。\n何日更成文字饮，共狂歌、一曲凉飙起。\n先寄讯，吾知己。",""],["怪髯翁、骚坛驰骤，笔锋欲断犀兕。\n生平擅绝红牙句，清致碧波千里。\n移砚几。\n对按拍、苹云一片芭蕉翠。\n含毫选意。\n羡白夹才披，乌丝初展，此际了无事。\n移情处。\n最是个人纤丽。\n老鸦飞上双髻。\n玉箫吹彻迦陵调，声入霓裳第几。\n珠槵底。\n甚悟到、诸天幻出婵娟子。\n空花蜃市。\n拟呼下当筵，琵琶试拨，划破罨溪水。","怪髯翁、骚坛驰骤，笔锋欲断犀兕。\n生平擅绝红牙句，清致碧波千里。\n移砚几。\n对按拍、蘋云一片芭蕉翠。\n含毫选意。\n羡白袷才披，乌丝初展，此际了无事。\n移情处。\n最是个人纤丽。\n老鸦飞上双髻。\n玉箫吹彻迦陵调，声入霓裳第几。\n珠槵底。\n甚悟到、诸天幻出婵娟子。\n空花蜃市。\n拟呼下当筵，琵琶试拨，划破罨溪水。"],["红晕倦眸如缬。\n春歇。\n梦回时。\n被香无赖晓魂腻。\n还睡。\n掩帘帏。",""],["小艇掠烟春浦。\n香雨。\n杜衡红。\n弱鬟斜掩画窗里。\n微起。\n绿杨风。",""],["忆待石桥金鲫。\n山夕。\n渌波凉。\n小亭红杏几枝侧。\n斜日。\n扑衣香。",""],["记得山楼日课。\n春惰。\n枕书眠。\n竹篱微映露桃面。\n红情。\n午晴天。",""],["窗午花情倦，楼春镜影妍。\n新燕啄泥天。\n枕屏围小梦，阿谁边。",""],["吊古重回远目，凭轩遥指荒丘。\n不睹西陵歌舞，唯见漳河乱流。",""],["落日乌啼影寂，春风鼠窜苔斑。\n只有千年旧瓦，曾覆当时玉颜。",""],["又向春风相见。\n梁燕。\n记得去年时。\n有个红栏共晚卮。\n思摩思。\n思摩思。",""],["天外影，人道是苏门。\n蹬覆松毛青到骨，崖封苔绣碧为魂。\n倘许一追扪。",""],["苏门好，何日得巾车。\n安乐有窝销白日，啸台无恙卧青霞。\n微咏帽檐斜。",""],["雪霁冰澌水漫流。\n鲁陂春涨绕矶头。\n携短棹，纵扁舟。\n逐鹭征凫下远洲。","雪霁冰澌水漫流。\n鲁陂春涨绕矶头。\n携短棹，纵扁舟。\n逐鹭徵凫下远洲。"],["系缆青邱万柳东。\n荷花面面午时风。\n悬箬笠，枕笼?。\n卧待宵凉理钓瞳。",""],["细雨浽溦湿绿蓑。\n白苹香里断鸿过。\n持蟹饮，扣舷歌。\n向夕渔灯炙紫螺。","细雨浽溦湿绿蓑。\n白蘋香里断鸿过。\n持蟹饮，扣舷歌。\n向夕渔灯炙紫螺。"],["认簖敲冰下短叉。\n北风猎猎背蓬遮。\n炊荻叶，蔽芦花。\n拥妇呼雏醉晚舣。",""],["晓风吹梦春色遍。\n栖稳梁燕。\n合欢衾，双凤扇。\n厌他常见。\n枕屏帆影向人来。\n又重回。",""],["花树。\n花树。\n幂历一窗红雾。\n月明寥落金樽。\n锦瑟年华断魂。\n魂断。\n魂断。\n厌煞春宵银汉。",""],["金雁。\n金雁。\n历历斜行筝面。\n红弦素手萦愁。\n迟日凝妆上楼。\n楼上。\n楼上。\n南浦渌波晴漾。",""],["何处红楼郎醉。\n侬抱春风孤睡。\n玉台前，谁共语。\n和影语。\n才到双眸晕处。\n最先知。\n剧怜伊。",""],["沙尾孤舟潮拥。\n手底离觞酒重。\n忽忽恼云帆，不似青骢堪控。\n如梦。\n如梦。\n昨夜短篷相共。",""],["欲别玉人归去。\n细雨廉纤薄暮。\n红烛静愔愔，好共绿窗幽语。\n且住。\n且住。\n衾润紫沉浓炷。",""],["正是夏头春尾。\n芍药酡颜红靡。\n向晚琐窗风，怅绝玉人孤倚。\n还喜。\n还喜。\n梦里灯花几蕊。",""],["风捻杨丝碧老。\n雨簸荷钱青小。\n何日草堂边，卧听一林黄鸟。\n堪懊。\n堪懊。\n误被软红相嬲。",""],["忆住柳庵山寺。\n幽兴随心无次。\n支枕敞晴窗，卧选万山紫翠。\n清吹。\n清吹。\n我爱涧松妩媚。",""],["拨棹春溪深几曲。\n桃花红蘸清波绿。\n渔郎怪事忆人间，归去迟。\n闭仙谷。\n俯仰青山身碌碌。",""],["秋千摇影月微明。\n到闲庭。\n绝人声。\n一点红灯，依约绿窗楞。\n敲遍阑干佯不应，拨兰烬，倦盈盈。",""],["风半廊。\n月半廊。\n凤胫灯青玉簟黄。\n别时秋乍凉。\n苹已霜。\n蓼已霜。\n碣石潇湘尚渺茫。\n关河较梦长。","风半廊。\n月半廊。\n凤胫灯青玉簟黄。\n别时秋乍凉。\n蘋已霜。\n蓼已霜。\n碣石潇湘尚渺茫。\n关河较梦长。"],["若为歌管销愁。\n荡离忧。\n忆逐残秋，征雁问扬州。\n意中漫，怜东阁，少淹留。\n谁识到来，翻送秣陵舟。",""],["最是春风情绪，无聊无赖无端。\n枕瑟孤眠思好梦，被池虚绣双鸾。\n争似蕊黄花子，朝朝贴向眉弯。",""],["仿佛玉人情态，桃花浅醉春风。\n咫尺女床仙树远，漫云宋玉墙东。\n争似猩红宝袜，朝朝约向酥胸。",""],["相见。\n鱼山畔。\n五载精诚重会面。\n云軿霞靷神仙伴。\n心感多情弦掾。\n同车还许同心绾。\n洛水春波婉娈。",""],["仙侣。\n溪边女。\n笑倚桃花相向语。\n绛帏双结同心苣。\n婉态幽欢难举。\n鸟啼乡思茫无主。\n轻别玉娥归去。",""],["难赋。\n凌波步。\n心寄君王魂定赴。\n遗情想像悲灵遇。\n斜日蘅皋空暮。\n独携遗枕循归路。\n愁逐洛川东注。",""],["相迟。\n真灵配。\n侍女重来遥寄意。\n玉盂曾作登真记。\n更付黄麟仙帔。\n墉城归去心期遂。\n云路双翔翡翠。",""],["霄汉。\n情难断。\n抚抱临歧空恋恋。\n紫房遥寄青缣怨。\n别后灵期汗漫。\n枕香衣泪留相伴。\n寂寂玉颜难见。",""],["回首。\n辞箕帚。\n殊绝苕颜惊阿母。\n玉卮难复为君妇。\n逻谷旧缘空有。\n遗君玉合君怜取。\n肠断仙都别后。",""],["何夕。\n蓝桥驿。\n百日为期难自惜。\n心坚玉臼终须得。\n共践玉峰仙宅。\n裴郎阿姊还相识。\n湘汉新诗重绎。",""],["星前角声。\n风前笛声。\n恼人日夕逢迎。\n问王程几程。\n别边酒醒。\n归边梦醒。\n忧来如月明明。\n问秋更几更。",""],["窗晓露微明，未醒双文睡。\n辗转玩琼颜，爱煞斜鬟腻。\n睡浅为郎羞，拥损重楼被。\n后夜却防郎，只枕郎君臂。",""],["紫栈已停熏，银蜡仍销焰。\n共影守残更，相惜还相厌。\n蕉萃此时心，郎定无由见。\n独有夜啼乌，仿佛闻微叹。",""],["阶怜好月痴，窗厌孤灯惨。\n无味夜来风，空逗帘犀飐。\n莫检枕函书，旧泪痕痕黮。\n都得几丝愁，萦损春山点。",""],["细雨愔愔。\n寂历红薇小院。\n殷轻雷，却纨扇。\n绿屏深。\n涎涎紫燕亸双尾。\n无语梁畔睡。\n簟痕孤，香气靡。\n暮寒侵。",""],["街鼓传三四。\n不见萧郎至。\n何物对裴回。\n玉香独见鞋。\n锦衾空艳艳。\n沉水薰来厌。\n休自听更筹。\n鸦啼金井头。",""],["梳里朝来淡。\n羞对移春槛。\n斜倚绿牙屏。\n梨花小院扃。\n独坐流光慢。\n迟日窥门限。\n蓬鬓乱双蝉。\n心慵又一年。",""],["楼外夕阳牢落。\n倚损危栏一角。\n何处见天涯。\n碧山遮。\n那似合欢双枕。\n解使潇湘路近。\n回梦惜馀欢。\n觑屏山。",""],["红索软，锦旗平。\n蝶裙轻。\n一倍春光照眼明。\n殢初莺。\n人是如云如月，天看非雨非晴。\n仿佛似闻花影里，坠钗声。",""],["雨嬲空庭，梦回失却桐庐路。\n春愁相赴。\n又是红窗暮。\n卜损金钗，怕见芳园树。\n微寒度。\n水沉销炷。\n且伴春风住。",""],["蹴踏闲愁，先生被却拘墟也。\n梦馀醒暇。\n叉手槐凉下。\n树畔驴儿，有似邯郸野。\n归去者。\n炊成潇洒。\n莫道黄梁哑。",""],["蹙惯双蛾翠损长。\n犀帘静暮堂。\n新梦断，乱蝉凉。\n慵续午馀香。\n宛转簟纹光。\n似回肠。\n清宵好更梦横塘。\n学鸳鸯。",""],["琼砌阴浓暑渐收。\n梦回楼角夕阳幽。\n晚花香里上帘钩。\n绿堕鸦鬟金雀隐，红斜宝袜玉肤柔。\n风边小立只低头。",""],["茉莉风凉沁洞房。\n琐窗斜月坠清光。\n玉人枕畔卸衣裳。\n细语低迷防婢觉，幽情宛约恼郎狂。\n暗中无奈绣鞋香。",""],["半下流苏罥绿霞。\n缓歌捉搦按红牙。\n春风先到泰娘家。\n选梦正宜衾鸭暖，昵人偏是鬓蝉斜。\n莫将销恨属名花。",""],["锦水文鸳宿处同。\n别来魂梦镇惺忪。\n分携记在绿屏东。\n执手凄凄还脉脉，回头昵昵苦匆匆。\n横波低揾一双红。",""],["妩媚风光二月过。\n轻衫不爱绣银鹅。\n蜻蜓浅碧缬文罗。\n小倦非缘思梦睡，柔情却似为春酡。\n红襟燕子又来么。",""],["风乱湘桃午倦时。\n双鬟好为掩罘罳。\n怕来春梦似游丝。\n种得碧兰怜露蕊，写成朱竹惜歌枝。\n为他情态也差差。",""],["情思恹恹厌袜罗。\n起来红日玉台多。\n关心残梦怎腾那。\n瘦损腰围如弱柳，梳成髻子是翻荷。\n当窗自惜态娥娥。",""],["笑倚秦筝理钿蝉。\n午窗兰气绝清妍。\n昵人脉脉亸香肩。\n秾李风情谁得似，破瓜年纪最堪怜。\n黑犀合子赠缠绵。",""],["柳叶眉长惯似愁。\n当欢微敛越风流。\n双文小玉总仙俦。\n梦浅羞郎还闭目，慵多唤婢代梳头。\n此乡真个是温柔。",""],["银床梧叶落渐满。\n怅流光欲晚。\n平楚高楼，连朝劳望眼。\n画屏潇湘漫展。\n恨梦破、雁和人远。\n心上秋来，问秋秋不管。",""],["船头暮笛吹寒浪。\n苹黄芦折怜遥望。\n野岸出空祠。\n灵期飏晚飔。\n无郎歌莫误。\n不是青溪路。\n夜夜对重湖。\n魂归片月孤。","船头暮笛吹寒浪。\n蘋黄芦折怜遥望。\n野岸出空祠。\n灵期飏晚飔。\n无郎歌莫误。\n不是青溪路。\n夜夜对重湖。\n魂归片月孤。"],["邯郸梦破抽身急。\n掉头怕近长安日。\n便跨白驴归。\n重寻旧钓矶。\n是非书几卷。\n失学从儿懒。\n带索好行歌。\n无劳春梦婆。",""],["春魂带梦扶难起。\n玉欹翠弱妆慵理。\n不用郁金油。\n鬟云腻欲流。\n一双罗袜瘦。\n小凤娇红咮。\n著罢立盈盈。\n兰阶无限情。",""],["玉阶浥露缃钩小。\n拗来豆蔻含清晓。\n何处惜芳菲。\n春光绣蝶衣。\n却归妆镜畔。\n伫立成微叹。\n还理乱衾窝。\n怜他伴梦多。",""],["抛侬几尺烟波路。\n断桥难断魂来去。\n何处望全迷。\n西陵更向西。\n欲知情郑重。\n验取宵来梦。\n可耐不成眠。\n乌啼又曙天。",""],["白云不恋恋温柔。\n曾记卧红楼。\n玉奴笑回莲脸，亲为试箜篌。\n云影散，雨香收。\n漫凝眸。\n几棂淡月，半臂浓香，一寸眉头。",""],["暗烛影疑冰，饥鼠声如雀。\n窗隙寒风和漏来，梦又成耽阁。\n归计尚蹉跎，春事全萧索。\n此际殷勤觅睡方，欲下真无药。",""],["春欲赋归欤。\n饯汝青门路。\n咄汝能偕愁共来，好拉愁同去。\n春谓君良误。\n愁与君何杵。\n此日幽拘除却愁，谁与君同住。",""],["宜人最是横波慢，睡态融融。\n红烛微蒙。\n杜牧清狂也到侬。\n愁君姓字偏难忘，耳畔东东。\n他日车中。\n怅绝轮边断续风。","宜人最是横波慢，睡态融融。\n红烛微濛。\n杜牧清狂也到侬。\n愁君姓字偏难忘，耳畔东东。\n他日车中。\n怅绝轮边断续风。"],["流苏不闭三春梦，宛转梨云。\n一霎氤氲。\n洛水湘波在宋邻。\n醒来无事消长昼，卧损秾春。\n莫问芳辰。\n春絮春花惯恼人。",""],["竹西清署。\n昨岁称觞曾暂去。\n慈母缝衣。\n又逐寒枫草草归。\n湘累新愁。\n二老遥闻魂应断。\n念此如何。\n梦溯清淮夜夜波。",""],["早年似陆。\n夜夜书灯还接屋。\n中岁如苏。\n雨驿梧声怨索居。\n只期暮齿。\n下泽同驱吾共尔。\n谁意而今。\n洒泪题诗寄卯君。",""],["谢家小女。\n少日红闺深处贮。\n嫁与黔娄。\n画匠金钗廿载愁。\n甘同终窭。\n未忘牛衣中夜语。\n只为梭巡。\n偕隐心惭举案人。",""],["桃花靧雪。\n掌里双珠光似月。\n几载身傍。\n次第鸠车看绕床。\n堪怜弱岁。\n𫗴橐崎岖为汝累。\n莫事诗书。\n殷鉴于今近在余。","桃花靧雪。\n掌里双珠光似月。\n几载身傍。\n次第鸠车看绕床。\n堪怜弱岁。\n饘橐崎岖为汝累。\n莫事诗书。\n殷鉴于今近在余。"],["谁云弄瓦。\n绣褓相怜无异者。\n弱女非男。\n也与陶公慰醉颜。\n还思卖犬。\n笥屐他年亲嫁遣。\n此意悠悠。\n面壁娇啼我欲愁。",""],["紫囊曾赌。\n早日阶兰欣在睹。\n昨岁于菟。\n乍见牵衣更捋须。\n经时离别。\n频梦芜城耏水月。\n羯末封胡。\n此日幽忧倍忆渠。",""],["单车宵引。\n铁网珊瑚思采尽。\n深院梧桐。\n红烛三条见至公。\n玉壶秋月。\n人道欧公清鉴别。\n我罪伊何。\n默默凭谁讯汨罗。",""],["还知别后。\n人工炉烟宛转瘦。\n灯底风前。\n憔悴苕华只自怜。\n凭谁寄语。\n莫为藁砧徒自苦。\n有日归兮。\n携手同君赋五噫。",""],["浥尘小雨清明近。\n几番花信。\n重来玉剪双双趁。\n玳梁堪认。\n故巢新补芹泥润。\n落红相衬。\n流黄机畔人回瞬。\n陡添娇晕。",""],["回首碧山栖，四面远天为壁。\n窗启俯临层𪩘，看偃松苍积。\n花关长昼不曾开，猿鸟共休息。\n卓午聒回幽梦，是衙蜂喧日。","回首碧山栖，四面远天为壁。\n窗启俯临层巘，看偃松苍积。\n花关长昼不曾开，猿鸟共休息。\n卓午聒回幽梦，是衙蜂喧日。"],["晨睡起。\n倦眼微瞤秋水。\n且散娇慵春径里。\n露桃开几蕊。\n亸态风前如倚。\n扑乱杨花斜坠。\n正忆桐庐人未至。\n蛛丝轻送喜。",""],["深宵寂。\n暗烛晕成愁色。\n小婢开帘寒侧侧。\n梅花明夜黑。\n雪片风边瑟瑟。\n带个雁声凄历。\n孤枕愁听莲漏滴。\n枕痕朝看湿。",""],["晴空淡幕。\n远飞来、互鸣似索。\n鱼鳞云影断续，斜河正络角。\n几个疏星作作。\n井梧飘、酒怀乍恶。\n楚天秋水浩渺，寒沙几处落。",""],["秋眉碧。\n月明几夜流黄织。\n流黄织。\n谁家阑角，乍飘风笛。\n锦机羞镊鹣鹣翼。\n远书漫说长相忆。\n长相忆。\n玉笼愁绝，相思声只。",""],["个侬名字似东东。\n记曲又红红。\n眉月幽幽，鬟烟约约，肤雪蒙蒙。\n缥缈风情看不定，几处认巫峰。\n帘底樽前，花边竹外，掌上图中。","个侬名字似东东。\n记曲又红红。\n眉月幽幽，鬟烟约约，肤雪濛濛。\n缥缈风情看不定，几处认巫峰。\n帘底樽前，花边竹外，掌上图中。"],["泪眼非如潮有信。\n话到离愁便晕。\n此际看尤俊。\n横波那为多啼损。\n家住西泠还较近。\n苏小同心试问。\n莫忘相思分。\n却教油壁全无准。",""],["共子真同魂与魄。\n不道轻轻便坼。\n无奈离魂急。\n独留残魄谁相匹。\n检点屏帷寻旧迹。\n印臂钗痕未失。\n立尽窗儿黑。\n愁来那辨阡和陌。",""],["忆得相逢春欲暮。\n油壁西陵乍度。\n缥缈花和雾。\n风流欲压陈王赋。\n卖眼灯前回一顾。\n脉脉幽情早付。\n好月当窗处。\n背人却把心期诉。",""],["箫局晨香袅，流苏晓梦还。\n十三小女绿鸦鬟。\n情似十三明月，未全圆。\n花影红屏午，春光碧户传。\n抱来雁柱十三弦。\n已觉一弦一柱，思华年。",""],["琼树蒙蒙映，红窗漫漫流。\n雪儿好为唱无愁。\n休负一规亲切，照藏钩。\n珠露从教湿，金樽莫遣收。\n余光潋滟小眉头。\n不似清秋楚楚，咽箫楼。","琼树濛濛映，红窗漫漫流。\n雪儿好为唱无愁。\n休负一规亲切，照藏钩。\n珠露从教湿，金樽莫遣收。\n余光潋滟小眉头。\n不似清秋楚楚，咽箫楼。"],["愁似水潺潺。\n百意阑珊。\n几棂风做晚来寒。\n倩酒浇愁愁不顾，醉也无欢。\n岸帻倚疏栏。\n愧负青山。\n试歌行路古来难。\n何似随僧闲洗钵，溪畔松间。",""],["绣幕晚来重。\n怪底香浓。\n丁香如梦月胧胧。\n红烛殢人耽笑语，过了疏钟。\n倦眼玩酥胸。\n脂肉芙蓉。\n娇羞银蒜罥青虫。\n往事临风休更忆，吹乱心蓬。",""],["游屐息春忙。\n著雨幽墀似曲塘。\n砌外三桐层碧引，过墙。\n接叶愔愔覆草堂。\n摇日夕窗凉。\n破梦棋声静曲房。\n入夜流萤依竹见，还藏。\n簟展方流玉水长。",""],["愁剧意模糊。\n粽子还能益智无。\n且碾朱砂浮药玉，胡卢。\n图得闲愁半日逋。\n醉里惜幽拘。\n吟罢怀沙日又徂。\n记得弇州诗句好，非诬。\n信有人间屈左徒。",""],["茫茫交集情谁织。\n谓驱愁去愁仍蛰。\n放来屈赋就怀沙，腐后迁书传货殖。\n诗书赢得妻孥泣。\n孺仲妻贤真莫及。\n蓬头历齿任痴儿，有目何烦知六七。",""],["三春日日和愁住。\n愁汝来前与汝语。\n连朝愧汝太殷勤，我醉欲眠君且去。\n麾之不去愁良误。\n心已厌君君好喻。\n不然便觅一丸泥，封却汝愁来往路。",""],["只须冷笑，无烦细说，世事尽多鹘突。\n楚囚莫更泣南冠，教达者、嗤人录录。\n且酣醇酒，试弹长剑，醉罢一歌独漉。\n庄生齐物有遗篇，说千古、觞延彭促。",""],["瑞脑烘猊，素筝排雁。\n绿窗深处新妆淡。\n娇春偏觉眼波慵，宜人更是心情慢。\n佩响微风，琴鸣幽涧。\n还疑天女将花散。\n春光秾日惜分携，碧城缥缈愁无限。",""],["最惜东堂花树好，几枝掩雪骄霞。\n春宵胜引酒情赊。\n共倾银凿落，细玩玉夭斜。\n群季惠连真不让，新诗同竞妍华。\n十年踪迹似风花。\n赤栏楼角月，应解忆天涯。",""],["倾鬓颓云肩亸玉。\n髹几光凝，双映修蛾绿。\n仿佛风光屏外足。\n摊书停却寻春躅。\n炉里双烟青断续。\n玉砌红帘，不似牵萝屋。\n公瑾伯符皆不俗。\n知无一事萦心曲。",""],["翠幰红帘晴少翳。\n花驿风香，渐觉秾春至。\n漫道鹃声堪坠泪。\n木棉红照人颜腻。\n江路盘回山路细。\n谢女吟成，旅思清如水。\n彤管自怜多画意。\n幽修分得浮岚翠。",""],["雨后桐阴清似沐。\n苔色盈阶，淡月明于玉。\n此际流萤飞簌簌。\n穿廊黏砌纷空曲。\n才堕花梢还入竹。\n欲下仍高，偏旁池边屋。\n巧入风帘轻扑扑。\n幽光凉映须眉绿。",""],["渔屋低低茅作瓦。\n几湾碧柳真潇洒。\n此地风尘原不惹。\n渔父者。\n于中结个持竿社。\n乐事常年殊未寡。\n扁舟不系随波写。\n濯足舷边刚没髁。\n言不假。\n垂鞭笑煞先生马。",""],["湖岸渔村周似抱。\n家家门径开芳草。\n向背渔罾殊窈窕。\n凌晓到。\n晴矶已有垂杨扫。\n坐看点头行水鸟。\n近家何用收纶早。\n两桨一舟堪送老。\n波面好。\n宽闲不与欧争道。",""],["昔游记向西陵去。\n回油壁、个人曾遇。\n一笑灯前，春心暗掷幽情注。\n顿使情愁如滤。\n柳枝带结同心屡。\n尚惆怅、乌啼窗曙。\n可堪别后，云中无复来香雨。\n忍看玉炉双炷。",""],["淡妆轻裹。\n柳慵花堕。\n畅幽情、鸱夷仙舸。\n茉莉风凉，泊向段家桥左。\n悄窥人、月痕星颗。\n别来无那。\n魂销梦伙。\n寄离愁、雁儿难逻。\n烛烬宵深，独有单衾同我。\n问何时、酒怀能妥。","淡妆轻裹。\n柳慵花堕。\n畅幽情、鸱夷仙舸。\n茉莉风凉，泊向段家桥左。\n悄窥人、月痕星颗。\n别来无那。\n魂销梦夥。\n寄离愁、雁儿难逻。\n烛烬宵深，独有单衾同我。\n问何时、酒怀能妥。"],["何日山中，真结三间茅屋。\n更周遭、千章山槲。\n客稀睡足。\n人幽影独。\n映虚窗、晚峰添绿。\n抱膝无营，并绝周妻何肉。\n有春畦、芹香堪斀。\n松声谡谡。\n溪声续续。\n问从游、白鸥苍鹿。",""],["砌外一林竹。\n爱萧散、供幽独。\n闲窗拂戛，昼长卧听，音和笙筑。\n雨重风轻，姿韵看来难足。\n露晞烟晓，受初日、开寒绿。\n夜深还又，月浮乱碧，宛然空谷。\n那得湖州，图取变态千幅。",""],["阳春三月。\n袅袅东风急。\n陌上桥头吹不息。\n渲得短丝成碧。\n看嬉春黄鹂恰恰。\n怜娇色。\n晓日红楼辟。\n似有个、盈盈立。\n敛修蛾、且罢流黄织。\n灞岸条垂，玉关梦杳，袖向晴光暗湿。",""],["别恨曾谙，往事重拈。\n记临歧、暮色红帘。\n牵衣回抱，细语喃喃。\n见眉痕重，泪痕滴，酒痕咸。\n峡云归后，雨来空识，只宵阑、梦断魂黏。\n孤眠无赖，回忆何堪。\n是炉香歇，发香腻，被香甘。",""],["落拓心情，寂寂难销长昼。\n看罗巾、合欢双绣。\n殷红知是啼痕透。\n梦里蘅芜，往事空回首。\n记楼头细语，暗萦纤手。\n态盈盈、脸红宜酒。\n怅萍踪雨落青天信，芳心一寸，恩怨应双有。",""],["清宵盼盼银河路。\n只惆怅、华年去。\n密约芳期经几度。\n红弦翠管，风帘月簟，并与人何处。\n别时夏杪春还暮。\n燕燕莺莺漫成句。\n旧事萦心还几许。\n微酣曾访，短篷相遇，荷叶西陵雨。",""],["凌波不过横塘路，但目送，芳尘去。\n锦瑟华年谁与度？月桥花院，琐窗朱户，只有春知处。\n飞云冉冉蘅皋暮，彩笔新题断肠句。\n试问闲愁都几许？一川烟草，满城风絮，梅子黄时雨。",""],["沙畔文禽，双双锦羽。\n依绿萍、妥梦芳洲，唼红杜、寻欢遥浦。\n那还羡、紫燕交飞，青鸾偕舞。\n冷觑绣床娇女。\n抛残针镂。\n散娇慵、水槛闲凭，照宛约、玉台空妩。\n晚归去、凝视红衾，黯然无语。",""],["淡淡双眉萦远岫。\n草草凉襟还小袖。\n曲廊深处为侬来，随夜漏。\n乌栖后。\n枕臂啼痕红欲透。\n抚抱纤腰春更瘦。\n凝怨横波娇不溜。\n如思如懊转宜人，看巾绣。\n嗔相扣。\n痛惜肯教衾浪皱。",""],["河满不堪临别听。\n别酒醉来容易醒。\n持侬只问几时来，频揽镜。\n怜光景。\n此意料君能暗省。\n离绪最愁窗色暝。\n明月又还窥只影。\n空房应是怯孤眠，风欲定。\n钟初静。\n踏遍合欢廊下径。",""],["游春梦好殢元郎。\n恼侬狂。\n昵侬狂。\n燕子莺儿，底事送春忙。\n花露未晞云影散，痕在臂，泪沾裳。\n锦屏仿佛剩春光。\n枕馀香。\n簟馀香。\n髹几文奁，无复映晨妆。\n小叠红笺书恨字，凭谁寄，向伊行。",""],["花间叶外。\n又见蜂黄退。\n阶影慢，帘阴碎。\n合欢金缕枕，双绶红鸳带。\n人去也，银灯晕里羞相对。\n尚记横塘会。\n荷叶青如盖。\n纵已杳，魂犹在。\n凤奁香欲殄，蝉鬓云将改。\n无奈是，愁心一寸深于海。",""],["袁生把臂。\n珍重频相谓。\n从少日，依堂背。\n丸熊良已苦，坩鱃谁曾馈。\n图反哺，清霜几下慈乌泪。\n太息钦君意。\n菽水君何愧。\n门子洁，风人贵。\n母持灵寿杖，儿作斑衣戏。\n歌一阕，为君侑祝千秋岁。",""],["君家称寿。\n海内文章走。\n夸盛事，纷人口。\n颇闻黄发媪，早作青灯妇。\n冰雪里，藐孤涕泪曾相守。\n剃剪陶家久。\n台筑怀清旧。\n兼两事，须推母。\n春晖君解报，善颂吾何有。\n唯愿取，新安江水成春酒。",""],["文澜笔阵。\n早岁惊神骏。\n花萼继，飞腾迅。\n传经推戴德，佐郡同何逊。\n风景地，二分明月窥人俊。\n览揆当青鬓。\n底语为君进。\n却月迩，凌风近。\n玉壶冰色洁，宝瑟朱丝润。\n还自有，君家柑酒鹏声韵。",""],["浣纱江畔女儿身。\n苕艳窈无邻。\n谁人窥巧笑，独自惜微颦。\n无奈君王薪胆、催人去，遣作馆娃春。\n红兰草草吴宫事，空传鸾、雾疑神。\n还可念，苍茫一舸五湖滨。\n无赖唯馀石上、青苔迹，千载解愁人。",""],["自不能知，何事两眉常皱。\n依稀只是，无计支长昼。\n乌几凭暖，空妒双烟金兽。\n愁城无缝，密于鸳甃。\n欲浣离肠，不信有、消愁酒。\n别时略记，是欢侬共瘦。\n含泪无言，指与酸心梅豆。\n惊心又到，那时时候。",""],["路歧不用更迟回。\n任运安排。\n由来造物多颠倒，将颓颜、好付樽罍。\n急景如春有脚，逸民似古无怀。\n啼鹃休更向人哀。\n红友新开。\n裁书已报春山去，道先生、早晚归来。\n此意还如江水，东流到海难回。",""],["记分携日，斜风密雨送兰舟。\n共君无计夷犹。\n瞥眼垂杨夹岸，人影闭红楼。\n叹前期渺渺，往事悠悠。\n经春涉秋。\n梦尚隔、见何由。\n闻道吟侬旧句，红泪时流。\n侬诗总好，问争如、絮语话绸缪。\n须抛却、莫费凝眸。",""],["迎晚纱窗还闭。\n又早是、兰缸孤对。\n炉里双烟，床边单枕，合并恼人心意。\n独伊见慰。\n却繠繠、结成红穗。\n讶道来朝何喜。\n莫也似、蛛丝相戏。\n金粟非秋，银花连夜，猜料翻教无寐。\n宵阑频睇。\n焰虽残、肯将轻吹。",""],["歌阑酒歇，闷把乌巾岸。\n牢愁未涤，看空庭又晚。\n幽拘白发频添，故隐春光欲满。\n纵饶十床琼管。\n抒情短。\n当年曾记，鲁陂渔翁爱余懒。\n风尘缅邈，荏苒芳讯断。\n梦从蚁垤初回，意与鸥波共远。\n息壤旧盟须暖。",""],["日将暆，莺渐懒，寂寞梧还据。\n昧昧高天，转掌幻云雨。\n从来季主端著，君平说易。\n细思忖、都无是处。\n愁城阻。\n尽使费尽输攻，墨守只如许。\n黑漆屏风，深夜若能觑。\n好趁五柳初荣，孤松尚在，效元亮、柴桑归去。",""],["生平途较阮公穷。\n何物抵愁浓。\n香来略似垂丝柳，更拖烟、杏雨蒙蒙。\n麾去不遥，唤来便至，防煞更无踪。\n春冰化水已溶溶。\n幽郁好教通。\n延欢送恨浑无计，若寒夕、遮断帘栊。\n那似柳绵，一当春晚，吹尽任东风。","生平途较阮公穷。\n何物抵愁浓。\n香来略似垂丝柳，更拖烟、杏雨濛濛。\n麾去不遥，唤来便至，防煞更无踪。\n春冰化水已溶溶。\n幽郁好教通。\n延欢送恨浑无计，若寒夕、遮断帘栊。\n那似柳绵，一当春晚，吹尽任东风。"],["萼绿华羞，杜若香妒，阿谁得并琼颜。\n怅惘秾春，了似不相关。\n风前亸态嗔人调，却帐底、回身惜夜阑。\n此意惟侬心解，转复怜卿情重，并日寻欢。\n芍药花开，何计重盘桓。\n金猊抱炭连心热，奈玉虎、牵丝比泪潸。",""],["惜春花，愁春昼，恼春风。\n为昼长、风卷花丛。\n元微已去，星幡谁竖小园东。\n楼高台曲，朝来喜、未减芳秾。\n蝶儿翻，蜂儿闹，莺儿懒，燕儿慵。\n料都因、春色匆匆。\n绣床抛却，清眸凝损绮窗中。\n花茵堪籍，还办取、卧紫眠红。","惜春花，愁春昼，恼春风。\n为昼长、风捲花丛。\n元微已去，星幡谁竖小园东。\n楼高台曲，朝来喜、未减芳秾。\n蝶儿翻，蜂儿闹，莺儿懒，燕儿慵。\n料都因、春色匆匆。\n绣床抛却，清眸凝损绮窗中。\n花茵堪籍，还办取、卧紫眠红。"],["苹叶晴溪小，柳花春店香。\n鹅儿黄似酒，凫影白浮塘。\n偶来临风曳杖，坐喜对水开窗。\n垆侧小妇凝妆。\n莺语更如簧。\n十载羁宛洛，此日踏江乡。\n侧身吊古，茫茫金粉齐梁。\n况南徐南兖，江山如画，放怀且饮千百觞。","蘋叶晴溪小，柳花春店香。\n鹅儿黄似酒，凫影白浮塘。\n偶来临风曳杖，坐喜对水开窗。\n垆侧小妇凝妆。\n莺语更如簧。\n十载羁宛洛，此日踏江乡。\n侧身吊古，茫茫金粉齐梁。\n况南徐南兖，江山如画，放怀且饮千百觞。"],["绮砌红阑，新凉雨后足。\n微风畔，叶痕添绿。\n繁苞素蕊，媚晚色、渐开冰玉。\n最怜是、昵魄萦魂，纵迷迭，难比馥。\n美人睡起，撋馀倦、乍凝目。\n移夕簟、慵生新浴。\n盈盈小摘，枕屏夜、抱香宿。\n更双鬟、解事露华一匊。\n清晓还，陪膏沐。",""],["明河此夜，隐隐微云掩。\n织女皇姑又相见。\n问千年嘉会，乌鹊填桥，谁怂恿、不遣灵期汗漫。\n楼中人叹绝，况值迎秋，一叶梧桐落阶畔。\n正念远伤离，那得闲心，拈素缕、鸳针双穿。\n想荡子、回头望双星，也暗暗蹉跎，凉暄潜换。",""],["夏木千草，草亭长昼请如水。\n小窗高枕，回午梦、有声堪喜。\n无限风思露想，缥缈青天里。\n应识取、清音无滓。\n作复止。\n仿佛是、迎凉送暑。\n问褦襶、谁知此。\n蛙喧鹂巧，论鼓吹、难君似。\n况是居高声远，不籍秋风起。\n堪听也、须辨巢由耳。",""],["往事销凝久，把残编重读，香魂如迸。\n映红栏、弱柳怜人，伴文奁、寒梅成媵。\n随氏清娱，羊家净婉，那堪相并。\n看月坐，拥书眠，雅称夫君情性。\n如意珠沉，断肠花发，人去春风病。\n叹馆闭双成，绮窗深靓，紫?碧腴空剩。\n钏里流霞，是他年、洪都私证。",""],["四座休喧，听贱子、狂歌自祝。\n端只为、命遭磨蝎，运逢百六。\n徒欠书鱼文字债，未修沤鸟烟波福。\n念崎岖、三十九年过，唐衢哭。\n清癯相，难食肉。\n渺茫事，空握粟。\n算何须多寿，方才多辱。\n乘筏误教浮业海，携家悔不栖愚谷。\n问今朝、底物侑持觞，樽前筑。",""],["歧路悠悠，看几载、软红如簇。\n算何似、一邱一壑，纡青拖绿。\n脱却尘衫乌纳在，推开瓦枕黄梁熟。\n只而今、立地便抽身，原非速。\n甚不必，离骚读。\n大无谓，秋风哭。\n但一周虎落，三间茅屋。\n却署休休名目好，试歌纂纂儿能续。\n也胜如、侧足走羊肠，邛崃曲。",""],["检校归思，共春后、碧溪同涨。\n山有信、鹤猿相忆，钓矶无恙。\n雨渗一犁田犊喜，波添三尺河鱼上。\n道同招、冀缺共妻归，谋耕饷。\n五柳畔，晴丝漾。\n老屋上，春鸠唱。\n更掌教鸟集，花从蜂酿。\n晓日好操苹渚楫，晚风任倚柴门杖。\n纵田家、佳语愧储王，还能状。","检校归思，共春后、碧溪同涨。\n山有信、鹤猿相忆，钓矶无恙。\n雨渗一犁田犊喜，波添三尺河鱼上。\n道同招、冀缺共妻归，谋耕饷。\n五柳畔，晴丝漾。\n老屋上，春鸠唱。\n更掌教鸟集，花从蜂酿。\n晓日好操蘋渚楫，晚风任倚柴门杖。\n纵田家、佳语愧储王，还能状。"],["栗里春深，羡柳浪、层层如涨。\n更喜得、敝庐容膝，南窗无恙。\n独酌好谋形影共，高眠也自羲皇上。\n顾床头、藤笠与椰瓢，幽人饷。\n清溪侧，看鱼漾。\n远村外，听樵唱。\n况桃花堪饭，松花堪酿。\n自课织帘还有手，便从荷蓧非无杖。\n算吾生、约略可描摹，山居状。",""],["积雨湖头，看门外、岸痕添涨。\n欣乍到、屐声随遇，故人无恙。\n易得浊醪谋若下，难逢春水如天上。\n况韶光、淡宕恰新晴，天公饷。\n青雀舫，徐徐漾。\n白苎曲、愔愔唱。\n须好怀如涤，闲愁休酿。\n我醉欲持铜绰板，君闲那负青藤杖。\n任六桥、人指两狂生，多奇状。",""],["睥睨烟霞，笑人世、红尘如涨。\n都一手、移来妙喜，维摩何恙。\n褊性只宜栖物外，微名何必居人上。\n最移情、邂逅老东阿，新词饷。\n花共鸟、纷摇漾。\n皮与陆、堪酬唱。\n况胡姬肆近，老春初酿。\n休畅肯教稀步屧，沉酣未便需筇杖。\n莫轻辜、几叠好云山，朝昏状。",""],["三竺双高，新晴后、烟峦青涨。\n殊慰籍、君侯花笔，别来无恙。\n宋玉非徒唐景亚，陈王的在应徐上。\n羡新诗、字字比瑶环，须交饷。\n墨有縠，微微漾。\n歌付雪，低低唱。\n算官厨法酝，更谁解酿。\n司马高才原合腐，彦渊博学真须杖。\n怪吾徒、底事昵虫鱼，臣无状。",""],["烟雨凭栏，爱浮黛、遥山纹涨。\n同抱膝、清言移晷，松枝无恙。\n堤柳已随坡老没，竹枝谁驾廉夫上。\n拟搴云、踏遍万峰巅，为君饷。\n湖雾积，渔舠漾。\n林翠湿，提壶唱。\n向黄公垆畔，重沽新酿。\n漆后断纹仍可鼓，削馀方竹还堪杖。\n问吾曹、补劓息黥心，谁能状。",""],["杯酒从容，拂斜槛、茶烟初涨。\n断桥外、柳眉微蹙，苎萝新恙。\n顾我已甘栖庑下，如公才合居楼上。\n喜遥山、排闼送青来，还谁饷。\n看天半，晴云漾。\n听湖舫，朱丝唱。\n纵肠悭蕉叶，宜城须酿。\n试寄离心频梦草，要扶残醉还携杖。\n好舒怀、为指白苏堤，阴晴状。",""],["露湿幽兰，西泠畔、浮堤波涨。\n行歌去、声传金石，原思非恙。\n老友披襟云水际，旧游回首烟霄上。\n自归来、懒作洛中书，心相饷。\n玉河暖，微风漾。\n宫柳碧，新莺唱。\n可相携还往，同消春酿。\n诸子勉筹前席箸，野夫好植耘田杖。\n任人惊、湖海气难除，元龙状。",""],["揽撷烟云，羡抱膝、墨池波涨。\n更缥缈、湘东三管，千秋无恙。\n处士风流丘壑底，王孙门阀陈隋上。\n感殷勤、岁晏肯华予，丹青饷。\n雨枻湿，风蓑漾。\n王裴句，秦黄唱。\n总宜修耍眇，清思独酿。\n髯客遗书歌荷筱，须君搦管图携杖。\n好生情、别样写埙篪，山癯状。",""],["咄汝陶泓，问何事、幻成千眼。\n锡嘉名、曰星宿海，承之无腼。\n云梦谁能吞八九，蓬莱真见频清浅。\n主人翁、奇语匹皇坟，须君展。\n青玉赠，来荒缅。\n紫石猎，嗤环蠕。\n有奇傀梦告，神人圭冕。\n麟角一双相佐佑，龙宾十二同游衍。\n导摛玄、遐想溯昆仑，条流远。",""],["岸尾桥头，曾珍重、玉人芳约。\n奈荏苒、流光似水，离怀作恶。\n花底三春输紫燕，河边七夕怜乌鹊。\n欲消除、此病借禅机，从谁学。\n梦中路，寻频错。\n梁间月，看频落。\n更愁窥酒醒，欲来难却。\n顾我情条千缕结，怀君人柳三眠弱。\n只拼将、泪眼倚重楼，天垂幕。",""],["年少耽游冶，脱帽倚红楼。\n兴酣龙挈凤攫，文采并珊钩。\n目睨公孙妙舞，足付宾王余沥，落拓也风流。\n醉卧胡姬肆，忽忽不知愁。\n涉迷津，婴世网，任虚舟。\n小山春草，也应怪我久淹留。\n难挽韶华似水，难掇忧思如月，陶写付箜篌。\n可耐艳歌歇，白日淡幽州。",""],["白月为心，朱绳比质，生平自负峨峨。\n司空百炼，绕指已无多。\n到眼浓阴欲满，心忧矣、谣罢还歌。\n细屈指，古来谁似，磨蝎说东坡。\n茫茫无可语，朅来千缕，暗纬愁梭。\n更溶溶漾漾，难剪如波。\n可耐春光万里，尚寥落、卧盼庭柯。\n问何日，盟烟狎水，鸥鹭媚渔蓑。","白月为心，朱绳比质，生平自负峨峨。\n司空百鍊，绕指已无多。\n到眼浓阴欲满，心忧矣、谣罢还歌。\n细屈指，古来谁似，磨蝎说东坡。\n茫茫无可语，朅来千缕，暗纬愁梭。\n更溶溶漾漾，难剪如波。\n可耐春光万里，尚寥落、卧盼庭柯。\n问何日，盟烟狎水，鸥鹭媚渔蓑。"],["蓉粉嬉春，蕣姿延露，禅房胜日标奇。\n趁时芳草，正向绿墀滋。\n却似匀和獭髓，轻装就、千点红玑。\n宜人处，似斜仍亸，态倚晓风披。\n芳时。\n还怅怅，桃花靧雪，遥想仙姿。\n叹去年花下，空有前期。\n谁制护花幡子，驻幽艳、莫使花衰。\n好点注，馀春如画，留覆态盈棋。",""],["并蒂疑花，俱飞同蝶，早来相逐相怜。\n文窗幽窈，人玉与鬟烟。\n几许春风消息，只探向、明镜台前。\n鸳鸯字，背人学写，颠倒遍蛮笺。\n嫣然。\n还自惜，回眸一笑，鹦鹉能言。\n算碧楼红玉，总是前缘。\n心喜宜男待女，花共草、入佩能全。\n为欢好，一弦一柱。\n锦瑟趁华年。",""],["灵凤当雏，名花值蕊，思量往事回头。\n记帘垂犀押，镜挂珊钩。\n人似鹣鹣白鹢，行坐里、爱玩无休。\n谁能负，春风浅夜，明月新秋。\n悠悠。\n光阴荏苒，纵长绳百尺，逝景难留。\n看新来华发，旧日朱楼。\n宛宛前欢堪觅，屏山畔、薄醉回眸。\n临风立，斜阳如昔，独照清愁。",""],["梦破茫然，忆故园春昼，人境吾庐。\n衡门常掩无事，风味真殊。\n每当胜日，那肯使、莺阔花疏。\n闲曳杖，遴苔选石，都来尘思全无。\n一自罡风吹落，便十年奔走，仆仆谁如。\n却思猿朋鹤旧，渺渺愁余。\n鲁连陂上，几孤负、春鳜秋鲈。\n还怅绝，南窗睨日，静窥寂寂琴书。",""],["红殷绿浅，几许风光，撋做春昼。\n宛转重门，掩映红闺如绣。\n正芳时，成间阻，罗衫浥泪千重透。\n最难堪，是茶闲篆冷，梦回时候。\n漫凝立、𬮱阇隔断，不似雕栏，还近纤手。\n漱尽香醪，难与清愁相斗。\n残月疏钟人断后，几番挨过还如旧。\n教愁颜，共风边，新杨同瘦。","红殷绿浅，几许风光，撋做春昼。\n宛转重门，掩映红闺如绣。\n正芳时，成间阻，罗衫浥泪千重透。\n最难堪，是茶闲篆冷，梦回时候。\n漫凝立、闉阇隔断，不似雕栏，还近纤手。\n漱尽香醪，难与清愁相斗。\n残月疏钟人断后，几番挨过还如旧。\n教愁颜，共风边，新杨同瘦。"],["难搜难括，非去非来，做成一寸千曲。\n欲尽根株，除是马还生角。\n任教春风荡涤，只昏昏、月黄烟绿。\n甚追逐，最难拼更是、天寒茅屋。\n漏向眉间一半，揽清镜、已觉雾萦烟蹙。\n仿佛真形，五岳寸心矗矗。\n能令酒来都化，作鲛珠、界破幽独。\n算千种，还谁解、区别细目。",""],["醉馀惆怅绝，是从来、佳丽说扬州。\n看隋家天子，江都梦好，离别无愁。\n更有平安夜报，书记最风流。\n总此花和月，好任淹留。\n旧迹如尘难觅，空垂杨鸦暮，腐草萤流。\n望玉勾斜畔，落日淰荒丘。\n更何来、玉人箫管，唤二分、明月向珠楼。\n好怜取、红桥烟艇，试泛清秋。",""],["清盥多闲，幽阶似浣，且放湘帘垂地。\n喜长日悠悠，摆除尘累。\n一任铄石流金，只坚眠、不受红尘祟。\n乌巾常挂，青鞋懒著，庭阴清閟。\n无事。\n心容裔。\n且琼水浮瓜，冰盘荐芰。\n笑河朔袁刘，湎然何意。\n碧树晚凉飒沓，又枝上、风蝉鸣嘒嘒。\n应不羡、短壑青松，赤脚层冰情味。",""],["居恒夸我，道黄山胜处，峰峰奇绝。\n十载仳离辞故隐，磨尽鞋芒冠铁。\n却向尘中，凝思霞外，颐朵西施舌。\n行行掉首，九牛难挽归辙。\n知汝已佩苍精，朋游莫讶，轻作人间别。\n三十六峰从此去，快浴朱沙汤热。\n鹭羽为蓑，麂皮作荐，坐抚孤松拙。\n笑看足底，晴云铺海如雪。",""],["人生几许，叹经年契阔、不殊梁燕。\n西子湖头判袂后，携手又来隋苑。\n苏小车尘，钱王潮水。\n回首同飞电。\n芒芒交集，顿成洗马清叹。\n擢秀大别清湘，吾宗才子，允矣邦之彦。\n抚字阳城书下考，漫说安仁花县。\n巨眼如箕，高情似水，肯作浮云恋。\n举杯醉月，澄江莫负如练。",""],["银床缓汲，玉砌新晴，栏影愔愔细。\n峭寒斜倚。\n花阴畔、静把小铛亲试。\n云光露蕊。\n遥拖映、柔烟几缕。\n松响消、匀写娇擎，姽婳春风意。\n轻约䰀鬟鬌髻。\n看芳磁如雪，光映荑指。\n佩幽环脆。\n参差近、顿唤馀酲教起。\n樱桃小婢。\n越衬得、霍娘娇丽。\n珊枕边、徐嗅兰香，还带兰膏味。",""],["向风尘决计，急办取、鹿皮冠。\n好濡足柴桑，褰裳谷口，掉首邯郸。\n长歌采薇竟去，指烟霞、深处旧柴关。\n山雨代除荒径，春溪为浣尘衫。\n厌他拄笏对西山。\n兀兀一驼鞍。\n有锦水渔矶，黄山兔柴，洗眼重看。\n斜阳临风曳杖，值邻翁、谈笑不知还。\n怕说车轮生耳，还教置辐河干。",""],["灵均览揆重逢，幽拘欲忘桑蓬事。\n飞光如箭，出人不意，忽焉还至。\n咄咄书空，芒芒集臆，了无情思。\n况狄云望杳，谢池梦断，肱虽曲，谁能睡。\n不用出疆载贽。\n受一尘、隶无怀氏。\n人间无用，江淹彩笔，杨雄奇字。\n试问何如，披裘安稳，漉巾容裔。\n待樊笼剖破，便携德曜，变名吴会。",""],["飞腾四十明年，及今归去应非早。\n行藏略似，鸟中杜宇，虫中寒号。\n白眼倚松，颓颜就菊，吾存吾傲。\n更漠阴报瓮，忘机用拙，泊如也，无馀好。\n时复登台一啸。\n旧山公、全慵书报。\n当年入洛，士龙故态，惟馀狂笑。\n短布长镵，也应不减，隐囊纱帽。\n况白山旧隐，考槃仍在，无烦重考。",""],["玉阶画省全慵，任教细逐桃花坠。\n撩他燕胻，呢他莺啭，晓情暮思。\n天与颠狂，去来那管，重门深闭。\n看将低仍飏，依稀思妇，眠初妥，还惊起。\n才到墀心栏嘴。\n又轻黏、翠屏朱缀。\n似捎似趁，无拘无管，搅将春碎。\n解伴年年、多情春草，无情春水。\n更红帘揭处，几番偷入，伴人娇泪。",""],["浅夏萧森，犹自馀寒，襟袖时洒。\n愁来还似荷珠，不定虽多难把。\n盈樽浊酒，总来凭仗消除，片时依旧相萦惹。\n若拟绘愁形，这三毛谁写。\n东冶。\n有徒能赋，旋释髡钳，日边云下，长乐钟声，仍近漫听频打。\n柔成绕指，人道垒落刘琨，欲惭方外狂司马。\n便使赋归兮，较渊明迟也。",""],["擅江东、公瑾风流。\n况绮丽、更扬州。\n喜得龙门人未腐，买清娱、且伴遨游。\n个侬还有，黄华妙腕，绛树清喉。\n倩明珠、十斛贮将金屋，移入琼楼。\n帷灯照怯，窗日怜羞，妆成倦倚香篝。\n不为筵前矜顾曲，笑郎君、底费回眸。\n双飞好去，华清侧畔，绣岭前头。\n待他年、学誓长生，同看织女牵牛。",""],["玉壶携酒，烟舫冲波，暇日共寻城畔路。\n霁花风柳，拂槛排窗看无数。\n还时遇，金钗照水，玉佩当歌，几许芳洲游冶女。\n乱叶翳蝉，回渚行鸥，触景成趣。\n沿洄屡。\n更拟遥山舒眺，却值片云催句。\n兼带荐爽迎凉，数点疏雨。\n情休遽。\n睥睨烟际不遥，招提竹边重驻。\n听取花宫夕梵，缓缓归去。",""],["墀日烘莺，檐阴䛏燕，绿暗盈阶幽草。\n红楼小妇，解惜馀春，凭损一栏清晓。\n梧井碧影初齐，映户当轩，叶浓花小。\n恰斜纹珍簟，◇门徐展，鸟闲人小。\n亸小闷、针缕慵拈，玉床函梦，鹦鹉逗人堪恼。\n午香消炷，斜照筛窗，晚镜倦眉轻扫。\n宝袜微风暗吹，似殢如凝，春和天老。\n画屏边、罗扇才携，几个早萤低绕。",""],["小雨撋晴，微暖挼寒，阶景乍长。\n恰游丝依约，莺和柳懒，轻阴历乱，燕逐花忙。\n几处开窗，何人倚槛，领略风光青粉墙。\n伤哉仆，祗恨眉如压，天色沧浪。\n愁怀此际无央。\n漫负手、闲阶车转肠。\n看似残仍滴，依稀夜漏。\n如灰更袅，仿佛晨香。\n笺与天公，梭巡不报，且驾尻舆问醉乡。\n还叵耐，是杜康力惫，难遣茫茫。",""],["我友中牟，自序生平，达人之风。\n道闭目不窥，还成公案，折腰倘许，也胜飘蓬。\n饮不三升，瓶无半菽，日筑糟丘念困穷。\n萧散意，更香山居易，甫里龟蒙。\n悬弧五闰才逢。\n已斑鬓、行称六十翁。\n叹河清难俟，良辰馀几。\n社樗无恙，散木期同。\n诗唱黄河，书藏名岳，此寿原齐华与嵩，还相调，能十篇赠我，百闰遗公。",""],["遥望匡庐，几载幽思，忽忽南昌。\n想峰排五老，半天空翠，泉飞三叠，百尺银泷。\n林跱东西，贤传十八，胜迹心知不可忘。\n问何日，向彭蠡渡口，一苇轻杭。\n卧游把卷神飏。\n似肩拍、匡君烟路翔。\n见地回天迥，邀云入户，山深岚重，迟月升堂。\n锦涧桥边，玉渊潭侧，恍惚心清闻妙香。\n才解信，道辋川愈疾，语不荒唐。",""],["屈指词人，咄咄唯髯，跋扈飞扬。\n似波寒竟去，衣冠飒飒，烛昏欲醉，履舄茫茫。\n红豆筵中，白杨斋外，哀艳无端互激昂。\n凭人道，是秋坟唱苦，子野歌长。\n廿年落拓名场。\n便历落、嵚崎也未妨。\n看弥生单绞，挝声慷慨，陈王芋蔗，舞态回翔。\n儿女情深，风云气在。\n同此牢愁一寸肠。\n君毋让，信黠如顾虎，狂比袁羊。",""],["银汉期犹渺。\n讶今朝、人间牛女，桥成何早。\n妙誉天人三妹擅，前度刘郎还晓。\n那待得、秋风吹到。\n试向玉卮娘子问，也低头、无语微微笑。\n应听取，郎君了。\n佳期择向朱明好。\n正薰风、荷香兰气，洞房清窅。\n隔巷停车知不事，咫尺仙源非杳。\n易盼到、麻姑仙爪。\n闺里青山原解画，描新眉、莫遣新人恼。\n须摹下，张家稿。",""],["认霜绡。\n烟丝粉晕轻飘。\n隐隐见、云开花弄，一轮明月堆高。\n桂如眉、双描非敞，桃疑面、半朵同姚。\n蜀锦为茵，齐纨作扇，微凉依约井桐摇。\n应怜取、断肠花色，欲并小鬟娇。\n还指点、银瓶玉斗，缓汲徐浇。\n看迷离、流黄残影，徘徊懒下花梢。\n露侵衣、宵猊欲尽，风吹带、别鹤难调。\n银蒜愁搴，金荃羞咏，一庭花月冷纤腰。\n知何处、陈王八斗，罗袜赋蘅皋。\n空抛却、画中人在，良夜频消。",""],["芜城城北，共诸公高会，衔觞引瞩。\n相约还为文字饮，抹尽清丝脆竹。\n已歇兰芳，仍迟梅信，那得花枝簇。\n狂情无那，愁看落落枫菊。\n增有青鸟红巾，似遥还近，巧笑人如玉。\n何必苹香飞絮暖，已觉烟光堪掬。\n羞日愁春，易求难得，好句知能续。\n晚归惆怅，天寒人返萝屋。","芜城城北，共诸公高会，衔觞引瞩。\n相约还为文字饮，抹尽清丝脆竹。\n已歇兰芳，仍迟梅信，那得花枝簇。\n狂情无那，愁看落落枫菊。\n增有青鸟红巾，似遥还近，巧笑人如玉。\n何必蘋香飞絮暖，已觉烟光堪掬。\n羞日愁春，易求难得，好句知能续。\n晚归惆怅，天寒人返萝屋。"],["华披秀振，羡词成星子，琅玕十幅。\n还似楚骚传屈子，句里龙堂鳞屋。\n削迹艰虞，擅场风雅，未遣中书秃。\n何须哀怨，国香合在幽谷。\n黄九秦七虽能，那如坡老，豪气尤堪掬。\n侬向欢场歌苦调，终类季疵击木。\n画壁垆头，题巾酒次，此事推君独。\n穿云裂石，好将配入豪竹。",""],["征帆竟举，怅客中分手，旧游难续。\n洒酒船头看去浪，愁绝离觞屡覆。\n却忆频年，萍踪数聚，春草欢鸣鹿。\n子荆零雨，醉来那忍重读。\n道遇小弟仪曹，为言别久，和仲思同叔。\n畴昔逍遥堂后意，不尽远书几幅。\n淹迹江乡，倦游京国，寂寞东西屋。\n黑窑重九，会同谁把黄菊。",""],["杯残人起，便骊歌纷唱，晨征肃肃。\n一别参差真似雨，那得云龙相逐。\n才子吴融，隐人朱放，各拥孤帆宿。\n金蕉南下，又螺青似新沐。\n关吏伐鼓通晨，几朝沿溯，却过支硎麓。\n寄语章华词赋客，爱尔人文皆玉。\n鹤市烟寒，鸡陂露冷，何处张融屋。\n白云南雁，怀人漫咏兰菊。",""],["由来文字，是荒年之谷，丰年之玉。\n喜遇隐侯苗裔在，胜事选楼堪续。\n笔役风骚，腹罗经史，原委明桓穆。\n风流跌宕，驾他厨俊名目。\n况是群彦彬彬，琳琅辉映，触目如蚕簇。\n艺苑文坛相犄角，戎子支驹逐鹿，好句争呈，竹西亭畔，选尽柯亭竹。\n把来还讶，龙威书出林屋。",""],["昨来良会，喜长歌才已，短歌重续。\n杂坐挥毫纷气色，好手人思得鹿。\n大雅扶轮，小山承盖，慢戏非同束。\n奇文共赏，为欢真觉难足。\n就里才子君虞，文心肆映，绣结金还蹙。\n惆怅风流云散遽，忽忽摇魂送目。\n司马挑琴，鄂君覆被，君有兼人福。\n怜不羁旅，朔风吹老茅屋。",""],["萧然高奇，羡孔轩鸾翥，耻同征逐。\n我向伦侪惊小异，有类梦中呼服。\n锦拟文披，尘将手并，那是风尘物。\n新词幽艳，真嗤桃李粗俗。\n更有正字高才，扶舆间气，融结同清淑。\n越艳吴趋赓和好，书遍蛮笺几束。\n大白频浮，小红低唱，爱煞姜郎曲。\n绮情似此，并堪丽竖戁烛。","萧然高奇，羡孔轩鸾翥，耻同徵逐。\n我向伦侪惊小异，有类梦中呼服。\n锦拟文披，尘将手并，那是风尘物。\n新词幽艳，真嗤桃李粗俗。\n更有正字高才，扶舆间气，融结同清淑。\n越艳吴趋赓和好，书遍蛮笺几束。\n大白频浮，小红低唱，爱煞姜郎曲。\n绮情似此，并堪丽竖戁烛。"],["词场今日，问何人拔帜，阿谁夺纛。\n心识孙樵文采富，不止量珠以斛。\n日下畴双，云中独矫，袁也羞同伏。\n比来酬唱，敢云便拟皮陆。\n复是小乘初禅，愧他杯渡，肆啖人间肉。\n羡子机锋殊自有，已似南能稻熟。\n顾我何长，差能解得，不闭并门目。\n佯狂作达，余生冀享顽福。",""],["新词授我，讶笔端出没，蛟泅龙洑。\n直得苏家读史法，把酒灯前豪读。\n如此佳人，平生觅句，定耻双眉蹙。\n嵚崎历落，笑他周柳轻俗。\n自愧兴寄颓然，声如秦缶，那得同哀玉。\n笔纵不停文不点，只是枚皋拙速。\n何似君家，临风振响，韵胜丝兼竹。\n老夫辟舍，合居季野牛屋。",""],["科头箕踞，许佯狂我辈，追踪琴牧。\n况对二分无赖月，好佐听鸿灭烛。\n为语玄机，收将红泪，一唱欢闻曲。\n亭亭真似，薛涛名擅西蜀。\n更喜字比雕阴，禅同天女，怜我辞何肉。\n绮语谁云成堕落，自负前身金粟。\n漫说心摇，无劳手语，情寄横波目。\n别来怀梦，寒衾缩尽书屋。",""],["曾于曲宴，见渠侬少小，羞蛾攒绿。\n青鸟琼台烦几至，始听红窗一曲。\n局厌弹棋，豆安骰子，缘少珠盈斛。\n齐奴歌里，绿珠愁绝双犊。\n总道小住为佳，采云易化，难入忘忧录。\n佳客且教题凤去，赢得片时倚玉。\n解状幽修，语传清照，人比东篱菊。\n更贪清晓，晶帘卧看膏沐。",""],["朔风猎猎，怅停帆起柁，渭城一曲。\n此霓怜君词赋好，郑重湘东斑竹。\n得失尘轻，升沉电幻，无事论臧谷。\n瞿硎隐处，高眠不管山屋。\n最念我友唐球，诗瓢共识，艺苑称尊宿。\n闻道秋灯书细字，老去吟情弥笃。\n济上车回，江东云远，几载怀幽躅。\n东阳归去，离忧寄与千斛。",""],["兰幌灯前卷。\n便相如、愁盈四壁，一是齐遣。\n始信明眸真善睐，暗瞬秋波似泫。\n早打叠、鸾衾如茧。\n扣扣繁钦情乍定，道琴心、眉语都来浅。\n双影好，玉台展。\n三生石上精魂显。\n好摩挲、蓝桥赠盒，玉圆犀扁。\n得近佳人偏郑重，不惜乌龙字犬。\n纵病渴、谁能求免。\n从此比肩形影似，奉鸳鸯、绣谱同经典。\n红绶带，肯轻剪。",""],["上日端居，春风缓度，宛似山家。\n迟迟萼绿，晴昊待繁花。\n何处樵青供饮，祇松响、如沸炉茶。\n高眠罢，门开剥啄，喜揽瑶华。\n奚必向人夸。\n须领取、南阳独寄琅琊。\n芙蓉墅静，此物是生涯。\n那得扁舟相就，共吟尽、初柳明霞。\n堪遥忆，幽寻处处，溪草新芽。","上日端居，春风缓度，宛似山家。\n迟迟萼绿，晴昊待繁花。\n何处樵青供饮，祇松响、如沸炉茶。\n高眠罢，门开剥啄，喜揽瑶华。\n奚必向人誇。\n须领取、南阳独寄琅琊。\n芙蓉墅静，此物是生涯。\n那得扁舟相就，共吟尽、初柳明霞。\n堪遥忆，幽寻处处，溪草新芽。"],["白襕乌帽。\n搦管桐阴随啸傲。\n张绪当年。\n春柳灵和尚宛然。\n诗人老去。\n廿载名场还未遇。\n此日披图。\n惆怅韶华似辘轳。",""],["曾看新妆镜前。\n别来怊怅甚、不成眠。\n此情不拟有人怜。\n愁袅袅、空似兽炉烟。\n辜负月娟娟。\n梅花如有意、落红钿。\n东风轻软到秋千。\n遥相忆、微倦夕阳天。",""],["霄汉晴霞卷。\n近阳回、恰逢览揆，佳时天遣。\n堪羡湘东三管丽，笔露非秋仍泫。\n论黼黻、八蚕抽茧。\n经术文章兼事业，莫潘江陆海量深浅。\n光旦旦，庆云展。\n风流正不妨通显。\n看幽栖、春帆字阁，龙松题扁。\n洞里痴龙收秘帙，绝胜刘安鸡犬。\n捉鼻事、何须求免。\n肃肃容台司礼乐，听赓歌、如读唐虞典。\n还补衮，待纫剪。",""],["道大凭舒卷。\n只纵横、鸿文无范，烟驱云遣。\n往往探骊遗爪甲，颗颗海珠光泫。\n信不负、佳豪名茧。\n银汉倒悬千尺影，更沧江、屈注流非浅。\n声奕奕，宇中展。\n勋名恰并文章显。\n看千秋、景钟铭伐，螺书还扁。\n何必仙山求大药，枸杞根形如犬。\n算恨事、唯公其免。\n待向黄扉成燮理，调四时、玉烛光前典。\n筇竹杖，任公剪。",""],["雁阵秋风卷。\n逗先生、五湖归兴，浩然难遣。\n萧寺寒钟催襆被，黄菊蘸霜薄泫。\n别思裹、层层如茧。\n昨夜离堂縆锦瑟，赋酒悲、语讶文通浅。\n更漏促，意难展。\n凭他李蔡身能显。\n定何如、司空表圣，休休高扁。\n到日鹤湖弭短楫，门有衔衣旧犬。\n莼菜忆、此时应免。\n砚北著书倾八斗，笑子桓、旧论难为典。\n荷芰服，羡君剪。",""],["风柳千条卷。\n对清波、鉴窗添槛，幽情堪遣。\n鸭绿粼粼光不定，欲上人衣似泫。\n供妙咏、南藤东茧。\n除却青帘双画楫，较青溪、溪水无深浅。\n新句就，旅怀展。\n君家世以诗名显。\n更无须、兵曹遗斧，斗轮夸扁。\n笔底丹头深自秘，舐鼎那容凡犬。\n笑犊鼻、长竿堪免。\n竟欲相从沽一斗，便十千、未和春衣典。\n尘俗虑，坐来剪。","风柳千条卷。\n对清波、鉴窗添槛，幽情堪遣。\n鸭绿粼粼光不定，欲上人衣似泫。\n供妙咏、南藤东茧。\n除却青帘双画楫，较青溪、溪水无深浅。\n新句就，旅怀展。\n君家世以诗名显。\n更无须、兵曹遗斧，斗轮誇扁。\n笔底丹头深自秘，舐鼎那容凡犬。\n笑犊鼻、长竿堪免。\n竟欲相从沽一斗，便十千、未和春衣典。\n尘俗虑，坐来剪。"],["瓶拂将书卷。\n伴参差、几痕疏影，尘情都遣。\n只借徐吾光一罅，移得东篱晴泫。\n似淡墨、泼来冰茧。\n神释中宵形赠影，眼模糊、不辨秋深浅。\n斜复亚，缩仍展。\n懒鱼虽懒神通显。\n总都虑、依稀能认，叶棱花扁。\n宛尔浔阳风味在，深巷还闻吠犬。\n色相累、输君全免。\n魍魉抱疑应借问，须教参、影事翻禅典。\n情脉脉，不堪剪。",""],["武林沈母，论阃仪、端第一流人物。\n桓氏少君梁德曜，犹恨多名少福。\n夫品耆英，子才王佐，古史伊谁匹。\n令仪堆积，不能写尽湘帖。\n忽然鸾驭仙游，白云缥缈，瞻望匪风急。\n三凤一胞毛羽戢，梁父孤吟抱膝。\n锦诰何期，素车乍驱，哀痕何时极。\n山路纡絗，衣冠粲粲如雪。",""],["九龄减四，八龙少一，展也多男多寿。\n皑皑白雪双蛾，犹忆得、挽车举臼。\n家驹飞兔，宅相绣虎，指日黄银紫绶。\n墓门鹤驭若重来，正七叶、辉煌如昼。",""],["伯鸾友孟，少君妃鲍，金石齐贞比寿。\n肃雍梱内不闻声，独自理、䌟絣井臼。\n征兰屡兆，诒防多谷，天锡累累组绶。\n史家班管好标题，会待取、日华重昼。","伯鸾友孟，少君妃鲍，金石齐贞比寿。\n肃雍梱内不闻声，独自理、䌟絣井臼。\n徵兰屡兆，诒防多谷，天锡累累组绶。\n史家班管好标题，会待取、日华重昼。"],["池上荷花赭。\n映珠帘、冰盘消暑，青禽飞下。\n亲旧宾朋闲笑语，满座称觞劝斝。\n更休问、年华老大。\n绿酒金尊聊玩世，笑白云、苍狗由他罢。\n最堪乐，天山卦。\n北窗曲榭花枝亚。\n遣余年、阮宣筇杖，邺侯书架。\n学易知天从此始，说甚屠龙呼马。\n早报道、先生醉也。\n种竹观鱼都乐事，况清谭、诗卷真佳话。\n谁复数，耆英社。",""],["九月月方朔，南极应长庚。\n曙色朝烟初展，车骑满郊坰。\n已过凤池佳节，未是龙山高宴，来往甚逢迎。\n蒋径有双仲，华祝拟耆英。\n把黄花，歌白石，舞青萍。\n唾壶休击，须知铜柱接蓬瀛。\n上马试君霹雳，下马看君露布，早岁已成名。\n未遂伏波志，矍铄自骞腾。",""],["金井风微响辘轳。\n桐阴漏日晓妆初。\n薄寒犹怯玉肌肤。\n帘幕絮萦双紫燕，盆池花衬小红鱼。\n昼长耽阁绣工夫。",""],["风皱澄波绿漾陂。\n腕慵不觉荡船迟。\n欲惊沙嘴鸳鸯睡，笑掷青青芡子儿。",""],["胡波慢似眼波秋。\n自爱风流照碧流。\n嫌他年少颠狂甚，棹入荷花不举头。",""],["铁镬生梁子，铜枢种枣花。\n杨柳正藏鸦。\n闭门春昼静，是谁家。",""],["茜染墙头草，乌飞陌上桑。\n三十侍中郎。\n自矜拖紫绶，茜花香。",""],["蕙幌春前雨，花竿晚后虹。\n解珥坠青虫。\n去年曾借宿，宋家东。",""],["蕊扑鸦头浅，鬟梳虿尾轻。\n镜里未分明。\n匀残红粉絮，挂帘钉。",""],["高屧宜墙窄，长裙爱裥多。\n风起动江波。\n隔江风更急，奈裙何。",""],["旧苑罗罗在，新教略略成。\n殿上暗呼名。\n镀金黄甲子，堕银筝。",""],["双桨红船欲度。\n荷路。\n向前溪。\n叶摇倾下露珠子。\n菱刺。\n又牵衣。",""],["五月南塘水满，吹断，鲤鱼风。\n小娘停棹濯纤指。\n水底。\n见花红。",""],["杨柳枝，莫教折。\n留绾衫前散巾结。\n只恐飞花上紫纶，认作摇郎鬓边雪。",""],["花漏深，春睡醒。\n二五窥蟾半边影。\n烧残蜡泪泛铜盘，一尺珊瑚沁心冷。",""],["燕尾捎轻雾，花柎涌落潮。\n朝鲜计吏附书遥。\n三月隋堤、杨柳暗河桥。",""],["驱马东郊道，提筐南陌头。\n桑枝欲尽且移钩。\n日暮蚕饥、归去好难留。",""],["蜡晕眉间粉，裙萦履上珠。\n阳云楼上教歌殊。\n吹暖凤梢、双籥卸唇朱。",""],["涩杼嫌经密，残丝畏镊欹。\n织缣织素总难期。\n独对支机彩石、有谁知。",""],["溘匝箱金断，青红钿晕残。\n狂夫塞下几时还。\n时见琐窗、蜿蜿坠双环。",""],["掬溜愁苹卷，投竿喜藻开。\n莲舟棹女夜归来。\n争照水中、髻子落金钗。","掬溜愁蘋捲，投竿喜藻开。\n莲舟棹女夜归来。\n争照水中、髻子落金钗。"],["河没时。\n霜繁月已低。\n错惊银槅曙，起来迟。\n扶上鬓梢随意绾，乱丝丝。",""],["日满檐。\n虫飞逐槛边。\n红衫腰后结，洗妆铅。\n指拂额黄时转侧，镜台前。",""],["欲上床。\n卸头留半妆。\n残膏衔兽颈，且缝裳。\n晶环绕指先知冷，偎谁傍。",""],["漏壶移。\n还将绣谱披。\n碧窗连锁下，响朝鸡。\n坐得画裙千百褶，夜何其。",""],["湘渚头。\n水北流。\n麦天风雨绿崖秋。\n蕉叶缉纱仍染绿，荆门红树好生愁。",""],["邛竹枝。\n生古祠。\n丛丛峭壁鹧鸪啼。\n朝雨过来还暮雨，不知神女几时归。",""],["吴蛾窈窕初拂舞。\n堂下春雨。\n柳垂鋋，花转毂。\n暖翻红烛。\n只怜却舞汗衣干。\n又春寒。",""],["胡腾起作石国语。\n愁杀番女。\n罽靴尖，铜带软。\n蹴踏宛转。\n回头忽忆旧安西。\n两眉低。",""],["江上路，横曼小长干。\n日炙水花红滟潋，烟浮堤草绿绵蛮。\n高阁尚春寒。",""],["江路远，草际暗尘消。\n红药园深朝坠露，白苹渚浅夜添潮。\n人醉画栏桥。",""],["堪忆处，曲巷试单衫。\n菱井啄泥悬社燕，桃根熨火种春蚕。\n风景是江南。",""],["风景好，菰叶满横塘。\n碧带帩头骑马客，红钉屐子拢船娘。\n两两见鸳鸯。",""],["临大道，金碧绕天涯。\n出郭危楼云作埒，抱江小槛幔垂沙。\n记得那人家。",""],["前浦去，何处最能留。\n黄鸟换枝啼不歇，落花细逐往来舟。\n微月上汀洲。",""],["妆裹淡，时世在江淮。\n裙褶缓韬双笼袜，髻根松贴两梁钗。\n驱鸭去还来。",""],["频怅望，耶水与梧宫。\n谁浣素纱窥越女，因歌白苎号吴侬。\n总在石莲东。",""],["归去好，长听子规啼。\n红藕城桥风脉脉，黄梅江阁雨凄凄。\n愁思望中迷。",""],["江上市，帆落度桥来。\n两岸娼楼悬水栅，平船击板瞑烟开。\n渔火夜相猜。",""],["芳草软，朝暮籍车轮。\n鸲鹆早寒调婢子，琵琶夜雨赛姑神。\n愁杀浪游人。",""],["拨捩迟。\n歌挑舞又催。\n半折红衫遮柱，柱初移。\n慢揳银𫸩弦急，恐难支。\n不念中宵起，上弦时。","拨捩迟。\n歌挑舞又催。\n半折红衫遮柱，柱初移。\n慢揳银彄弦急，恐难支。\n不念中宵起，上弦时。"],["红帉。\n紫帉蓝绿帉。\n翠帽玉铃珠串，压金裙。\n垂手正巾徐步，毯毛深未分。\n倏见暖风吹绕，一堂云。",""],["霓裳。\n羽衣谱未详。\n玉貌何人无力，绕珠珰。\n曳得钿缨累累，履跷裙自扬。\n犹自曲终徐立，听声长。",""],["仙橘山前看橘花。\n单衫裁就橘山麻。\n春江空作揉蓝色，浪里淘来那得纱。",""],["杉木为箄竹作檐。\n江潮能苦雨能甜。\n连朝只饮檐头雨，翻道江潮错着盐。",""],["蕉叶领，橘花翘。\n红藤篾子束裙腰。\n私念鵔鸡颜色好。\n从谁道。\n栽作大郎头上帽。",""],["藤菜暖，荔枝干。\n青蛉河畔碧鱼餐。\n愿绞桄榔皮里肉，炊乌木。\n暂与小郎充晚腹。","藤菜暖，荔枝乾。\n青蛉河畔碧鱼餐。\n愿绞桄榔皮里肉，炊乌木。\n暂与小郎充晚腹。"],["赛起祠丛。\n木棉花发野椒红。\n记得丁郎山下路。\n敲铜鼓。\n九孔红螺扇遮舞。",""],["卢橘催酸。\n风生蒌叶瘴烟寒。\n自卖明珠归极浦。\n心苦。\n白氎单衫着秋雨。",""],["银床金井晓啼鸦。\n帘额上，衬红霞。\n同心栀子夜开花。\n和露折来斜。\n无好意，送与谢娘家。",""],["织金衫重懒提笔。\n双扼臂，卸来轻。\n平头吹蜡炙铜笙。\n叶底弄莺声。\n无好意，唤与顺郎听。",""],["赭门东上海潮青。\n古西陵。\n雨冥冥。\n越王宫女，着履在樟亭。\n亭下教兵遗竹矢，秋日晚，堕鸦翎。",""],["日出城头鸡子黄。\n照红妆。\n动江光。\n采莲江畔，锦缆藕丝长。\n欲问小姑愁隔浦，长独处，久无郎。",""],["江深不畜伺潮鸡。\n春和出户迟。\n浣纱稀。\n双桥钗子，填粟缀红泥，裁得荷花新样好，羞比着，嫁时衣。",""],["花萼楼前杨柳枝。\n美人剪彩自寻思。\n千丝万丝谁作样，剪来总似一条眉。","花萼楼前杨柳枝。\n美人剪綵自寻思。\n千丝万丝谁作样，剪来总似一条眉。"],["白蝶爱翻轻粉絮，黄鹂偏上缕金条。\n双眉桑叶凭君看，无奈低边是细腰。",""],["园里花成子，梁间絮作泥。\n风鸢移柱线，云母贴窗衣。\n漫摘鬓边篦，上有闹蛾儿。",""],["网户黏虫翅，帘旌压柳条。\n整钗时对镜，结襻屡回绦。\n漫折井边桃，上有合欢梢。",""],["蜡炬乍开红芍药。\n枝头又噪星桥鹊。\n还疑荡子早归来，蛛网错。\n勾眼角。\n昨晚下阶裙带落。",""],["玉茧牵丝缠宝帔。\n当胸绣出承恩字。\n朝朝独自卷衣裳，蜥蜴尾。\n长绕臂。\n谁识床头有龙子。","玉茧牵丝缠宝帔。\n当胸绣出承恩字。\n朝朝独自捲衣裳，蜥蜴尾。\n长绕臂。\n谁识床头有龙子。"],["珠雀五层宫髻直。\n红绦盘委花砖级。\n太平天子用恩多，草露潗。\n裙裹湿。\n犹许蜻蜓上裙立。",""],["墙里花枝墙外影。\n嘶䯄缓踏飞花冷。\n隔墙见得不分明，金甃井。\n银络绠。\n井面看身见斜领。","墙里花枝墙外影。\n嘶騧缓踏飞花冷。\n隔墙见得不分明，金甃井。\n银络绠。\n井面看身见斜领。"],["新殿前头骑马去。\n射生籍里名初注。\n红裆垂镫手垂丝，回盼处。\n风绕絮。\n羞抱夹金鞍子住。",""],["鱼网劈来螺粉滑。\n臂痕细压金条脱。\n背人写就两行欹，花胜缬。\n银缕结。\n纤指斜封惹脂沫。",""],["城上春云城下雨。\n倩人留婿倾春醑。\n偷将婿夹障春寒，烹雪黍。\n炊玉杵。\n调婿乡音隔窗语。","城上春云城下雨。\n倩人留婿倾春醑。\n偷将婿袷障春寒，烹雪黍。\n炊玉杵。\n调婿乡音隔窗语。"],["针管红抽丹凤锓。\n螭头金错裁双枕。\n谁家白苎夜歌来，人未寝。\n霜又凛。\n误剪葡萄紫丝锦。",""],["斑簟纹生双腕缬。\n梦中欲笑开娇靥。\n醒来记得许多情，檀兽爇。\n钗燕热。\n侍婢相看那能说。",""],["长相思，在春晚。\n朝日瞳瞳熨花暖。\n黄鸟飞，绿波满。\n雀粟衔素珰，蛛丝断金剪。\n欲着别时衣，开箱自展转。",""],["长相思，在秋节。\n复斗垂垂怨蜻蛚。\n锦纹砧，素丝镊。\n梦苦见参星，关深落榆叶。\n欲识夫婿寒，花阶映微雪。",""],["枇杷花里谁家院，近丛坛。\n青漆左厢开绣户，坐双鬟。\n着地画帘飞燕燕，当阶碧草映兰兰。\n车轮未必成三角，叉住门边那得还。",""],["阿侯十六南邻女，对门居。\n相视欲申无限意，口中朱。\n朝起青烟萦兽爪，晚来红烛透虾须。\n牙箱实裹冰蚕茧，骨里相思岂是虚。\n·金斗熨开鱼子襭，衬红裳。\n铜瓶注暖狮头炭，理黄妆。\n频呼小玉因声巧，欲写泥金恐恨长。\n那见瑶台成粉幛，果然银汉是红墙。",""],["风搅红帘。\n愁损隔帘人影。\n倩秦娥，缠越苘。\n唱吴盐。\n黄铺白锁春相望。\n高阁魂惊难上。\n那更堪，花满桁。\n柳垂檐。",""],["可惜春归。\n换得好花成叶。\n启金箱，叠絮褶。\n熨单衣。\n银钩翠笼南邻女。\n日暮采桑西去。\n怕秋胡，回道路。\n返迟迟。",""],["宁扫空床。\n怕见满栏月色。\n写金针，萦象尺。\n坐灯凉。\n屏欹漏月灯犹悄。\n坐远影儿较小。\n为孤单，长伴晓。\n似双双。",""],["纠纠珠臂绳，宛转辘轳上。\n那知双穗条，夜夜空垂帐。\n楚雀缘钗桥，胡蜂咂衣桁。\n制得懒卸头，殷勤与谁唱。",""],["校尉新开疏勒，旋右地，返轮台。\n未归来。\n夺得燕支万里，草青春已回。\n谁道于阗还有，野花开。",""],["月落武阳碑下。\n控鹊血，挽牛螉。\n看烽红。\n夜半军中女子，鼓声寒不雄。\n恰是深闺人去，梦魂中。",""],["是谁过上苑。\n试马归来晚。\n双镫武威铜。\n樱桃马颊红。\n百枝灯并起。\n解马归花里。\n花底碎金篦。\n珊瑚错燕泥。",""],["杏园初试酒。\n挟弹遮杨柳。\n醉里困金吾。\n教姬倒玉壶。\n绶丝如鹝子。\n翠帢团团刺。\n花片缀衣巾。\n衣花看转新。",""],["绿柰匝茱幮，皂角穿萝屋。\n犀槅钉明螺，眼底分朝旭。\n沅浦长，淇水曲。\n处处难追逐。\n欲见有何由，簳蜡成红烛。",""],["碧玉蒲芽短短针。\n雀罗波底刺当心。\n拔蒲归去水淫淫。\n楫染绿苔疑掩袖，幔漂红露似湔襟。\n晚风吹转北塘深。",""],["溪女妆成出若耶。\n芹丝萍蔓逼流斜。\n青苔石上浣新纱。\n爱把单鬟捎竹叶，羞将双脸近荷花。\n缇油前覆夜来车。",""],["软红江波鸭子清。\n日迟游女遍江城。\n红桥度烛缓相迎。\n细马隔裙穿镫子，平船素手拨帘旌。\n大堤春日往来情。",""],["娇女新妆村艳浓。\n四枝鬟插石榴红。\n出门还怕隔溪风。\n石镜暗飞山后鹊，荻屏销画水边荭。\n西施台馆碧波中。",""],["绿满南园孔雀栖。\n重花叠叶不通飞。\n小姑独出采蔷薇。\n珥底珠儿徒刺脸，带穿贝子恐磨衣。\n行行立立自寻思。",""],["丛鬓轻笼象格纱。\n曲尘巾皱翳朝霞。\n愁听江阁按红牙。\n簪管枉铰银盖叶，绣床空钉白团花。\n游丝飞絮近天涯。",""],["水绕空江叶绕枝。\n竹郎桥畔豆娘祠。\n佳人邂逅最堪思。\n烛近只将遮幔子，风前长自敛衫儿。\n梨花初落酒阑时。",""],["筱壁含烟澹，椒花滴露稀。\n风吹细雨晓云低。\n十二碧峰迷。\n神女祠前泪，清猿峡里啼。\n瞿塘新水曲尘微。\n行客自依依。",""],["寒雨萝衣湿，晴云蕉帔开。\n空舲峡下近阳台。\n谁向梦中来。\n丛笛江妃庙，孤舟新妇隈。\n山花石竹不须栽。\n看作小姑钗。",""],["上元少女。\n谁授玉函金筥。\n倚香坛。\n画帔藤花浅，雕钟橘乳寒。\n南宫除牒子，北斗动幡干。\n犹见春归燕，似青鸾。",""],["玄都清晓。\n坐间碧堂红草。\n女仙家。\n玉铪量星豆，金◇煮雪花。\n驻颜丹作粉，系肘箓垂纱。\n浼浼沟头水，尽胡麻。",""],["上清仙梦。\n桄到十三春洞。\n玉颜红。\n月下随王母，花前别宁封。\n黄衶潜解佩，赤舄缓弛弓。\n称名多误听，为呼侬。",""],["仙房寂寂。\n戏采瑶林珠实。\n是何乡。\n红尾梢花犬，青衣覆石羊。\n鲛丝裁绶短，鹅管呷笙长。\n倘得逢燕使，问昭王。",""],["平明受事。\n堪惜玉笄初侍。\n小茅君。\n薄雾笼青鬓，轻烟曳䌨裙。\n凤衔琪树荩，虬使玉堂云。\n恐逐童男去，思纷纷。",""],["碧箫初弄。\n暗想秦楼双凤。\n几多情。\n玉锲分芦节，金箱贮枣饧。\n蕉花含秘阁，松影落层城。\n谁捣玄霜尽，见云英。",""],["短花长叶。\n到处翠軿相接。\n洞中春。\n衣炷熬丹锡，唇脂瀹水银。\n盘囊闲系虎，麈尾笑遗人。\n总隔蓬莱路，也生尘。",""],["金巾姣好。\n长佩玉砂瑶草。\n受清虚。\n妆镜歼山鬼，香奁检道书。\n缃眉遮羽盖。\n素手涤仙厨。\n每当三五夜，望蟾蜍。",""],["赤城紫府。\n闲贮玄珑妃女。\n小仙才。\n节拥蓝丝葆，冠抽绿玉钗。\n蜂房融日粉，蝶梦绕天涯。\n何事刘郎去，不归来。",""],["蝉翅宫绡傅体寒。\n琵琶掩面夜歌阑。\n插得钿头新拨子，是红蛮。\n隔舍紫姑星会浅。\n开门乌桕雨啼残。\n曾卜金钱今始验，拆和单。",""],["小院风摇九子铃。\n临河长对牸牛星。\n欲上玉机愁杼短，织难成。\n掷缕烛翻娇凤出，萦丝泪尽湿花生。\n谁道锦文无样子，看回程。",""],["小屏山上西江曲。\n深处落梅寒簌簌。\n晓鉴菱开赭粉红，残灯穗卷香脂绿。\n草头阶刬袜钗金，花里碧钩幡胜玉。\n绕凤双簧蜡炙新，早春惊破霜溪竹。",""],["竹溪霜破惊春早。\n新炙蜡簧双凤绕。\n玉胜幡钩壁里花，金钗袜刬阶头草。\n绿脂香卷穗灯残，红粉赭开菱鉴晓。\n簌簌寒梅落处深，曲江西上山屏小。",""],["含桃着雨花如雪。\n井边吹落春云叶。\n鹦鹉结钗楼，新娘半上头。\n裁衣翻样子。\n压线盘金篚。\n十五小裙腰。\n能留线几条。",""],["山鸡栖罢乌啼树。\n迎人烧尽柑红炬。\n复钥下铜鱼。\n车前一幰除。\n褥花尝对缝。\n羞见双鸳控。\n渐减玉炉烟。\n人眠故未眠。",""],["宜城二月莺啼早。\n罗敷十五双鬟小。\n锦带约桑钩。\n使君南陌头。\n连钱嘶日暮。\n共返宜城渡。\n莫是看罗敷。\n罗敷自有夫。",""],["轻雷鹿鹿宫车转。\n晚凉偷弄邠王管。\n双甲小蠀蛦。\n黄鹂处处啼。\n春风吹欲遍。\n尽作西清怨。\n暗里换歌头。\n伊州似石州。",""],["一株柳树千条叶。\n桃根巧向梅根接。\n花坞暗相通。\n新花隔几重。\n宝函春信杳。\n水漫红鱼小。\n半格轴头丝。\n环环无尽时。",""],["日黄不上妆山面，露圆难缀珠帘线。\n种得郁金花，将来浸木瓜。\n枕屏山六扇，上有江南岸。\n岸尽是吴关，关前人未还。",""],["楚雨歇残阳。\n满庭新月潇湘。\n松花湿影坠山黄。\n帝女花竿庙旁。\n瑶瑟洞箫来极浦，风吹桂酒椒浆。\n夜半烟寒翠敛，几人能上高唐。",""],["丹殿俯嵯峨。\n洞庭秋水湘娥。\n深房鬼火暗青萝。\n呜咽神弦自歌。\n文木漆光丝缠腹，蕉花影里婆娑。\n只为相思美子，灯前一敛双蛾。",""],["枣屏深，桦烛冷。\n复壁照人双影。\n鱼坠管，兽衔环。\n一床衾枕单。\n更漏咽。\n楼头月。\n偏射小窗明蛤。\n红幕掩，鹊桥低。\n银河又向西。",""],["小檀槽，新捍拨。\n弹就夜堂秋月。\n银箭断，玉钗凉。\n烛槃红泪长。\n寒角动。\n霜风送。\n惊起金微残梦。\n关戍柝，女郎砧。\n城南秋渐深。",""],["幔钩绳，复斗穗。\n寒夜美人半睡。\n云掩絮，月胧明。\n枕函亭钏声。\n蚕烛耀。\n飞蛾绕。\n门外乌啼难晓。\n燔蕙烬，隐纱笼。\n罘罳划碎红。",""],["剪鲛丝，量兽锦。\n宽窄灯前自审。\n钿尺短，错刀残。\n晚来多少寒。\n园雾薄。\n林花落。\n水面星摇池阁。\n山犬吠，草虫鸣。\n曲房魂暗惊。",""],["井梧阴，庭树暝。\n寂寂画栏人静。\n蜡子焰，蟹衣筐。\n邻家夜绩凉。\n芭蕉露。\n零如雨。\n记得暗中欢去。\n宵漏尽，晓钟催。\n碧窗殊未来。",""],["晓莺娓娓流妆阁。\n日上烛吹红绣幕。\n束将方带玉芙蕖，裹就半鞲银芍药。\n寻花露冷胭脂薄。\n花底暗翻钗子落。\n谁开鸳锦抱轻云，误使丁娘枕前索。","晓莺娓娓流妆阁。\n日上烛吹红绣幕。\n束将方带玉芙蕖，裹就半韝银芍药。\n寻花露冷胭脂薄。\n花底暗翻钗子落。\n谁开鸳锦抱轻云，误使丁娘枕前索。"],["春殿香销锁碧空。\n夜凉宫漏悄、咽铜龙。\n银河泻地水漴漴。\n妆初洗，残粉腻沟红。\n双凤宿梧桐。\n小桃金井上、露华浓。\n长门枉自闭重重。\n珠闼迥，时拂玉阶虫。",""],["芳草茸茸翠辇迟。\n昭阳初日影、散彤墀。\n银幡彩胜戴双纚。\n金错小，剪出万年枝。\n御苑落花时。\n祠前祈百子、汉家池。\n承恩唯有臂红知。\n中宵梦，频起视胭脂。","芳草茸茸翠辇迟。\n昭阳初日影、散彤墀。\n银幡綵胜戴双纚。\n金错小，剪出万年枝。\n御苑落花时。\n祠前祈百子、汉家池。\n承恩唯有臂红知。\n中宵梦，频起视胭脂。"],["黄帕衔鳌结象床。\n卷衣长拂面、侍君王。\n衫襟深惹御篝香。\n绡幛影，隐隐见鸳鸯。\n别院罢霓裳。\n众中新赐着、殿头黄。\n年来独系绛纱囊。\n江南路，四十杜秋娘。","黄帕衔鳌结象床。\n捲衣长拂面、侍君王。\n衫襟深惹御篝香。\n绡幛影，隐隐见鸳鸯。\n别院罢霓裳。\n众中新赐着、殿头黄。\n年来独系绛纱囊。\n江南路，四十杜秋娘。"],["鳷鹊高翾负日温。\n春冰融太液、细流浑。\n懒调黄子渍香荪。\n羊车近，竹叶满金盆。\n十载见承恩。\n踏青随例出、望春门。\n却收银钥暗销魂。\n梨花落，深殿又黄昏。",""],["榆叶里，楝花前。\n烧尽白矾烟。\n娇龙自走不须鞭。\n最喜是莺迁。\n歌羽歌，舞羽舞。\n人在掌中飞去。\n雾丝裙子本蹁跹。\n何处更留仙。",""],["杏苑北，曲江西。\n残雪尚依依。\n轻轮辗絮着人衣。\n拊马夜归迟。\n蓬宴遥，莲漏浅。\n红烛万条深院。\n晓来唯听乳莺啼。\n移上绿杨枝。",""],["澧浦红兰开日暮，美人倚徙空亭。\n幽岩春竹雨冥冥。\n长思公子，愁绝翠云屏。\n碧水尚传瑶瑟怨，枨枨夜鼓湘灵。\n苍梧南去晚山青。\n楚江迁客，憔悴不堪听。",""],["秋藕丝裙春树面，龙安寺里为家。\n时来空馆倚栏斜。\n栏前新水，日日浸桃花。\n素手自撩金索动，腕绳轻约红纱。\n东风相见各天涯。\n道傍愁思，散作日边霞。",""],["高阁近花红影合，绕床还种青梧。\n西施娇小似无夫。\n黄金梯滑，不见有人扶。\n茭叶菱根遮浦暗，含情但采菖蒲。\n金阊门外夜啼乌。\n女坟前去，寒烛照东湖。",""],["晚渡潮生野火静，丛祠深对江波。\n垂鬟接黛一青娥。\n宝冠珠络，花帔贴银鹅。\n估客往来争祷赛，隔船吹凤鸣鼍。\n山低如带水如罗。\n螭头黄绢，隐隐画双螺。",""],["睡架荼蘼红刺软，雾中桄蔽轻纨。\n几番觅钏坐花间。\n香山未暖，石炭捣烟寒。\n薄絮装衣萦背胛，空悬辟冻金环。\n武溪雪净尚征蛮。\n杜鹃声杳，莫是未教还。",""],["红藕香销暑殿凉。\n玉梭横枕堕钗长。\n东楼赋得新来怨，中夜看沉龟甲黄。\n黄甲龟沉看夜中。\n怨来新得赋楼东。\n长钗堕枕横梭玉，凉殿暑销香藕红。",""],["君在教头歌昔昔，妓看垂手落掺掺。\n裙裥半将遮屐点，柘竿长是拄腰纤。\n纤腰拄是长竿柘，点屐遮将半涧裙。\n掺掺落手垂看妓，昔昔歌头教在君。",""],["楼高是处尽乌啼。\n柳外烟同翠眼迷。\n流水落花春寂寂，浮家一槛近前溪。\n溪前近槛一家浮。\n寂寂春花落水流。\n迷眼翠同烟外柳，啼乌尽处是高楼。",""],["春缸玉酒细鳞红。\n怨鸟啼花隔数重。\n银子蒜垂帘押静，新开背面两鸾栊。\n栊鸾两面背开新。\n静押帘垂蒜子银。\n重数隔花啼鸟怨，红鳞细酒玉缸春。",""],["谁向妆亭亭后别，望中烟雨带帆开。\n丝回漫水蓝如袄，黛绕横山青似媒。\n媒似青山横绕黛，袄如蓝水漫回丝。\n开帆带雨烟中望，别后亭亭妆向谁。",""],["红荷短间白荷长。\n细细风来细细香。\n浓露滑篙联艇侧，同来到处问家乡。\n乡家问处到来同。\n侧艇联篙滑露浓。\n香细细来风细细，长荷白间短荷红。",""],["寒雨江汀隔断桥。\n去时当似不来潮。\n兰浦忆人愁渺目，漫漫夜梦合花梢。\n梢花合梦夜漫漫。\n目渺愁人忆浦兰。\n潮来不似当时去，桥断隔汀江雨寒。",""],["鸠浮白水踏歌虚。\n鬓捋虫珠雀画裙。\n楼上卷裳龙女侍，沟前御宿卸妆初。\n初妆卸宿御前沟。\n侍女龙裳卷上楼。\n裾画雀珠虫捋鬓，虚歌踏水白浮鸠。","鸠浮白水踏歌虚。\n鬓捋虫珠雀画裙。\n楼上捲裳龙女侍，沟前御宿卸妆初。\n初妆卸宿御前沟。\n侍女龙裳捲上楼。\n裾画雀珠虫捋鬓，虚歌踏水白浮鸠。"],["青槐路，迤逦返长杨。\n暮云翔。\n银鱼立胛，金鹅仗带，曾骑黄马射黄羊。\n歌肆侧，酒垆旁。\n调鹰牵犬归去，愁杀羽林郎。\n花刬帽，往往赌毬场。\n暗风扬。\n薰衣透缕，隔巷细生香。",""],["金槌去，长策枣红骝。\n五陵游。\n纯钩蒯绕，缦胡缨曲，冰梢猎猎似星流。\n兄执戟，弟长秋。\n射飞逐没尝见，便殿赐衣裘。\n年正少，花发醉娼楼。\n锦缠头。\n几行歌舞，一曲遍甘州。",""],["甘州遍，羌笛又将残。\n听声寒。\n黄花碎叶，雕戈铁马，茫茫飞雪满燕山。\n边角静，戍衣单。\n红闺万里梦断，都护请生还。\n雁帛远，风急堕旌竿。\n望长安。\n甘泉铙吹，何日达萧关。",""],["秋风起，展转事长征。\n出边城。\n弯弧鹊角，佩刀犀首，趫趫斥突愿擒生。\n收敕勒，卷镵枪。\n夜凉频击刁斗，空碛答遥声。\n转战苦，车骑未成名。\n塞魂惊。\n琵琶孤冢，春草日青青。","秋风起，展转事长征。\n出边城。\n弯弧鹊角，佩刀犀首，趫趫斥突愿擒生。\n收敕勒，捲镵枪。\n夜凉频击刁斗，空碛答遥声。\n转战苦，车骑未成名。\n塞魂惊。\n琵琶孤冢，春草日青青。"],["花下影，跟人上玉墀。\n谁推倒，横着半毡儿。",""],["青草软，绿波长。\n日暮乡关思渺茫。\n吴苑隋堤何处是，满江垂柳又垂杨。",""],["云淡淡，雨丝丝。\n旧日真娘何处祠。\n横笛短箫声渐远，藕花塘子夜来时。",""],["临安去，陌上已开花。\n扇影似翻江上羽，车帘刚拂草头沙。\n缓缓好归家。",""],["临安去，陌上已开花。\n绕路烟丝笼暖去，清江日影带潮回。\n缓缓好归来。",""],["江帆暮，江帆暮。\n六月水西头。\n竹子牵来黄蛤履，荷花泛去白螺舟。\n送汝返罗浮。",""],["东风吹柳覆金堤。\n夹岸红楼望去迷。\n日映游丝卷幔低。\n画桥西。\n一树娇花鸟自啼。","东风吹柳覆金堤。\n夹岸红楼望去迷。\n日映游丝捲幔低。\n画桥西。\n一树娇花鸟自啼。"],["西施歌馆旧城东。\n画栋朱栏映碧空。\n花絮阴阴趁晚风。\n翠重重。\n石上胭脂堕雨红。",""],["光宅坊前十字街。\n桃子花开。\n杏子花开。\n钿头栎子有人猜。\n恐是铜钗。\n不是金钗。",""],["缚竹纤纤似女腰。\n欲上溪桥。\n怕上溪桥。\n黑云遮住北山坳。\n昨日风潮。\n今日风潮。",""],["木槲花间乳鹊栖。\n鹊也能飞。\n花也能飞。\n临行空记草花期。\n二月当归。\n三月当归。",""],["一桥低。\n两桥低。\n枣树湾头西复西。\n江深雨欲迷。\n早乌啼。\n晚乌啼。\n两桨归来乌未栖。\n相逢半路溪。",""],["双头钗。\n独头钗。\n一样金鹅两样排。\n钗梁起四台。\n乌帽来。\n白帽来。\n湖就矶头望几回。\n菖蒲花未开。",""],["恼杀啼鹃，逢人还道春归去。\n留人不住。\n谁要留春住。\n花絮茫茫，万点愁人绪。\n归何处，春归无路。\n莫是人归路。",""],["抱出檀槽，金丝拨子轻轻落。\n浅围罗幕。\n月上栏杆角。\n夜半嘈嘈，繁手惊相错。\n敲银索。\n梦回妆阁。\n花底飞乌鹊。",""],["南浦风微，画桡已到深深处。\n藕花遮不住。\n不许穿花去。\n隔藕丛丛，似有人言语。\n难寻溯。\n乱红无主。\n一望斜阳暮。",""],["倚床还绣芙蓉。\n对花丛。\n牵得丝丝柳线翠烟笼。\n愁思远，抛金剪。\n唾残绒。\n羞煞鸳鸯衔去一丝红。",""],["花前顾影粼粼。\n水中人。\n水面残花片片绕人身。\n私自整。\n红斜领。\n茜儿巾。\n却讶领间巾里刺花新。",""],["秋风袅袅登台。\n强徘徊。\n两两鸳鸯飞去几时回。\n钱塘路。\n西陵渡。\n总天涯。\n不是早潮又是晚潮来。",""],["平沙十里。\n滚滚江潮水。\n横下秋鹰如削，短草岸，朔风起。\n栏杆人共倚。\n旧关何处是。\n记得西施，去路残阳外，碧烟里。",""],["柳烟如织。\n病起逢寒食。\n昨夜东风吹紧，花梢上，雨来急。\n晓开铜镜立。\n镜光涵晓色。\n惊见浓云堆下，梨花月，一轮白。",""],["玉瓶春暖酴醾浅，艳杀青哥。\n窄袖摩挲。\n早把空杯弄钿螺。\n擎来误湿双条脱，重泻金波。\n斜对银河。\n唱罢甘州奈若何。",""],["珠绳初挂银河泻，花满中庭。\n露满中庭。\n懒向庭前看月明。\n山屏几褶孤眠久，梦也难凭。\n醒也难凭。\n翻愿今宵梦不成。",""],["城南暮雨。\n尚有采桑秦氏女。\n低系桑笼。\n独倚桃花一树红。\n青骢西去。\n口里衔丝衔不住。\n归到灯前。\n一任三眠与四眠。",""],["陆公祠畔。\n十里横塘行未半。\n花港深深。\n王四娘家何处寻。\n醁醅初注。\n又是孝廉船欲去。\n怕照菱花。\n对面分明又一家。",""],["小鸟踏花枝，花落如红霰。\n花树朦胧一径迷，中有佳人面。\n愁见落花多，欲去还留恋。\n扇子盛来仔细看，点点桃花片。",""],["门外绿杨堤，门里红妆女。\n何处金羁美少年，故绾垂杨缕。\n风起搅杨花，飞作廉纤雨。\n眼底迷迷不见人，且听黄鹂语。",""],["樱桃子熟竹初肥。\n南园昼启迟。\n蜂房滤粉暗成脾。\n画垣生绿衣。\n蒲雨涨，柳桥低。\n秋千深院迷。\n杜鹃啼歇最高枝。\n有人还未归。",""],["拒霜花发傍妆楼。\n楼前细水流。\n隔花初日上帘钩。\n美人楼上头。\n开碧箧，泻红油。\n镜边长坐愁。\n鸳鸯瓦热露华浮。\n玉钗寒未抽。",""],["阴柳垂庭山枕斜。\n禽鸣自上槛边花。\n深屏午梦隔窗纱。\n瓮启冰牙蛆泻酒，襟披雪眼蟹潆茶。\n临妆晚扫淡黄鸦。",""],["斜枕山庭垂柳阴。\n花边槛上自鸣禽。\n纱窗隔梦午屏深。\n酒泻蛆牙冰启瓮，茶潆蟹眼雪披襟。\n鸦黄淡扫晚妆临。",""],["溪口桃花红欲暮，浅水泛胡麻。\n行尽空林散紫霞。\n来到上清家。\n缥缈香坛松饭熟，石鼎醉丹砂。\n归路残阳噪晚鸦。\n回首乱云遮。",""],["花前鼓瑟花间听，红灯低照新妆靓。\n侍婢唤行云。\n高唐曾见君。\n玉笼香雾绕，怕见青铜晓。\n井上辘轳声，翻教睡画屏。",""],["珊瑚镂枕珠阗细。\n盘云散泽香衣腻。\n枯压鬓边花，花红印一些。\n与谁同转侧，绣出双㶉鶒。\n将枕付陈思。\n陈思思不思。","珊瑚镂枕珠阗细。\n盘云散泽香衣腻。\n枯压鬓边花，花红印一些。\n与谁同转侧，绣出双鸂鶒。\n将枕付陈思。\n陈思思不思。"],["嘉文小裹双丝纽。\n单窝认得孤眠久。\n泪浥口脂融，相逢一梦中。\n花函遮短帔，中有相思字。\n银烛夜来新，深怜抱枕人。",""],["沟头流水山头雪。\n春江几度迎桃叶。\n桃叶渡江来，江花两岸开。\n珍珠量几斛，买得双蛾绿。\n衫子绿于蛾，双蛾奈绿何。",""],["丹枫叶叶迎春小，锦茵开处香鸾绕。\n银扇隔雕栊，灯花百子红。\n檐前乌鹊曙，休遣催妆去。\n赋得夜来珠，昭容揽镜馀。",""],["雕篮细压花毬小。\n金箱叠锁珠丝绕。\n花烛满帘栊，双樽琥珀红。\n芙蓉清漏曙，晓凤衔烟去。\n慢撒帐头珠，香奁贮有馀。",""],["药栏勾堕衔钗雀。\n雀钗衔堕勾栏药。\n花落画屏纱。\n纱屏画落花。\n晓山关雁绕。\n绕雁关山晓。\n人远惜残春。\n春残惜远人。",""],["软铺铜甃飞红浅。\n浅红飞甃铜铺软。\n深巷柳摇金。\n金摇柳巷深。\n爚篝香雾薄。\n薄雾香篝爚。\n门掩半黄昏。\n昏黄半掩门。",""],["去春三鸟栖来曙。\n曙来栖鸟三春去。\n边塞绝秋千。\n千秋绝塞边。\n错弹哀抵角。\n角抵哀弹错。\n楼倚谢娘秋。\n秋娘谢倚楼。",""],["井干双断金丝绠。\n绠丝金断双干井。\n城上响啼莺。\n莺啼响上城。\n绮园南去骑。\n骑去南园绮。\n迟日坠鸣机。\n机鸣坠日迟。",""],["簸钱金压花裙唾。\n唾裙花压金钱簸。\n斜日斗钿车。\n车钿斗日斜。\n酒胡雕列缶。\n缶列雕胡酒。\n孤独醉当垆。\n垆当醉烛孤。",""],["熨香沉斗珠绳屈。\n屈绳珠斗沉香熨。\n花鸭睡笼纱。\n纱笼睡鸭花。\n减丝荷漏浅。\n浅漏荷丝减。\n长夜好难量。\n量难好夜长。",""],["烛槃深影春围曲。\n曲围春影深槃烛。\n迷路入花溪。\n溪花入路迷。\n枕函空覆锦。\n锦覆空函枕。\n遮莫苦栖鸦。\n鸦栖苦莫遮。",""],["刺桐花满高桥寺。\n寺桥高满花桐刺。\n魂断几家村。\n村家几断魂。\n去䯄嘶落絮。\n絮落嘶䯄去。\n娘度夜中霜。\n霜中夜度娘。","刺桐花满高桥寺。\n寺桥高满花桐刺。\n魂断几家村。\n村家几断魂。\n去騧嘶落絮。\n絮落嘶騧去。\n娘度夜中霜。\n霜中夜度娘。"],["小姑村映青溪晓。\n晓溪青映村姑小。\n家是就矶斜。\n斜矶就是家。\n返舟莲棹远。\n远棹莲舟返。\n侬识旧娃宫。\n宫娃旧识侬。",""],["上潮春涨西陵望。\n望陵西涨春潮上。\n寒雨渡来难。\n难来渡雨寒。\n燕泥衔断槛。\n槛断衔泥燕。\n时苦作蚕丝。\n丝蚕作苦时。",""],["路旁厢板乌椑树。\n树椑乌板厢旁路。\n寻处甚阴阴。\n阴阴甚处寻。\n缕丝千点雨。\n雨点千丝缕。\n何若别情多。\n多情别若何。",""],["窄帆轻落亭前驿。\n驿前亭落轻帆窄。\n红露浥花栊。\n栊花浥露红。\n渡淮临雨暮。\n暮雨临淮渡。\n长过莫愁乡。\n乡愁莫过长。",""],["黄木湾前芦雁稀。\n琵琶洲畔竹花飞。\n南去陆郎烟瘴里，几时归。\n翠鸟羽长临镜远，章鱼海阔跳波微。\n看到木棉红又白，好装衣。",""],["当时邂逅，凌家山下，桃树满前津。\n今来又值，桃花开后，不见那时人。\n香轮翠幕陵前路，日影动飞尘。\n流水横斜，鸟啼哀怨，愁对武陵春。",""],["喜摘唯红豆，难攀是白榆。\n百花亭外展氍毹。\n藏得宜男、临赛又踟蹰。\n绡帕牵藤刺，缃襕裹露珠。\n朦胧却把翠钿输。\n暗拣花枝、插补鬓边虚。",""],["青漆垂银钥，丹纱映玉栊。\n隔窗娇立小芙蓉。\n两地分明、细语一灯红。\n好鸟音初剪，幽兰气转浓。\n相看枉自唤玲珑。\n一寸明螺、槅子万重峰。",""],["粉蕊飘来薄，红英落处稀。\n一团并作屐头泥。\n却是桃花飞过、李花飞。\n残粉留青蒂，零红断碧枝。\n落花那辨早和迟。\n空自晓风吹了、晚风吹。",""],["梧子丛台敞，荷香小幕开。\n冰浆雪瀣满樽罍。\n时见梁间双燕、自飞回。\n覆草传螺碗，藏钩觅坠钗。\n闺中柳絮谢家才。\n妒煞王郎、私遣隔帘猜。",""],["绛帐迢迢结作云。\n东风吹皱石榴纹。\n芙蓉弄色调金粉，蛱蝶寻双认绣裙。\n花羃历，思纷纭。\n游车归去日斜讯。\n不知唱得难忘曲，十二钗边若个闻。",""],["银甲雕戈小队工。\n内家宣敕教从戎。\n山萝覆镞萦金细，野火烧旗闪幔红。\n宫月静，阵云空。\n凤凰山下抱龙弓。\n珠兜玉靸团营路，小雨寒花何处逢。",""],["翠鬣红翘金跖低。\n藕花多处一汀迷。\n谁怜比翼琴台瓦，枉织双丝锦字机。\n银埒远，玉塘稀。\n天长海阔几时归。\n相离只解相思死，那解相思未死时。","翠鬣红翘金蹠低。\n藕花多处一汀迷。\n谁怜比翼琴台瓦，枉织双丝锦字机。\n银埒远，玉塘稀。\n天长海阔几时归。\n相离只解相思死，那解相思未死时。"],["蓼浦兰江隔远涔。\n彩毛飞去信音沉。\n十三弦上锼金柱，二八丫头琢玉簪。\n无处觅，好难寻。\n空留双影绣罗衾。\n几回欲向沙头路，到得沙头路转深。",""],["梅花开满清江路。\n北府夜凉新幰度。\n谁开扇上五明罗，只挂灯前九子璐。\n西陵水削回潮暮。\n双盏乍传天欲曙。\n开元新赐小金钱，撒在帐中无觅处。",""],["红蕖小幕开深槛。\n微雨乍收凉漏浅。\n酒淹垆火带霜吹，风搅浊油和烟剪。\n银船交泛明河转，玉树当轩共婉娈。\n夜深空忆广陵涛，水绕曲江知近远。",""],["吴山晓阁妆螺子。\n山木倒开蛮镜里。\n笔床闲写竹衣红，书带自垂藤菜紫。\n机头小轴穿花绮。\n纂就散丝盈络纬。\n秋波千顷照芙蓉，无数彩云江畔起。",""],["龙山秋曙官亭冷。\n烟锁茱萸井。\n西风吹雨雁南来。\n何处还登戏马宋公台。\n美人垆下桑郎熟。\n细把金钱菊。\n辽东皂帽堕堪伤。\n不道满城风雨又重阳。",""],["芜城新曲勾栏浅。\n覆地氍毹软。\n小蛮金管雪儿筝。\n二十四桥明月照人醒。\n三朝不作衔书凤。\n但舞江南弄。\n晓风散去彩云愁。\n可是竹西歌吹久扬州。",""],["布帆婀娜江州至。\n贻我相思字。\n怀中一日九开看。\n记得旧时风雨夜阑干。\n潮平若泛西陵渡。\n须把滕王赋。\n南州榻冷剑城凉。\n借问延陵何日下南昌。",""],["宫莺细啭皇州路。\n花暖金盘露。\n春风扈从赋长杨。\n策马归来重醉酒垆傍。\n钱塘五月冰壶晓。\n别馆新荷小。\n瑶辞百幅重南金。\n思煞梁园客子到如今。",""],["夕阳江上丹枫暮。\n看车马、纷无数。\n当日西施从此去。\n城山出海，楼船近岸，中有更衣处。\n平沙十里长亭路。\n空留得、花如雾。\n最恨江流流不住。\n暮潮初下，午潮还上，今古西陵渡。",""],["片帆絓处芦花白。\n痛年少、经兵革。\n庾信江陵归未得。\n教兵城下，高迁屯畔，一夜寒涛坼。\n东来西往看如织。\n问谁是、当时客。\n睹此芒芒百思集。\n素车何在，乌鸢散尽，犹有人沾臆。",""],["梨花亸鹊惊春雪，柳曲迎车怯晓风。\n篮外蝶衣笼画粉，楼头凤蜡泻珠红。\n熏迷银叶怜妆坼，露压金槽滴睡浓。\n无奈景阳钟隐隐，数声和月到帘栊。",""],["春还绣陌桃初落，日映璚绡幕半遮。\n黄点额头花胜结，红抽靴子蒯绳芽。\n妒蛾筝合矜秦赵，细犊车香绕狭斜。\n空有侍中夸易识，难忘一笑在东家。",""],["吴娃窈窕裁芳纻，楚竹参差聚列星。\n歌扇影回屏半褶，舞裙丝挂箔头钉。\n觞迎水曲翻龙㔶，车转花梢动鸽铃。\n天上旧曾听鼓瑟，归来几度暮山青。",""],["董贤馆外骄䯄骋，班氏门前冷鸟啼。\n湘浦芰裳迷蔡北，秦台苏合出乌西。\n针萦鸾缕愁丹缠，灯满蚕𫭟怨赤蹄。\n难与故夫携束素，重逢但唱杞梁妻。","董贤馆外骄騧骋，班氏门前冷鸟啼。\n湘浦芰裳迷蔡北，秦台苏合出乌西。\n针萦鸾缕愁丹缠，灯满蚕塸怨赤蹄。\n难与故夫携束素，重逢但唱杞梁妻。"],["宝扇横时，玉堂深处。\n开奁齐唱金针句。\n汉阳少妇解璇玑，孝标令妹工词赋。\n郁草名金，柳花成絮。\n满阑种就珍珠树。\n欲听缑氏海西谣，须寻仙尉江南路。",""],["麦垄青青菜垄黄。\n野棠花满路、日初长。\n谁家女伴斗新妆。\n蜂来往，刺得口脂香。\n三五映垂杨。\n见人还却步、背方塘。\n小姑不解断人肠。\n看花落，又看浴鸳鸯。",""],["绣柱红绳曳彩云。\n双双悬画板、对斜曛。\n风吹袜子小鸦分。\n重扶下，低系水罗裙。\n天际映虹纹。\n抛来香带薄、绕氤氲。\n空园人散欲黄昏。\n惊鸿堕，花落自纷纷。",""],["花里重寻赵璧弹。\n流黄朝日映、织初残。\n停机暗下理双鬟。\n调弦请，莫是喜幽兰。\n弦涩苦难安。\n机丝曾裂指、沁心寒。\n思繁错记写离鸾。\n弹多误，频脱指环看。",""],["青鸟衔来双锦鳞。\n背人佯撇下、小重茵。\n口脂红浅浥香津。\n缄题处，印得指螺新。\n素字小泥银。\n簪花新样巧、卫夫人。\n鸳鸯格子剪江苹。\n波纹细，恍见泪粼粼。","青鸟衔来双锦鳞。\n背人佯撇下、小重茵。\n口脂红浅浥香津。\n缄题处，印得指螺新。\n素字小泥银。\n簪花新样巧、卫夫人。\n鸳鸯格子剪江蘋。\n波纹细，恍见泪粼粼。"],["一过东湖深又深。\n石桥啼不断、午时禽。\n柳黄曾压绞儿金。\n双朱户，流水昼沉沉。\n有女暗相寻。\n红衣羞泪湿、洗前襟。\n东风吹放小桃心。\n吹难住，吹落满庭阴。",""],["怨怨。\n柳如线。\n清漆鸦头红脰燕。\n背人偷弄金条钏。\n一曲桃枝相恋。\n落花飞满春江面。\n飞过春江何限。",""],["梦梦。\n晚花冻。\n小妹闺房原解诵。\n窥帘偏爱求凤弄。\n恰是琴心难动。\n琴心袅袅春风送。\n岂是琴心难动。",""],["处处。\n绕飞絮。\n纱帽郎今何处去。\n章台折尽长条树。\n樗子街头重遇。\n玉瓶金盏灯前注。\n愁煞夜乌啼曙。",""],["五月海榴红照眼，美人初佩丹砂。\n金堂绮席启朝霞。\n暑衣裁葛叶，冰碗浸菖花。\n赋就子虚将入奏，汉庭狗监先夸。\n秋风锦石动星槎。\n但悬金似斗，那羡枣如瓜。","五月海榴红照眼，美人初佩丹砂。\n金堂绮席启朝霞。\n暑衣裁葛叶，冰碗浸菖花。\n赋就子虚将入奏，汉庭狗监先誇。\n秋风锦石动星槎。\n但悬金似斗，那羡枣如瓜。"],["细结五丝仙胜缕，屏间艾虎交悬。\n愿郎如虎复如仙。\n山公曾典薄，四十正当年。\n男子生难跨万乘，也应日数官钱。\n他时花拂锦连干。\n欲看三岛雪，更泛五湖船。","细结五丝仙胜缕，屏间艾虎交悬。\n愿郎如虎复如仙。\n山公曾典薄，四十正当年。\n男子生难跨万乘，也应日数官钱。\n他时花拂锦连乾。\n欲看三岛雪，更泛五湖船。"],["红旆远迎汾上路，楼船还赋秋风。\n儿童骑就竹龙葱。\n塞烟含柳碧，关雨坠枫红。\n汉相江都三策贵，勿需司马军容。\n琴台撤幕敞芙蓉。\n高山千万叠，流水两三重。",""],["记得蜀葵花发后，一樽长对花前。\n鸣鸠初拂杖乡年。\n紫?开碧筱，丹灶有青莲。\n十亩绮园还自赋，彦升当日诗篇。\n玉钩金犗钓鱼船。\n枕来沧海外，漱向赤城边。",""],["蜡子樱儿飞绿鹊。\n午睡裁醒，倚遍雕红药。\n青映远山回雨脚。\n残虹几晕胭脂削。\n满院繁华看渐落。\n日暮风生，片片吹来薄。\n粘得断丝丝又弱。\n重重绊住秋千索。",""],["日暖秾桃红照水。\n粉蝶飞来，水上衔香蕊。\n映水双双低复起。\n影儿也在花窝里。",""],["隋苑覆依依。\n行人迷又迷。\n风前空惜好腰肢。\n待得长条堪作线，蚕箔下，又缫丝。\n折尽渭亭枝。\n年年送别离。\n满栏空自扑人衣。\n待得飞花堪作絮，交领下，暖风吹。",""],["红亭细柳碧条条。\n解轻舠。\n渡春潮。\n沽酒帘低，春色满河桥。\n送得柳枝南浦去，人渐远，楚天遥。\n临行重系绿丝绦。\n拂花梢。\n望迢迢。\n柳絮飞飞，偏惹柘黄袍。\n春去那堪还积雪，点点下，未曾消。",""],["花衔日色柳衔烟。\n画楼前。\n水连天。\n缓橹轻歌，鸭嘴小娘船。\n新载摇郎湖曲里，不愿取，渡头钱。\n前山深树有啼鹃。\n恨年年。\n未归旋。\n红板人家，犹自挂秋千。\n日薄馀寒春又晚，溪路远，草芊芊。",""],["画栏低，斜日暮，睡起甚无绪。\n蝶蝶游丝，阵阵惹飞絮。\n是他梅子生心，樱桃辞蒂，著甚个、五风三雨。\n隔墙树。\n听叶底鹃儿，不住叫谁去。\n看又黄昏，寂寂闭朱户。\n夜来明月何如，几时回顾，记不出、初三十五。",""],["猊火初红，抱绿绮、夜堂三弄。\n渐秋老、亭皋木落，晚云流冻。\n紫稗霜田翔寡鹄，碧梧凉叶栖雏凤。\n似兰娘、峡里听流泉，当时梦。\n几曾是，商陵痛。\n何须作，雍门恸。\n但前轩月下，手挥目送。\n三尺冰弦看似雪，有新声、迸入鸳鸯综。\n恰七条、总似一条丝，丝丝动。",""],["第六桥头，四望里、水青山绿。\n柳荫下、幔舟舣岸，管笙低蹙。\n过雨晓移东岭尽，清钟午度西林曲。\n趁红裙、同拜岳王祠，闲追逐。\n双熊仗，排花谷。\n交螭字，横荒麓。\n启玉函珠玺，凤鸾飞簇。\n漫道明湖春去久，听子规、尚叫南枝木。\n痛玉毫、散写作南枝，枝枝矗。",""],["右军祠下路，胜友高朋，一时云集。\n修竹崇岩，遥想兰亭当日。\n车毂骤如流水，交履舄、满堂笙瑟。\n何处觅。\n华灯影里，管儿歌涩。\n早是千里相思，更命驾能来，四愁都释。\n南国佳人，邂逅相逢车笠。\n梁苑邺宫难再，金樽满、倒倾安惜。\n漏转急。\n今夕不知何夕。",""],["汉室淮南，潘封泽潞，红弦久擅空桑。\n携来海甸，宝匣散珠光。\n碧轸瑶徽矶额，龙门树、斫羽镂商。\n人传是，干清供奉，曾遗赐诸王。\n崇祯。\n题岁月，横纹印绿，苏带流黄。\n自王孙散去，沦落江湘。\n故国轩悬何处，烧桐好、付与中郎。\n谁知得，红丝系足，还是旧宫妆。","汉室淮南，潘封泽潞，红弦久擅空桑。\n携来海甸，宝匣散珠光。\n碧轸瑶徽矶额，龙门树、斫羽镂商。\n人传是，乾清供奉，曾遗赐诸王。\n崇祯。\n题岁月，横纹印绿，苏带流黄。\n自王孙散去，沦落江湘。\n故国轩悬何处，烧桐好、付与中郎。\n谁知得，红丝系足，还是旧宫妆。"],["海燕争春，城乌啼曙，丛丛花满阑干。\n虹梁日照，碧叶露初干。\n昨夜新衣裁就，薰笼暖、翠簇红攒。\n频提视，羞人难著，只说晓妆寒。\n长干。\n西去路，春江鸭绿，新水漫漫。\n早青牛朱毂，骝马金鞍。\n江畔垂杨万树，风吹绕、贝带斑斓。\n妆楼望，翩跹水底，疑向镜中看。",""],["紫峤鸾飞，银河鹊去，南园长报金卮。\n莲塘昼暖，花影散红衣。\n种得兔头新熟，闲吟望、绣满町畦。\n扶瑶瑟，佳人醉拥，日照画栏西。\n回首。\n当日事，鸡坛会鼓，鹤市吹篪。\n叹蹉跎隔岁，屈指俱非。\n但对百城图画，家濒海、有友安期。\n凭酣饮，朱颜未老，翘首绛云低。",""],["微雨凉收，风翻橡叶，女墙斜点三星。\n永恩楼上，蹑履暗中听。\n何处瑶琴初发，珠帘外、流水泠泠。\n停声久，千崖忽堕，玄鹤舞青冥。\n汾亭。\n遥奏后，箫怜秦女，瑟怨湘灵。\n奈晚风吹角，秋雨淋铃。\n此际琴心到处，东家女、谁在银屏。\n屏中睡，今宵无梦，有梦也应醒。",""],["石氏悬楼，王朗开阁，伤心睹此芒芒。\n上宫碧玉，本是旧名倡。\n穗帐空悬日暮，西陵下、几曲沧浪。\n如何地，漳台望久，回首见空王。\n双双。\n寻侣伴，幽吟梵磬，仿佛伊凉。\n把杨枝滴露，暗洗朝妆。\n满目天花散尽，云床冷、梦断高唐。\n褰帘坐，水田衫子，不叠旧衣箱。",""],["渭南万里，三载携琴，人诵廉洁。\n为葬慈亲，归卧溪山别业。\n道场勿辞高士吊，哀来时涌丹徒血。\n苦思君，又蹉跎相失，暮秋时节。\n游望冷、蔷薇洞口，丝竹萧条，远过前哲。\n兔苑鸡场，还揽旧时英杰。\n草暖吟成樊水调，花飞梦散华池雪。\n听西堂，几何时，又鸣蜻蛚。",""],["去冬冬至。\n刚雪霁梅花，山楼残醉。\n儿女灯前感叹，宛如梦寐。\n春来重订王孙约，竟淹留、又攀丛桂。\n青阳下榻，玄霜解缆，顷刻间事。\n念晨夕、盘餐并对。\n更寒雨鸡鸣，暖风花坠。\n巴里联吟古调，逊君佳细。\n云门旧誓寻难度，顿阳关、衰柳摇曳。\n几时还看，宾鸿万里，碧天留字。",""],["锦堂清昼，恰瑶盏传来，玉荷开后。\n齐岱基祥，甫侯嗣懿，盛世相君遗胄。\n皇览揆予初度，看彩凤翔云岫。\n况世载，有千金一字，国门之购。\n前侑歌缓处，脆板清丝，花下排红豆。\n竹秀联吟，波流送羽，觞咏兰亭依旧。\n当日醉乡何在，教好女揄长袖。\n恐有客，饮淳于一石，与君为寿。","锦堂清昼，恰瑶盏传来，玉荷开后。\n齐岱基祥，甫侯嗣懿，盛世相君遗胄。\n皇览揆予初度，看綵凤翔云岫。\n况世载，有千金一字，国门之购。\n前侑歌缓处，脆板清丝，花下排红豆。\n竹秀联吟，波流送羽，觞咏兰亭依旧。\n当日醉乡何在，教好女揄长袖。\n恐有客，饮淳于一石，与君为寿。"],["春已暮、画奁频启。\n朝日穿来，又在眉际。\n◇粉将施，弹绵先拂、镜儿里。\n木瓜渍了，又添上、新红子。\n为要好情多，还则向傍人、问个匀未。\n昼长绣褶暖，换却筛罗浅绮。\n薰嫌石叶，叠下郁金细细。\n临行道、履线将残，踏不得、楼头新?。\n谁曾顾楼前，楼外暮春馀几。",""],["兰亭秋暮，眺晴原、并到南华山墅。\n画槛横塘看两岸，多少断红残紫。\n鳌禁当年，鹭车昔日，休沐时来此。\n苍梧颍嗣，至今长读秋水。\n闲备彩缆青丝，玉壶携酒处，锦鳞鲜美。\n吴下阿蒙何日至，相对邺宫才子，舞凤雄图，放龟遗迹，衰柳频低起。\n耶溪相望，不知去几何里。",""],["谢庭玉树，乍临风，摇曳，乌衣巷里。\n何处羊车还洛市，皎皎双瞳如水。\n洗马清神，黄门隽格，少小能文史。\n玄亭问字，慨然逢故人子。\n相对芳树高轩，青灯残夜浅，流萤娓娓。\n转盼河桥解缆去，搴尽江皋兰芷。\n燕翼堪怜，凤毛有待，西水浮新芑。\n春阳努力，眼中吾且老矣。",""],["囗囗白下，叹何人、不识白家兄弟。\n长者贤良方就辟，仲学孝廉相继。\n有母年高，北堂娱养，萱树长芬斐。\n及时捧檄，如君孝弟能几。\n幸遇八十华辰，称觞远近，各具登堂礼。\n曾读前朝党锢传，二白齐名杜李。\n滂母贤哉，从容告诫，籍籍盈人耳。\n风流无恙，百年今且伊始。",""],["河水东流。\n看万里寒风，塞外惊秋。\n谁遣倾国，远嫁边头。\n辞凤辇、下龙楼。\n记临行上马，赐与锦带工箜篌。\n卸宫妆，向深深毳幕，徐换貂裘。\n平沙那堪晓发，似露下长门，月堕金沟。\n满地燕支，萎红枯紫，巧胜画笔涂勾。\n羡年年塞雁，归渡海岸与沙洲。\n愿仍还上林旧宿，同叫更筹。",""],["蝶里花襕，微雨后、深苑荆桃如菽。\n红粉堆边，露琯冰筝，并起是谁华屋。\n楝华风发前村暮，空岩畔、有人如玉。\n牵萝罢、天寒倚遍，一庭修竹。\n私唱开元旧曲。\n见林外春红，暗翻秋绿。\n昨夜惊乌，梦里还啼，向日对筵蕉烛。\n玉猧盘地银丝绕，吹松粉、坠来金粟。\n那须听、黄公鸟声断续。",""],["春后雪。\n衫儿因甚难热。\n绿丛啼鸟听吹来，嫩簧小舌。\n可怜谷雨是明朝，又当花谢时节。\n翠蛾子，谁与贴。\n雀花镜里谁折。\n珠娘西去唱杨枝，怨歌几阕。\n长干断处苦相迎，桃根桃树桃叶。\n枕屏叠下三四褶。\n揽流苏，带子双结。\n枉对金缸明灭。\n但辘轳井上、咿哑相接。\n恰夜乌城头啼歇。",""],["东南都会，会稽形胜，居然晋代风流。\n宛委赤书，蓬莱紫气，天连星宿牵牛。\n佳境任优游。\n向山阴道上，秦望峰头。\n万壑千岩，当时曾此镇扬州。\n依稀旧迹还留。\n怅兰亭人散，蕺里歌遒。\n九曲风光，五湖烟雨，望中处处生愁。\n时泛小犀舟。\n看西施西去，花谢妆楼。\n犹见若耶春涨，绿草遍芳洲。",""],["正小春花暖。\n绣屏开、碧觞乍举，黄眉初展。\n玄扈干云太宰后，犹见征南季简。\n且载酒、闲听丝管。\n绿野早成江上宅，况采芝、旧日商山远。\n问海水，几回浅。\n古来七十原稀罕。\n更菁葱、满庭玉树，雕盂金版。\n荀氏八龙齐下食，不羡瑶台琼苑。\n是何处、驰归轻幰。\n大妇流黄中妇锦，最可怜、小妇调笙缓。\n榆历历，枣攒攒。",""],["想前此。\n阁下薇花乍紫。\n横栏曲、半臂荔红，卷发新梳理黄子。\n按鹍弦第四。\n忽地。\n吴头楚尾。\n看看远、海雁又来，眼底空留数行字。\n思量那年事。\n不合启厢东，夜雨灯暗，桃花，误赚刘郎至。\n奈三载寒食，一朝欢聚，手把窄袜弄花绮。\n那知梦儿里。\n倚徙。\n病初起。\n况翠帐寒生，晚秋天气。\n暮暮朝朝向谁是。\n纵迢递关山，梦魂堪寄。\n知他去处是百里。\n是千里。",""],["看看又是，银河清浅，织女乍停机。\n不知何事，今宵残醉，还听汝南鸡。\n庭前瓜果妆成巧，暗里絓蛛丝。\n记得年前，小矾山下，干鹊夜来时。","看看又是，银河清浅，织女乍停机。\n不知何事，今宵残醉，还听汝南鸡。\n庭前瓜果妆成巧，暗里絓蛛丝。\n记得年前，小矾山下，乾鹊夜来时。"],["马蹄才发，阳平门外，望里是淮安。\n可怜此地，曾经流浪，一十五年前。\n曲江高会知何处，秋水晚生烟。\n惟有垂杨，千条万缕，还挂酒楼边。",""],["行来但觅，旗亭旧迹，下马驻城𬮱。\n请看当日，淮流如故，双泪落征轮。\n淮阴市上诸年少，相忆总沉沦。\n谁料衰年，征车北去，羞见市中人。","行来但觅，旗亭旧迹，下马驻城闉。\n请看当日，淮流如故，双泪落征轮。\n淮阴市上诸年少，相忆总沉沦。\n谁料衰年，徵车北去，羞见市中人。"],["十年苦忆，元龙颜面，梦寐恐难亲。\n不虞相见，长安道上，并见在傍人。\n停毫一顾踟蹰久，欲待按歌匀，碧鸭消时，红蕉坐去，何处不传神。",""],["江县看花后，山城种柳时。\n布袍竹杖鬓如丝。\n今日画图相对、系人思。",""],["水涨芙蓉粉，烟含杨柳丝。\n幽人家住五云溪。\n行过东坡书院，孝侯祠。\n箧有中封帖，吟成东去词。\n荆南相望一相思。\n恰又晚村花垛，夕阳时。",""],["驿馆吹芦叶，都亭舞柘枝。\n相逢风雪满淮西。\n记得去年残烛，照征衣。\n曲水东流浅，盘山北望迷。\n长安书远寄来稀。\n又是一年秋色，到天涯。",""],["青山犹在画栏空。\n人去夕阳中。\n不道十年重到，还披此地清风。\n蜀冈无恙，堂成命酒，一听歌钟。\n未审后来太守，是谁能继山翁。",""],["闻道欧公当日，宾朋载酒堂中。\n后来三过有坡翁。\n长使林花飞动。\n此事已经千载，我来重挹高风。\n眼前莫放酒杯空。\n恐是东坡残梦。",""],["平明载酒登高去。\n湖畔停船处。\n几株乌桕未全红。\n犹喜黄花开遍小桥东。\n长江一望环如带。\n放眼千山外。\n开樽更上越王城。\n多少夕阳江上晚来晴。",""],["江郎祠外中秋月。\n城角吹将彻。\n十年长记此宵中。\n豪客相过深巷有微风。\n今来君宿耆阍下。\n又值中秋也。\n题将丽句最纷披。\n恍见当时桂树晚依依。",""],["是谁画出潘家果。\n百琲珍珠颗。\n羡君原是柏梁才。\n记取桃梨橘栗李榴梅。\n玉瓶金锁琉璃瓮。\n且作和羹用。\n须知仙树本蟠根。\n欲借花前一醉石州春。",""],["秋风槭槭敖阳路。\n草屋方垂露。\n当垆夜起数金钱。\n独对寒灯此夜不成眠。\n廿年歧路今方息。\n又是征书急。\n柳梢斜挂月朦胧。\n不信还来骑马月明中。","秋风槭槭敖阳路。\n草屋方垂露。\n当垆夜起数金钱。\n独对寒灯此夜不成眠。\n廿年歧路今方息。\n又是徵书急。\n柳梢斜挂月朦胧。\n不信还来骑马月明中。"],["敬亭四月梅花发。\n正值清和节。\n慈恩寺里曲江边。\n新旧郎君争占一枝先。\n红罗欲寄无由寄。\n空写泥金字。\n楼头长赠碧山云。\n恰取花枝中半两平分。",""],["桃花又发临淮渡。\n错认天台路。\n行来莫笑太奔忙。\n知是赤栏桥畔旧刘郎。\n平明入直迥西寺。\n幞被双娥侍。\n含香谁问夜归迟。\n只恐桃花回首望中迷。",""],["图书万轴牙签满。\n辟蠹烧芸暖。\n果然子政是前身。\n羡煞当年天禄阁中人。\n白云司判西曹事。\n薇省曾留字。\n胸藏冰照宛如犀。\n绝胜西堂终夜对燃藜。",""],["草店鸡鸣酒未醒。\n马槽听啮粟、渐无声。\n灯前盥面促装成。\n车尘起，疑在雾中行。\n渡水石桥平。\n秋风联辔过、涿州城。\n乡关回首暗心惊。\n遥天尽，愁见一云横。",""],["贳酒前庄日渐低。\n鞭梢斜挂壁、卸征衣。\n同行三俊喜相依。\n垂杨下，长许控金羁。\n河水碧琉璃。\n垆头风物美、近京畿。\n征车欲度日迟迟。\n沉吟久，三辅故人稀。","贳酒前庄日渐低。\n鞭梢斜挂壁、卸征衣。\n同行三俊喜相依。\n垂杨下，长许控金羁。\n河水碧琉璃。\n垆头风物美、近京畿。\n徵车欲度日迟迟。\n沉吟久，三辅故人稀。"],["阊阖嵯峨天际开。\n宾门方四辟、重招徕。\n将军才到莫相猜。\n诸王邸，谁道买臣来。\n九市共三街。\n彩云遥起处、见蓬莱。\n秋风歌咏柏梁台。\n承明内，原有掞天才。",""],["欲绣平原几度思。\n园蛾初作茧、络成丝。\n前溪水满雪消时。\n波纹起，绿似小桃枝。\n投足散涟漪。\n夜来开绣谱、度针迟。\n一痕青影暮烟微。\n衔丝细，不用洗胭脂。",""],["朱颜绿发画图中。\n丹砂长饮酒、醉溶溶。\n前身王母旧青童。\n干将佩，花锷散芙蓉。\n羽峤有谁从。\n蓬莱刚水浅、渡苍龙。\n他年笑入杏花丛。\n瀛洲近，折取一枝红。",""],["当日吹篪两渡淮。\n感君长贳酒、醉高斋。\n十年分手各天涯。\n频频望，红叶喜当阶。\n高咏谢家才。\n彩毫裁诏罢、凤池回。\n征书白首苦相催。\n平津第，勿厌故人来。","当日吹篪两渡淮。\n感君长贳酒、醉高斋。\n十年分手各天涯。\n频频望，红叶喜当阶。\n高咏谢家才。\n綵毫裁诏罢、凤池回。\n徵书白首苦相催。\n平津第，勿厌故人来。"],["甫里先生何处是。\n家住近、垂虹亭子。\n著罢新书，开门闲望。\n但见一湖烟水。\n放棹偶然垂钓饵。\n人道是、松陵渔史。\n若问羊裘，投竿何所，应在白苹洲里。",""],["青幡才换。\n又是春过半。\n听啼莺，声将变。\n能令岁月增，真觉黄金贱。\n更那顾，秦王有女将衣卷。\n但赴芳林宴。\n一任花零乱。\n年半百，休三叹。\n文章堪自信，富贵非吾愿。\n君不见，比来世事皆如幻。",""],["姊妹相逢何处是，朱栏斜倚双桐。\n坐来委抱鬓笼松。\n画裙欹履窄，金钏隔纱红。\n寂寂春园人不到，看时多少朦胧。\n绿坡生草细茸茸。\n银猊闲戏逐，翻向绿坡中。",""],["三月暮春春雨后，申江初放桃花。\n忻看锦帨挂官衙。\n名姝如谢女，夫婿是秦嘉。\n制得香奁妆百福，珠屏烂若朝霞。\n麻姑曾过蔡经家。\n仙厨将进酒，图上见来么。",""],["何处玉台堪倚镜，徐陵原有新题。\n今来同住巷东西。\n门迎桃叶渡，人胜苎萝溪。\n散掷明珠安有价，无钱多买胭脂。\n只愁初制夏侯衣。\n茜裙裁剪未，帘外杏花飞。",""],["五月榴花开似锦，一尊长对花前。\n看看又值杖乡年。\n蟠溪多寿考，绮里本神仙。\n虽则东方能玩世，无须金马门边。\n君身何事不堪传。\n吟来忘岁月，笔下有云烟。",""],["海上青螣看负角，丹山凤翮初成。\n男儿二十建修名。\n陆机刚作赋，方朔正谈兵。\n自愧蹉跎多去日，羡君先请长缨。\n南箕不用咏三星。\n锦筵香薤发，官阁早梅生。",""],["客舍灯花开似锦，寒屏有梦惟鱼。\n新来喜得弄獐书。\n蓝田秋产玉，碧海夜生珠。\n绣褓画襕初试浴，遥看紫气充闾。\n君家原有旧鹓雏。\n他时汤饼会，啼听是何如。",""],["洛下久无同甲会，试看江左耆英。\n年来七十诵黄庭。\n孙芝千朵艳，儿竹万条青。\n怪道探书多绿字，闲堂代有传经。\n桃花染得彩衣成。\n杜陵谁最好，吾爱蒋元卿。","洛下久无同甲会，试看江左耆英。\n年来七十诵黄庭。\n孙芝千朵艳，儿竹万条青。\n怪道探书多绿字，闲堂代有传经。\n桃花染得綵衣成。\n杜陵谁最好，吾爱蒋元卿。"],["捣尽筁头泥。\n春蚕已蜕衣。\n片饧里作弹丸儿。\n不破弥罗三寸茧，谁解道，一窝丝。\n粔妆汉宫遗。\n餦餭久未施。\n开元宫女尚能为。\n今日尚书花餤会，银碗合，使人思。",""],["溪流雨过增新涨。\n春山处处桃花放。\n中有武陵人。\n花前一问津。\n幅巾裁白氎。\n坐听溪流咽。\n写入画图中。\n桃花映面红。",""],["钗头胜字裁方幅。\n定情弹作莺萝曲。\n闻道薛家来。\n灯花夜自开。\n清淮一别久。\n谁解双垂手。\n佛日会摹多。\n香山老去何。",""],["买金欲铸鸱夷像。\n频年忆汝江湖上。\n何处采名花。\n西施不及他。\n白头吟自在。\n诗寄钱刀外。\n恰似遇桓伊。\n听歌辄唤时。",""],["云鬟绾就青鸦小。\n春山画得双蛾巧。\n衣剪杏黄罗。\n红牙试按歌。\n锦屏香作雾。\n慢把金樽度。\n玉暖起烟丝。\n申江春去时。",""],["榴裙绉褶花千裥。\n地衣红衬弓鞋软。\n银箭下来迟。\n当筵舞柘枝。\n玉栊华蜡里。\n新月胧胧起。\n何处最嫣然。\n花前一笑间。",""],["晚色烟和。\n鸟散庭柯。\n听街头、击破吹螺。\n酒阑送客，夜火星罗。\n幡幢引处，看蝶演，似莺梭。\n法轮常转，五方何处，现维摩、试问禅那。\n作天魔舞，于意云何。\n香坛行过，随啸咏，且婆娑。",""],["寂寂暮春杨子宅。\n昔在乌聊，今在申江侧。\n座上彩云回锦席。\n门前几树桃花色。\n乍雨乍收檐溜滴。\n坐拥双鬟，为我弹瑶瑟。\n醉后倚歌还弄笛。\n醒来微月当窗白。",""],["东床先订，西家愿宿，何事穿墉穿瓦。\n纵教强委后来禽，却不道、子南夫也。\n明府风流、使君潇洒，两断可妻公冶。\n莫言河汉鹊桥乖，看合浦、在讼庭之下。",""],["韦氏双珠真可喜。\n芝兰欲在阶庭耳。\n春园况值有莺迁，人道是。\n天仙子。\n曾见宣尼抱送此。\n里号高阳从此始。\n凤毛麟角纷纷起。\n我来正值浴兰时，看取靧。\n金盘里。\n半是桃花半雪水。",""],["东扬不用占星婺。\n是家有、真贤孺。\n曾隔兵戈遥海路。\n合州城外，雷阳驿畔，多少仳离处。\n千山万水归来喜。\n看膝下、人如树。\n但得朱颜能久驻。\n蟠桃花发，蓬莱水浅，谁道流年度。",""],["荷风乍暖。\n恰红版桥头，骊驹唱缓。\n待诏公孙，弹琴司马，挟策争游上苑。\n万里鹏飞在望，看翠幕传金盏。\n况前路，有漳台花柳，郦亭丝管。\n迤逦揽辔处，大道秋光，不觉长安远。\n丞相延来，通侯载去，户外车尝满。\n他日玉堂堪继，喜大小皆贤阮。\n装衣待，来年红杏，为君裁剪。",""],["隔江人远。\n一别几何年，鬓毛都换。\n但十柴桑，难寻句曲，到处堪留堪恋。\n衣上黄尘不落，望垄首浮云变。\n犹相忆，在庐江旧第，芹泥桥畔。\n可念书画室，半榻琴箫，几树花零乱。\n人寄南窗，诗传北郭，莫道未还东苑。\n我亦西泠借住，须有日、烟霞结伴。\n邻居好，看墙头过酒，那时相见。",""],["秋风乍起，桂花时、又是东亭初度。\n四十年来弹指顷，阅历山川无数。\n倚马成文，磨盾草檄，杀尽中山兔。\n侯王以下，一时趋走如骛。\n谁道梁苑归来，故人官沪上，欢然相聚。\n有弟同行胜小陆，共作平台词赋。\n弧矢高悬，长庚何在，遥指星明处。\n壮心未已，莫言岁月迟暮。",""],["林花初放，捧霞觞、遥望敬亭山色。\n绕地珠绳箕宿转，光满谢公楼侧。\n阙里遗贤，石渠继世，曾讲诸儒易。\n廿年节度，一身高寄如客。\n督学齐鲁之间，湖西作镇，到处称申伯。\n天下山川游览遍，无数文章堆积。\n前遇吴关，今过瓯海，千里长相忆。\n才过甲子，为君重数畴昔。",""],["古鄮名家，彭城遗胄，所至公超成市。\n文效元和，诗以景龙为体。\n论学识、雅似颛孙，羡经术、精于杨起。\n第无如、弃世逃名，窜身长向瞿昙里。\n君家历世仕宦，况祖祢忠孝，名传黄纸。\n每辑残编，尚见泪痕如泚。\n寻欢会、偶在申江，叹孤游、有如樗里。\n又谁知、廿载相思，见君自此始。",""],["蜡尽春还，御河冰未泮，苑枝如沐。\n柳又生稊，双雉朝飞遫遫。\n花甲周时花烛启，宝帐妆成百福。\n由来原有，尚书三娶，东山名族。\n万年觞卜。\n道从此、天长地久，鸾弦终续。\n华帼披来，副髲有珈皆玉。\n池上歌添黄竹好，探去金桃再熟。\n那弃人笑，桃花洞里、刘郎初宿。",""],["已度三朝，忻逢四并，重对春波。\n看杨柳堤边，羽觞泛去，蔷薇洞口，油壁来过。\n北地贤宾，江南名士，人物加于晋永和。\n况杂坐、有美人相间，齐画双蛾。\n兴来酒泻银河。\n恰岩畔斜阳照绿萝。\n看环拥楸枰，目萦琢石，暗抛博具，指印纹螺。\n红袖香生，碧桃花放，此际春光可奈何。\n华灯起，见楼头纤月，徐上林柯。",""],["丁巳之春，我来沪渎，喜遇西园。\n念当日闻声，有如日下，今朝高会，竟在云间。\n江薛才华，庾徐藻采，所著佳文是偶言。\n笺题外，有吹蓬小令，折竹新篇。\n桃花初涨平川。\n又风起城头扑柳绵。\n自画阁摊书，谈深烛下，闲堂赠妓，肠断樽前。\n两次三番，风晨雨夕，是处相逢非偶然。\n沟头水，问东西会合，知在何年。",""],["凉月衔云，清风出谷，秋满人间。\n况出水芙蓉，诗篇绝丽，环溪修竹，酒兴将阑。\n子羽湖头，伯通桥畔，好友相思尝往还。\n扬舲去，见停来顾渚，望去吴关。\n横塘暑气将残。\n更微雨初过销夏湾。\n只陂有鸡栖，人归画舫，丘当虎去，寺在青山。\n畴昔曾游，石城深处，夜月清樽酹未干。\n歌词罢，向旗亭试听，可有双鬟。",""],["桃叶堤边，琵琶巷里，人字青溪。\n本博陵旧氏，愁窥燕幕，汾阳公子，共听乌啼。\n春寒愁又度，落尽东园几树梨。\n空回首，正江南烽火，塞北征鼙。\n相誓盈盈两地。\n奈仙源鸡犬望后都迷。\n况渚下书沉，误排雁影，章台人去，遗恨桃枝。\n隔巷空还系臂，便钿合金钗何处思。\n只蛮笺数幅，堪付新词。",""],["正河阳花满。\n秋水芙蓉，艳红如剪。\n赘婿淳于千里至，早已题诗齐苑。\n喜今日、光生银管。\n古署催妆开锦席，看一堂、紫罽铺香软。\n双盏暮，酌来浅。\n万条红烛烧将短。\n更庭前、几行画扇，遮来宛转。\n洗马文章当日事，乐令风流不远。\n况种得、蓝田琼琬。\n最羡今宵乘凤处，听秦台、几曲箫声缓。\n乌鹊到，喜何限。",""],["初过清明，才逾上巳，群贤高会南园。\n花岩接槛，洞口泻红泉。\n移得竹厨竹里，雕栏曲、杂坐金钿。\n擎觞至，红儿娇小，犹弄剪刀钱。\n楼前争作伎，枰楸壶竹，游咏依然。\n看玉钗纷絓，芗泽微传。\n醉煞兰亭旧侣，华灯外、新月纤纤。\n当筵赋，园如金谷，人似永和年。",""],["夏里开基，清河启郡，曾燃秘阁青藜。\n高斋寂静，夜听汝南鸡。\n仿佛神人告语，他年事、枕畔留题。\n长弓后，貂蝉奕叶，不数旧关西。\n黄梁炊未熟，翩翩蝴蝶，醒后多迷。\n托梨园象板，羽殿铢衣。\n千载凤鸾佳配，华茵暖，共酌玻瓈。\n听吹罢，一声长笛，无数彩云飞。",""],["琳畹琼妃，瑶台金母，当年曾驾蟾蜍。\n因披玉册，还御五云车。\n絓去庐江锦帨，闺房秀、早被霞裾。\n淮西路，春城千骑，夫婿上头居。\n五花裁作诰，香奁百琲，总是珍珠。\n看平头擎履，编齿吹竽。\n献得龙泥旧简，传经后、莫问居诸。\n闲相视，山桃片片，飞满玉床书。",""],["想此为图者。\n计生平、嵚嶙垒落，未经挥洒。\n富贵何时思量起，凡事尽如此画。\n纵满地、才源倾泻。\n但频年驱驰南北，到头末、抹却当时话。\n惟此剑，镇无价。\n从前只向车前挂。\n看中原、平沙万里，尽堪驰马。\n建礼门边题名后，便到晾鹰台下。\n且自解、双环重把。\n多少英雄今安在，遇甘蝇、莫折飞蓬射。\n穷与达，有时也。",""],["申江官舍，看桃花开后、柳丝如织。\n伯始风流才启宴，此夜刚逢寒食。\n烛下新妆，榴裙百褶，翻尽深红色。\n那堪小妓，病来歌舞无力。\n听莲漏将残，玉觞娇泻去，唇脂俱湿。\n夜雨初过花毯上，尚见翠钿狼藉。\n明日清明，来朝上巳，到处春堪惜。\n勾栏未散，慢言今夕何夕。",""],["撚髭无计，唤奚儿、长向水边山麓。\n蒲簟横陈将偃息，好句吟来断续。\n授册嫌频，开椷已缓，纸片纷零碌。\n游仙欹处，斲成五色文木。\n试启小篦中空，方襕连衽，大似青油袱。\n豹首鸡鸣俱不用，但取便便豕腹。\n梦去无论，醒来何事，栩栩相追逐。\n蝶庵诗就，此时午睡方足。",""],["夜堂听伎。\n正绛帐花垂，玉炉香细。\n莲炬光中，两两舞裙拖地。\n忽来金雀鸦鬟小，算才堪、琐儿年纪。\n栏边歌缓，油车暗里。\n翻然而至。\n便手把、金樽徐递。\n似嫩叶裁衣，幽兰吹气。\n病起迟来问取，小名尚未。\n风流京兆偏怜惜，道延年、女第如是。\n珊珊可念，何如竟唤，翩来为字。",""],["图画当年，正桃树、生花时节。\n有延州高士，酒颜方热。\n南浦风光何所似，西畴兴会由来别。\n恰闻人、洞口忆当年，频频说。\n舟过处，涵冰雪。\n花落尽，同榆荚。\n叹青芝白鹤，一时都绝。\n凡事总随风里絮，披图恍对云间月。\n幸前贤、手泽有传人，思来切。",""],["加豆得干腊，酾酒莫踟蹰。\n奈何置身岩谷其命在庖厨。\n不是笼驴炙豕，岂是牛犓鹅胛，此物本清虚。\n但束白茅去，安问绿蕉无。\n人一食，寿百岁，试何如。\n陈蕃设脠，相食慢作鲁公书。\n皮不必为藻币，肠不足为酒器。\n祗噬此些须，客座手能擗，何用倩麻姑。","加豆得乾腊，酾酒莫踟蹰。\n奈何置身岩谷其命在庖厨。\n不是笼驴炙豕，岂是牛犓鹅胛，此物本清虚。\n但束白茅去，安问绿蕉无。\n人一食，寿百岁，试何如。\n陈蕃设脠，相食慢作鲁公书。\n皮不必为藻币，肠不足为酒器。\n祗噬此些须，客座手能擗，何用倩麻姑。"],["兰渚亭边，莲河桥畔，高门乍启朝阳。\n单绂绕，彩云翔。\n云是揽予初度，争献仙人九酝觞。\n何限才名，今才四十，江左王郎。\n宫衣试着来长。\n有花下、新裁小乐章。\n回首京华，难兄执戟，同是东方。\n待补山公，正当典簿，努力功名看未央。\n他日乌衣，黑头还聚，重醉秋光。",""],["叹年华，看不尽，短亭花。\n更冬残、雪后停车。\n问谁相忆，寄来满幅是烟霞。\n分明指有，西陵渡口人家。\n沧洲近，知何处，空历遍，路途赊。\n念君也、留滞西平，思时便望，望时还见暮云遮。\n何年携我，向青山、麓碧湖涯。",""],["候属添丝，人方系缆，还逢高会南皮。\n闲堂夜来红烛，倒映金卮。\n争投博箸，妓帘不挂夏侯衣。\n频倾看，有葡萄酿，色似胭脂。\n夙昔只愁间阔，长从纸上，汗漫寄相思。\n今夕不知何夕，能预斯期。\n城头𬘘如五鼓，傍筵耿耿玉绳低。\n那堪与，曹刘沈谢，即席为词。","候属添丝，人方系缆，还逢高会南皮。\n闲堂夜来红烛，倒映金卮。\n争投博箸，妓帘不挂夏侯衣。\n频倾看，有葡萄酿，色似胭脂。\n夙昔只愁间阔，长从纸上，汗漫寄相思。\n今夕不知何夕，能预斯期。\n城头紞如五鼓，傍筵耿耿玉绳低。\n那堪与，曹刘沈谢，即席为词。"],["是南州高士，东海名家，西河旧里。\n茅屋数椽，纵亭台无几。\n墙外疏桐，檐前蔹蔓，到处成阴翳。\n人道蓬莱，逍遥散诞，不过如此。\n堪叹年时，燕齐吴楚，汗漫天涯，倦游知止。\n一任人间，似桑田海水。\n家有山妻，门无杂客，架上馀书史。\n安乐窝成，吾其从老，于是乡矣。",""],["淮南路。\n正值嵩阳归去。\n梨花晚、寒食初过，与汝东湖最深处。\n夜凉倾斗醑。\n听拨银筝无数。\n扶红袖、酒醒回时，长是城头鼓声曙。\n恨一别如雨。\n更南北东西，春还秋暮。\n许昌宫里留君住。\n任作赋繁台，题诗梁苑。\n何期此地复相遇。\n仿佛似前度。\n看舞。\n郡中署。\n便图遍屏山，歌残烛树。\n送君还上棠溪渡。\n望长淮千里，依然东注。\n那堪言别，况绿柳，渐飞絮。",""],["浮山如在眼，枞阳路、时望大江遥。\n想当日长瑜，曾为四友，今闻子季，仍号三高。\n从谁道，十年黄令阁，一别湛郎桥。\n湖上风光，全随蓬转，江南春信，半在梅梢。\n幸新来无恙，词中尚记得，醉卧干蕉。\n不道安成前度，良夜迢迢。\n自白鹭洲边，歌残纤月，红螺泽畔，酒散寒潮。\n试问梁园宾客，谁忆枚皋。",""],["最伤心处，是红亭、载酒上河桥。\n多少画栏杆外，杨柳正垂条。\n五两南风欲度，趁申江、几曲暮归潮。\n奈离筵人散，赠鞭情重，双泪落征袍。\n此地遨游堪恋，遍亭台、春意闹花梢。\n长载佳人油壁，深夜教吹箫。\n况值歌成南浦，也为君、重拨紫檀槽。\n且和歌一阕，问当前谁最销魂。",""],["春去久，怕逢客馆长昼。\n寄君书到正街头，濯枝雨后。\n那堪黄浦晚潮生，一帆吹下如溜。\n忆当日，方邂逅。\n按歌新记红豆。\n酒间移烛和予词，霎时草就。\n匆匆散去镇蹉跎，蜀葵花发时候。\n骊驹唱罢频把袖。\n看江流、如许颦皱。\n遥指垂杨渡口。\n更短亭、东上酒家，依旧欲放歌，何时还又。",""],["栀子开残，宜男采遍，日长深院啼莺。\n正荷衣被暑，裁剪初成。\n曾向慈恩寺里，春池浅、蘸笔题名。\n人争看，风流拔俗，第一吴兴。\n相惊。\n旧时八咏东阳，云起处、藻思纵横。\n恰衣盘雕锦，纸染红菱。\n羡煞丝纶世掌，凤池上、綷羽争明。\n悬弧处，堂前花发，海上云生。",""],["百尺冰荷可喜。\n况满壁、尽张罗绮。\n剪縠为栏，堆纱作树，不数米家山水。\n隔屏人指。\n道人在、隔花屏里。\n金粟玉虫累累。\n光到处、辘轳齐起。\n鸡戴珠竿，龙衔火籥，总是数条红紫。\n灯前且醉。\n看灯影、照人何几。",""],["何来采药仙源。\n问当年。\n云是伏波横海、旧登坛。\n麟阁里。\n沧洲意。\n任相看。\n一似桃花流水，向人间。",""],["合欢成被。\n铺就鹧鸪单枕腻。\n豹髓全融。\n肯负馋灯入夜红。\n壁光如曙。\n翻恨袖梢遮不住。\n收却残书。\n何用掀翻垒算珠。",""],["玉栏长夏金塘里。\n轩窗四面荷风起。\n菀蒻织花纹。\n盘盘散绿云。\n柳帷褰未闭。\n隔水窥人至。\n待起整钗钿。\n郎今未可前。",""],["乐陵台下看红药。\n底处曾相谑。\n苔衣掩尽石栏花。\n辜负东园杏子数枝斜。\n紫龙髯拂珊瑚柄。\n秃袖红相映。\n郎身岂有赭头蝇。\n暂作吴宫点墨白螺屏。",""],["朱阀迎齐女，金箱贮楚云。\n高阁傍斜曛。\n阿谁居阁上，济阳君。",""],["蓬山小吏，上清旧籍，曾控九仙朱鲤。\n若非花下认前身，几负却、双成久矣。\n枫亭何在，治装东去，请食宋家荔子。\n纵然置驿未能通，也胜看、忠州画里。",""],["两地烽烟天一隅。\n蒋山西尽处、莫愁湖。\n谁言流水隔姑苏。\n春潮上，中有一双鱼。\n缄处印含朱。\n泽蒲裁作线、界蜘蛛。\n簪花小字画来疏。\n凭偷看，传作窦家书。",""],["乃与阿潘同住。\n何故。\n花月映江潭。\n问谁还宿普明龛。\n参么参。\n参么参。",""],["长向花前摊女史。\n一榻自安花蔓里。\n尽教春去病还留，捐药饵。\n弄笔底。\n全似建安女博士。\n阶下稚童摇葛藟。\n满院月明清似水。\n慢言蓁莽辟除难，君意气。\n且已耳。\n泛扫请从一室始。",""],["齐代远，空吟乘马篇。\n真珠钏，解作算商钱。",""],["锦闼闲心，绿窗幽兴，得句相调。\n何意东园，杏花开遍，又是春朝。\n丁娘且索挥毫。\n甚处见、欢情久要。\n几阕清词，数行细字，一幅生绡。",""],["且慢记。\n琴心当日何似。\n只看绿绮绕孤桐，素丝未理。\n高山流水有谁听，离怀此际如寄。\n况花底，楸树子。\n旧枰在断垣里。\n空留遗挂紫檀心，琢成累累。\n横横直直试踌躇，几曾闲却纤指。\n是中意，诚莫己。\n良人惜未能此。\n追忆尔时佳致。\n或庶几、鼓瑟湘灵堪比。\n何况围棋张良娣。",""],["不辨黄鹂能却妒，临溪且采茵陈。\n文园能聘茂陵人。\n君心难问取，我见也怜生。\n今日秦淮相接处，当年桃树桃根。\n门前流水记前因。\n曼陀花下影，同拜绣幢身。",""],["采菱歌罢，见紫角新翻，绿苞初卸。\n问灌湖前汊。\n女伴恁来迟，停船相迓。\n红袖风吹，刚一望、夕阳西下。\n唤侍儿、慢卷朱竿，菱刺又牵罗帕。\n举棹去，南浦夜。\n叹洲尽含霜，湾名销夏。\n此事思如乍。\n待旧约重寻，流光不借。\n几度秋风，看浩浩、长淮东泻。\n好愁人、翠藻清涟，犹是参差如画。","采菱歌罢，见紫角新翻，绿苞初卸。\n问灌湖前汊。\n女伴恁来迟，停船相迓。\n红袖风吹，刚一望、夕阳西下。\n唤侍儿、慢捲朱竿，菱刺又牵罗帕。\n举棹去，南浦夜。\n叹洲尽含霜，湾名销夏。\n此事思如乍。\n待旧约重寻，流光不借。\n几度秋风，看浩浩、长淮东泻。\n好愁人、翠藻清涟，犹是参差如画。"],["前湖十里，芙蓉到门，皦皦明如练。\n波光云映，芦埼鹭下，宛然一片。\n湘葩含铅，青房滤粉，素珠成串。\n便采莲红女，绛裙千褶，遮叶住，有谁见。\n只为社中人散。\n倚遥空、削成难辨。\n赤栏桥子，无端愁把，碧天遮断。\n月下飞香，霜前落叶，容华将变。\n但秋衣未制，剪来朵朵，不须染茜。",""],["但秋风、有谁还忆，夏瓜冬菜春韭。\n儿家住近横塘曲，长在柳姑庙后。\n相邀取，借邻女花竿、挑起红丝浏。\n摘来盈缶。\n任九月猪毛，百茎雉尾，总贳一壶酒。\n品瀜甚、慢说白如琼玖。\n下将盐豉烹就。\n钿头钗脚难形似，只顾流匙在口。\n还念否。\n料拾鲙分鲭、未是和羹手。\n踌躇良久。\n便羊酪能胜，龙酥堪敌，归去也何有。",""],["水咽铜龙漏断时。\n金铺青琐外、蜿双垂。\n疏桐玉露滴阶墀。\n银床静，缭绕辘轳丝。\n袍裤扫鸾帷。\n九微花报喜、晚风吹。\n额黄催卸却迟迟。\n珠帘下，犹望月如眉。",""],["籊籊银钩挂竹竿。\n珊瑚车子铁连环。\n莲叶渡，蓼花滩。\n烟波淼淼几时还。",""],["菰叶菱根罥网丝。\n曲榔单板立鸬鹚。\n前浦约，隔江期。\n江长浦阔暝归迟。",""],["襡襣对裆一抹。\n帕复两头八撮。\n抱腰身，牵带孔。\n持带孔。\n卸到烛光浮动。\n暖烟浓。\n泻轻红。",""],["棋底红编履子。\n低?砑罗如水。\n夜填时，重解袜。\n重束袜。\n坐久欲填还脱。\n忽见月如钩。\n使人愁。",""],["风起莲江绉绿罗。\n并船归唱采莲歌。\n画屏只见金㶉鶒。\n不信双双水鸟多。","风起莲江绉绿罗。\n并船归唱采莲歌。\n画屏只见金鸂鶒。\n不信双双水鸟多。"],["细萍点点钉花船。\n荇线飘飘缚画竿。\n折得小莲羞并蒂。\n红靴钩入锦裙边。",""],["十二峰前十二滩。\n嘈嘈急水渡来难。",""],["瞿塘看似桃花马，只少装成八宝鞍。",""],["锦江春水白浮浮。\n担水娇娘踏水愁。",""],["洗面好来清溜里，洗足当寻浊浪头。",""],["当日虎符初下处，桃花开满山阿。\n万层绛帐覆来多。\n驱盐投峻阪，拔羽出虞罗。\n一自龙山高会后，春江曾哭曹娥。\n天南万里到牂柯。\n帝乡把盏去，锦里盼车过。",""],["谁料十年星纪换，延津还泛仙槎。\n江淮转运使如何。\n金笳开越峤，绣棨动吴波。\n幸得闲堂仍聚首，清樽频把玻㼈。\n刘郎前度喜重过。\n公门桃树老，犹有旧枝柯。",""],["翠帐寒生香篆袅。\n斜亸腰支，一向和衣抱。\n暮雨帘栊如欲晓。\n罗裙半展潇湘绕。\n笑吐丁香檀晕小。\n雾湿花房，杨柳三眠了。\n唤起凤屏灯悄悄。\n试看鬟影松多少。",""],["星移帆影月移沙。\n秋思谁家。\n别时不敢分明语，蹙春山、暗损韶华。\n又是中秋时候，西风几阵归鸦。\n相思难遣梦交加。\n水阔山斜。\n尊前常恨天涯远，况如今、真个天涯。\n若问重来何日，待伊归向窗纱。",""],["马迹车尘，甚今生、还能到我。\n更多少、鸿离鹤怨，浪淘风簸。\n酒力不禁归梦觉，鬓丝都是羁愁做。\n冷秋心、梁燕北来时，能传么。\n穷愁恨，眉峰锁。\n风尘泪，征衫涴。\n尽寂寥前事，算来都可。\n小句成时看墨浅，新妆竟了怜花妥。\n只如今、和影对新蟾，人三个。",""],["别袂偷分，盼不到、片帆香陌。\n正雨过、乱红飞尽，水云凝碧。\n杨柳漫牵歌意绪，苎萝多少愁踪迹。\n怕羁心、重对旧亭台，伤今昔。\n花影昼，蟾阴夕。\n重执手，何时得。\n奈渚蒲樯燕，助人行色。\n纵是梦来应有恨，情知留得元无益。\n算人生、双鬓几时青，成抛掷。","别袂偷分，盼不到、片帆香陌。\n正雨过、乱红飞尽，水云凝碧。\n杨柳漫牵歌意绪，苧萝多少愁踪迹。\n怕羁心、重对旧亭台，伤今昔。\n花影昼，蟾阴夕。\n重执手，何时得。\n奈渚蒲樯燕，助人行色。\n纵是梦来应有恨，情知留得元无益。\n算人生、双鬓几时青，成抛掷。"],["生老樊川，水嬉不尽当年兴。\n问十里、湖光何处，画桡相并。\n金管风多听又失，珠帘雨细看难定。\n算陈思、著眼不曾多，惊鸿影。\n凭舷意，应谁省。\n抛醉缬，朱榴映。\n尽繁华都付，藕丝风领。\n一簇愁红空极浦，半湖柔绿浮归艇。\n正高楼、人在柳阴中，烟光暝。",""],["细柳拖烟，织就乱丝多少。\n怪掷处、金梭偏小。\n一枝飞绕。\n数声啼了。\n涩新簧、薄寒犹峭。\n娇音断续，短梦绿窗惊晓。\n弄春阴、翠翻红笑。\n曲池人悄。\n落花风袅。\n又衔来、一番残照。",""]]});
